}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 
        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 
        p.vx = Math.cos(angle) * dist; p.vy = Math.sin(angle) * dist; p.vz = vZ;
        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff'; p.size = 64 * scale; 
        p.type = 'SPRITE'; p.image = img;
        p.rotation = Math.random() * Math.PI * 2; p.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(p);
    };

    const baseColor = '#52525b';
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 50 + Math.random() * 100; 
        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor; p.size = 10 + Math.random() * 10;
        p.type = 'SHARD'; p.rotation = angle; p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    // Spawn Icon (Head)
    spawnSprite(assets.icon, 0.6, 70, 300);   

    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40;
        const angle = Math.random() * Math.PI * 2;
        const speed = 50 + Math.random() * 150;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 150 + Math.random() * 150;
        p.life = 2.0; p.maxLife = 2.0;
        p.color = coreColor; p.size = 6 + Math.random() * 6;
        p.type = 'DEBRIS'; 
        p.rotation = Math.random() * Math.PI; p.vRotation = (Math.random()-0.5) * 15;
        system.state.particles.push(p);
    }
    addDecal(system, x, y, '#000'); 
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 
    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 
        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 20 + Math.random() * 30;
        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; p.delay = 0;
        system.state.particles.push(p);
    }
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'PROJECTILE_HIT': 
                this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05); // Minimal impact
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                // New: High Impact Cast Break
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); // High trauma to feel the "SNAP"
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     // Very slight nudge on Ult finish
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.1); // Minimized from 0.2

            // 1. FACTION RITUAL
            if (faction === Team.BLUE) {
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 1.5, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 1.2);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            // 2. AOE RIPPLE
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(centerHex, h);
                        const delay = dist * 0.08; 

                        VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, color, faction, delay);

                        if (skill.ccType === 'DOT' || skill.ccType === 'SILENCE') {
                            VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 4.0, delay);
                        }
                    }
                });
            } else {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }
        } else {
            // Normal Skill Logic
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affected = HexUtils.range(centerHex, radius);
                VFXSpawners.addDecal(vfx, event.pos.x, centerVisualY, color);

                affected.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(centerHex, h);

                        if (dist <= radius) {
                            if (Math.random() < 0.6) { 
                                VFXSpawners.addImpact(vfx, tilePos.x, tileVisualY, 0, color, 'RING', 0.4);
                            }
                            if (skill.ccType === 'DOT') {
                                VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 3.0, dist * 0.05);
                            }
                        }
                    }
                });
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex, MovementType, LogActionType } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS, LOG_COLORS } from "../constants";

// Core Entities
import { Agent, SpecialVisualStatus } from "./core/Agent";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { EventBus } from "./events/EventBus";
import type { GameRenderer } from "./renderer";

export { Agent, SpecialVisualStatus };

// Constants
export const VICTORY_PHASE_DURATION = 0.5; // Reduced to 0.5s for snappier finish

export class GameEngine {
    public agents: Agent[] = [];

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;

    // Time & Speed Control
    public timeScale: number = 1.0;
    public targetTimeScale: number = 1.0; // New: For smooth slow-mo transitions

    public battleTime: number = 0;
    public mapVersion: number = 0; 

    // Finishing Sequence State
    public isFinishing: boolean = false;
    public victoryTimer: number = 0;
    public winningTeam: Team | null = null;

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.isFinishing = false;
            this.winningTeam = null;
            this.targetTimeScale = 1.0;
            this.timeScale = 1.0;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.isFinishing = false;
        this.winningTeam = null;
        this.targetTimeScale = 1.0;
        this.timeScale = 1.0;
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });
        this.combat.projectiles = []; 
        this.events = []; 
        this.battleTime = 0;
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.combat.projectiles = [];
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    tick(dt: number) {
        if (!this.isRunning) return;

        // 1. Time Dilation Logic (Smooth Slow Mo)
        if (Math.abs(this.targetTimeScale - this.timeScale) > 0.01) {
            this.timeScale += (this.targetTimeScale - this.timeScale) * 5.0 * dt; // Soft lerp
        } else {
            this.timeScale = this.targetTimeScale;
        }

        this.events.length = 0;
        this.updateDirector(dt);

        // 2. Victory Check Logic
        if (this.isFinishing) {
            this.victoryTimer -= dt;
            // Continue animating death falls and particles
            this.updateEntities(dt);

            if (this.victoryTimer <= 0) {
                this.stop();
                // Reset timescale for next run
                this.targetTimeScale = 1.0;
                this.timeScale = 1.0;
                this.bus.emit('GAME_OVER', { winner: this.winningTeam });
            }
            return;
        }

        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }

        if ((blue === 0 && red > 0) || (red === 0 && blue > 0)) { 
            // Enter Finishing Sequence
            this.isFinishing = true;
            this.winningTeam = blue === 0 ? Team.RED : Team.BLUE;
            this.victoryTimer = VICTORY_PHASE_DURATION; // Use Constant
            // Note: The slow motion trigger (0.1x) happens in SkillResolutionSystem on the lethal hit.
            // Here we ensure it doesn't stay frozen forever, drifting back up to 0.4x for the fall.
            this.targetTimeScale = 0.4; 
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;
            this.movement.updatePhysics(a, dt, this);
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.status.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        // If current target is dead, force reset
        if (this.directorTargetId) {
            const current = this.agents.find(a => a.id === this.directorTargetId);
            if (!current || current.hp <= 0) {
                this.directorTimer = -1;
            }
        }

        if (this.directorTimer <= 0) {
            let candidates: Agent[] = [];
            let ultCasters: Agent[] = [];

            // Single loop to find candidates (Avoids array allocation of .filter)
            for (const a of this.agents) {
                if (a.hp > 0) {
                    candidates.push(a);
                    if (a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT') {
                        ultCasters.push(a);
                    }
                }
            }

            if (candidates.length > 0) {
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0; // Stay longer on Ult
                } else {
                     this.directorTargetId = candidates[Math.floor(Math.random() * candidates.length)].id;
                     this.directorTimer = 3.0;
                }
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 
            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, 'CAST', '詠唱', targetName, `開始引導 ${a.skills[i]!.name} (需 ${a.skills[i]!.cast} 秒)`);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    log(agent: Agent | null, typeOrAction: LogActionType | string, actionNameOrTarget: string | null, detailOrTargetInfo: string, legacyDetail?: string) {
        const time = this.battleTime.toFixed(1);
        let actionType: LogActionType = 'SYSTEM';
        let actionName = 'Action';
        let targetInfo = '';
        let detail = '';
        let color = LOG_COLORS.SYSTEM;

        const isLegacy = !this.isLogActionType(typeOrAction);

        if (isLegacy) {
            const rawAction = typeOrAction as string;
            actionName = rawAction;
            targetInfo = actionNameOrTarget || '';
            detail = detailOrTargetInfo;
            if (rawAction === '死亡') { actionType = 'DEATH'; color = LOG_COLORS.DEATH; }
            else if (rawAction === '放逐結束') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '中斷') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '命中') { actionType = 'HIT'; color = LOG_COLORS.HIT; }
            else { actionType = 'SYSTEM'; }
        } else {
            actionType = typeOrAction as LogActionType;
            actionName = actionNameOrTarget || '';
            targetInfo = detailOrTargetInfo || '';
            detail = legacyDetail || '';
            switch(actionType) {
                case 'MOVE': color = LOG_COLORS.MOVE; break;
                case 'CAST': color = LOG_COLORS.CAST; break;
                case 'HIT': color = LOG_COLORS.HIT; break;
                case 'HEAL': color = LOG_COLORS.HEAL; break;
                case 'DECISION': color = LOG_COLORS.DECISION; break;
                case 'DEATH': color = LOG_COLORS.DEATH; break;
                case 'CC': color = LOG_COLORS.CC; break;
                default: color = LOG_COLORS.SYSTEM; break;
            }
        }

        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            turn: Math.floor(this.battleTime * 10),
            agentId: agent?.id || 'SYSTEM',
            team: agent?.team,
            location: agent ? `(${agent.q},${agent.r})` : 'global',
            actionType: actionType,
            actionName: actionName,
            targetInfo: targetInfo,
            detail: detail,
            visualColor: color,
            action: actionName,
            target: targetInfo,
            loc: agent ? `@(${agent.q},${agent.r})` : ''
        };

        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }

    private isLogActionType(val: any): val is LogActionType {
        return ['MOVE','CAST','HIT','DECISION','DEATH','SYSTEM','HEAL','CC'].includes(val);
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // Speed adjusted: 3.0 for ~0.33s transitions (Snappy!)
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 3.0);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - God View Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">

                        {/* Winner Label */}
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>

                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-4 rounded-xl text-lg font-bold bg-white/5 hover:bg-white/10 border-white/20 text-slate-200 shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Restart className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>

                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showUnitDetail, setShowUnitDetail] = useState(false);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    // This allows the engine to drive state changes without prop drilling
    useEffect(() => {
        const engine = engineRef.current;

        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            // If in showcase, auto-restart flow logic is moved here or kept in loop?
            // Actually, hooks can read state better.

            // Logic moved from old onWin prop:
            if (engine.isRunning) engine.stop(); // Ensure stopped

            // Note: We access current value of isShowcaseMode via ref if needed, or rely on state updates
            // Since this effect closes over initial state, we need to be careful.
            // Better to trigger visual updates here.
            setIsPlaying(false);
        };

        engine.bus.on('GAME_OVER', handleGameOver);

        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic (Reactive to winner state)
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            // Speed up the showcase loop significantly
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 500); // 0.5s fade in (syncs with map flying in)
                }, 500); // 0.5s fly out
            }, 1000); // 1.0s dwell on victory (slow mo)
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        setShowUnitDetail(false);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        // Fisher-Yates shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    // Initial Start
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    // Stats Loop
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    // Time Scale Sync
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    // --- HANDLERS ---

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        // Quick Spawn logic for manual random
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);

        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        // Reuse random logic but start playing immediately
        handleRandomBattlefield();

        // Need to wait a tick for agents to be ready? 
        // handleRandomBattlefield runs synchronously, so we can just play.
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;

        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }

            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
        if (!a) setShowUnitDetail(false);
    };

    // --- RETURN ---
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB,
            showUnitDetail, transitionPhase, showFactionWarning
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, 
            setShowUnitDetail, setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel, // New action
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, // Manual trigger shim
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); // FIX: Explicitly start engine
                setIsPlaying(true); 
            }
        }
    };
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: GAME OVER BLUR (Frosted Glass) ---
        // Enhanced Logic: Fade out blur during new match entry
        let blurAmount = 0;

        if (engine.isFinishing) {
            // Ramping Up (Active Victory Phase)
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // Bridge Gap: Game finished but showcase loop hasn't reset yet
            blurAmount = 1.0;
        }

        // Transition Overrides
        if (this.transitionPhase === 'OUT') {
            // Leaving: Keep blurred
            blurAmount = 1.0;
        } else if (this.transitionPhase === 'IN') {
            // Entering: Fade Out (1.0 -> 0.0)
            blurAmount = 1.0 - this.transitionT;
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Draw Trail ---
        // Using the pre-calculated visual trail points in op.pTrail
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = op.pColor;

            // Trail Width Logic: Tapering
            // We iterate through the visual points (Screen Space relative to map origin)

            // Draw the line strip
            ctx.beginPath();

            const trail = op.pTrail;
            if (trail.length > 0) {
                // The first point in trail array is the HEAD (newest)
                ctx.moveTo(trail[0].x, trail[0].y);
                for(let i=1; i<trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
            }

            // Style: Fade out
            const grad = ctx.createLinearGradient(trail[0].x, trail[0].y, trail[trail.length-1].x, trail[trail.length-1].y);
            grad.addColorStop(0, op.pColor); // Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Tail

            ctx.strokeStyle = grad;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();

            // Inner Core Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        // Simple blob shadow on ground
        // We use pVisShadowY stored in op
        const shadowAltitude = op.pVisShadowY - op.pVisY; // Difference between ground and air

        // Don't draw shadow if too low (to avoid clipping with sprite)
        // Or if really high, shadow fades
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            // Scale shadow based on height (higher = smaller/blurrier)
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);

            ctx.scale(shadowScale, shadowScale * 0.5); // Flattened ellipse
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Procedural Noise function
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number // NEW: Time injection for animation
    ) {
        const BASE_THICKNESS = 12; 
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.7, baseColor);
            grad.addColorStop(1, '#020617');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // Layer Lines
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        // --- BASE MATERIAL ---
        // Static Gradient for base material to ensure solid look
        const topGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- DYNAMIC OVERLAYS (Texture 2.0) ---
        if (type === 'MAGMA') {
            // OPTIMIZATION: Replaced per-tile Gradient with flat fill.
            // Creating RadialGradient 100+ times per frame kills FPS.
            const pulse = Math.sin(globalTime * 1.5 + x * 0.1 + y * 0.1); 

            // Only draw heat if pulse is high
            if (pulse > 0.2) {
                // Map pulse (-1 to 1) to alpha (0 to 0.25)
                const heatAlpha = (pulse - 0.2) * 0.3; 
                ctx.fillStyle = `rgba(239, 68, 68, ${heatAlpha})`; // Flat Red Overlay
                ctx.fill();
            }

        } else if (type === 'ICE') {
            // FIX: Ice is now a glossy surface with a moving specular reflection, not a flashing strobe
            // Specular band moving across the tile
            const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;

            ctx.save();
            ctx.clip(); // Clip to hex

            const specGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
            // Gentle white/cyan reflection
            specGrad.addColorStop(0, 'rgba(255, 255, 255, 0)');
            specGrad.addColorStop(0.45, 'rgba(255, 255, 255, 0)');
            specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.2)'); // Subtle highlight
            specGrad.addColorStop(0.55, 'rgba(255, 255, 255, 0)');
            specGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');

            ctx.translate(bandPos * 0.5, 0); // Move reflection
            ctx.fillStyle = specGrad;
            ctx.fill();
            ctx.restore();
        } 

        // 3. Rim Light
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;

        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];

        ctx.moveTo(x + c4.x, y - topY + c4.y);
        ctx.lineTo(x + c3.x, y - topY + c3.y);
        ctx.lineTo(x + c2.x, y - topY + c2.y); 
        ctx.stroke();

        ctx.globalAlpha = 1.0;

        // 4. Subtle Outline
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.moveTo(x + HEX_CORNERS[2].x, y - topY + HEX_CORNERS[2].y);
        ctx.lineTo(x + HEX_CORNERS[1].x, y - topY + HEX_CORNERS[1].y);
        ctx.lineTo(x + HEX_CORNERS[0].x, y - topY + HEX_CORNERS[0].y);
        ctx.lineTo(x + HEX_CORNERS[5].x, y - topY + HEX_CORNERS[5].y);
        ctx.lineTo(x + HEX_CORNERS[4].x, y - topY + HEX_CORNERS[4].y);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;

        const n = noise(q, r);
        const time = performance.now() / 1000;

        if (type === 'MAGMA') {
            // Charred Cracks (Darker, less glowing)
            const pulse = 0.5 + Math.sin(time + n * 10) * 0.5;

            // OPTIMIZATION: Removed globalCompositeOperation 'multiply'.
            // Switching blend modes per-tile is expensive. Use alpha-blended dark line instead.
            ctx.strokeStyle = 'rgba(40, 5, 5, 0.7)'; // Dark crack
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5);
            ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3);
            ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            // Only occasional glowing ember spots
            if (pulse > 0.8) {
                // OPTIMIZATION: Removed globalCompositeOperation 'lighter'.
                // Just draw bright red on top.
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = (pulse - 0.8) * 3; 
                ctx.beginPath(); ctx.arc(cx - 5, cy - 2, 2, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'VOID') {
            // ENHANCED: Digital Circuitry
            ctx.globalAlpha = 0.3;

            // Static Grid Node
            if (n > 0.3) {
                ctx.fillStyle = '#38bdf8';
                ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();

                // Connecting lines
                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 1;
                ctx.beginPath();
                if (n > 0.6) { ctx.moveTo(cx, cy); ctx.lineTo(cx + 15, cy - 8); }
                if (n < 0.4) { ctx.moveTo(cx, cy); ctx.lineTo(cx - 15, cy + 8); }
                ctx.stroke();
            }

            // Moving Data Packet
            const packetTime = (time * 0.5 + n) % 2; // 2 second loop
            if (packetTime < 1.0) {
                ctx.globalAlpha = 1.0 - packetTime; // Fade out
                ctx.fillStyle = '#bae6fd';
                const px = cx + (Math.cos(n * 10) * 20 * packetTime);
                const py = cy + (Math.sin(n * 10) * 10 * packetTime); // Squashed Y
                ctx.fillRect(px, py, 2, 2);
            }

        } else if (type === 'FOREST') {
            // ENHANCED: Moving Grass
            ctx.globalAlpha = 0.6;
            const tufts = Math.floor(n * 3) + 2;

            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;

                // Wind Sway Logic
                const wind = Math.sin(time * 2 + cx * 0.05 + i) * 3;

                ctx.beginPath();
                // Blade 1
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind * 1.5, cy + oy - 8);
                // Blade 2
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox + 2 + wind, cy + oy - 5, cx + ox + 4 + wind * 1.5, cy + oy - 7);

                ctx.lineWidth = 1.5;
                ctx.strokeStyle = i % 2 === 0 ? '#4ade80' : '#22c55e'; // Varied greens
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            // Subtler scratches
            ctx.globalAlpha = 0.3;
            ctx.fillStyle = '#fff';
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2);
                ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4);
                ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();
            }

        } else if (type === 'DESERT') {
            // ENHANCED: Moving Sand Ripples
            ctx.globalAlpha = 0.2;
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;

            // Scroll ripples
            const offset = (time * 5) % 20; 

            ctx.beginPath();
            // Draw 2 ripples
            for(let i=0; i<2; i++) {
                const yBase = cy - 10 + i * 15;
                const shift = offset + (n * 20); // Random offset per tile
                const xStart = cx - 15 + (shift % 10);

                ctx.moveTo(xStart, yBase);
                ctx.quadraticCurveTo(xStart + 10, yBase - 3, xStart + 20, yBase);
            }
            ctx.stroke();
        }

        ctx.restore();
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

// COLORS
const COL_PURPLE = '#8b5cf6'; // Violet-500
const COL_GOLD = '#facc15';   // Yellow-400
const COL_CRIMSON = '#ef4444'; // Red-500

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    // We are at Ground Level (0,0) in the scaled context.
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    // Rotating Rune Ring - Clear indication of ground position
    ctx.save();
    ctx.scale(1, 0.58); // Isometric flat on ground
    ctx.rotate(t * 0.5);

    // Outer dashed ring
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    // Only visible if unit is airborne to show connection
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); // Fade out near unit feet

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        // Draw Main Tether Line
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        // Draw Moving Energy Pulses up the tether
        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; // 0 to 1, faster speed
            const px = feetX * p;
            const py = feetY * p;

            // Draw small horizontal dash/disk traveling up
            // Scale based on height to simulate perspective
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); // Faster spin for thrusters

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    // 3 Arcs for stability look
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; // Flicker
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    if (skill.tag === 'ULT') {
        drawUltimateChantVFX(ctx, agent, t);
        return;
    }

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

// 🌀 NEW: ULTIMATE CHANT VFX (Body)
export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const factionColor = agent.team === Team.BLUE ? COL_GOLD : COL_CRIMSON;
    const mainColor = COL_PURPLE;

    ctx.save();

    // 1. Atmosphere (Localized Darkening)
    // Draw a large dark vignette behind the unit to make runes pop
    const vignetteSize = 120 * progress;
    const vignette = ctx.createRadialGradient(0, -40, 20, 0, -40, vignetteSize);
    vignette.addColorStop(0, 'rgba(0,0,0,0)');
    vignette.addColorStop(1, 'rgba(0,0,0,0.6)');

    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = vignette;
    ctx.beginPath(); ctx.arc(0, -40, vignetteSize, 0, Math.PI*2); ctx.fill();

    // 2. Implosion (Energy Gathering)
    // Particles moving from radius inwards to chest
    ctx.globalCompositeOperation = 'lighter';
    const pCount = 16;
    const radius = 80;

    for(let i=0; i<pCount; i++) {
        const speed = 2.0 + progress * 2.0; // Speed up as cast finishes
        const offset = i * (1/pCount);
        const lifetime = (t * speed + offset) % 1.0;

        // lifetime 0 = spawn at edge, 1 = hit center
        // Reverse for implosion: spawn far (p=0), move in (p=1)
        const curDist = radius * (1 - Math.pow(lifetime, 2)); // Ease in
        const angle = i * (Math.PI * 2 / pCount) + t + (progress * 5); // Spiral in

        const px = Math.cos(angle) * curDist;
        const py = Math.sin(angle) * curDist - 40; // Center on chest (-40)

        const size = (2 + progress * 3) * lifetime; // Grow slightly as they condense
        const alpha = Math.sin(lifetime * Math.PI); 

        ctx.fillStyle = i % 2 === 0 ? factionColor : mainColor;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(px, py, size, 0, Math.PI*2); ctx.fill();

        // Trail
        if (curDist > 10) {
            ctx.strokeStyle = ctx.fillStyle;
            ctx.lineWidth = size * 0.5;
            ctx.beginPath();
            ctx.moveTo(px, py);
            const tailX = Math.cos(angle - 0.2) * (curDist + 15);
            const tailY = Math.sin(angle - 0.2) * (curDist + 15) - 40;
            ctx.lineTo(tailX, tailY);
            ctx.stroke();
        }
    }

    // 3. Core Overload (Bright center glow)
    // OPTIMIZATION: Removed shadowBlur, replaced with Radial Gradient
    const pulse = 1 + Math.sin(t * 30) * 0.2;
    ctx.globalAlpha = 0.8 * progress;

    const coreGrad = ctx.createRadialGradient(0, -40, 2, 0, -40, 15 * pulse);
    coreGrad.addColorStop(0, '#ffffff');
    coreGrad.addColorStop(0.4, factionColor);
    coreGrad.addColorStop(1, 'rgba(0,0,0,0)');

    ctx.fillStyle = coreGrad;
    ctx.beginPath(); ctx.arc(0, -40, 15 * pulse, 0, Math.PI*2); ctx.fill();

    ctx.restore();
}

// 🌀 NEW: ULTIMATE GROUND CIRCLE (Replaces AssetManager circle)
export function drawUltimateGroundCircle(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, t: number, progress: number) {
    const pulse = 1 + Math.sin(t * 5) * 0.05;
    const baseSize = 70 * pulse; 

    ctx.save();
    ctx.translate(x, y);
    ctx.scale(1, 0.58); // Isometric projection
    ctx.globalCompositeOperation = 'lighter';

    // 1. Outer Ring (Slow Rotate)
    ctx.save();
    ctx.rotate(t * 0.5);
    ctx.strokeStyle = COL_PURPLE;
    ctx.setLineDash([20, 10]); // Runes

    // OPTIMIZATION: Fake Glow (Double Stroke)
    ctx.lineWidth = 4;
    ctx.globalAlpha = (0.6 + progress * 0.4) * 0.3; // Low alpha for width
    ctx.beginPath(); ctx.arc(0, 0, baseSize, 0, Math.PI*2); ctx.stroke();

    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6 + progress * 0.4;
    ctx.stroke();
    ctx.restore();

    // 2. Inner Ring (Fast Counter-Rotate)
    ctx.save();
    ctx.rotate(-t * 1.5);
    ctx.strokeStyle = COL_GOLD; // Gold core for contrast
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.8;
    ctx.setLineDash([5, 15, 2, 10]); // Complex pattern
    ctx.beginPath(); ctx.arc(0, 0, baseSize * 0.7, 0, Math.PI*2); ctx.stroke();
    ctx.restore();

    // 3. Central Geometry (Triangle/Square pulse)
    ctx.save();
    ctx.rotate(t);
    ctx.globalAlpha = 0.3 * progress;
    ctx.fillStyle = color;
    const r = baseSize * 0.5 * progress;
    ctx.beginPath();
    for(let i=0; i<3; i++) {
        const a = i * (Math.PI*2/3);
        ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM (Encasing the unit)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); // Center of body

        // Draw Hexagonal Prism
        const w = 30;
        const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        // Back Faces
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        // Front Faces (Glassy)
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); // Top Tip
        ctx.lineTo(w + 5, -h + 10);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h + 10); // Bottom Tip
        ctx.lineTo(-w, h);
        ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath();
        ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE (Rotates around unit)
    // MUTUALLY EXCLUSIVE: Only draw if NOT Poly'd and NOT Stasis
    if (agent.banished && agent.visualStatus !== 'POLYMORPH' && agent.visualStatus !== 'STASIS') {
        ctx.translate(0, -30); // Body center

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // Vertical Bars orbiting (Simulated 3D Cylinder)
        const bars = 5;
        const radius = 25;
        const height = 50;

        for(let i=0; i<bars; i++) {
            // Rotate bars over time
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); // Depth

            // Perspective scale
            // const scale = 1 + z * 0.1;
            const alpha = 0.5 + (z + 1) * 0.25; // Fade back bars

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(x, -height);
            ctx.lineTo(x, height);
            ctx.stroke();

            // Runes on bars
            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Top and Bottom Rings
        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); // Isometric
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);

        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;

        const count = 5;
        const radius = 25;

        // Orbiting Stars
        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            // 3D Orbit: Y is squashed
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            // Z-sort simulation: if sin(angle) > 0, it's in front
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            // OPTIMIZATION: Removed shadowBlur. Added fake glow circle.
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();

            // Fake Glow
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();

            ctx.restore();
        }
    }

    // 4. SILENCE - FLOATING RUNE SEAL
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);

        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';

        // OPTIMIZATION: Fake glow via multi-pass stroke instead of shadowBlur
        ctx.globalCompositeOperation = 'lighter';

        const drawRune = (width: number, alpha: number) => {
            ctx.lineWidth = width;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.rect(-15, -10, 30, 20);
            ctx.fill();
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
            ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
            ctx.stroke();
        };

        drawRune(4, 0.3); // Glow pass
        drawRune(2, 1.0); // Core pass
    }

    // 5. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    // OPTIMIZATION: Fake glow strokes instead of standard stroke
    const mainCol = agent.team === Team.BLUE ? '#60a5fa' : '#f87171';
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = mainCol;

    // Outer Glow
    ctx.lineWidth = 4;
    ctx.globalAlpha = alpha * 0.4;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.stroke();

    // Inner Core
    ctx.lineWidth = 2;
    ctx.globalAlpha = alpha;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.stroke();

    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.fill();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS (Fixes "Floating" feeling) ---
        // We are currently at [x, GroundY - Z].
        // To draw shadow at GroundY, we must translate down by Z.
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash

            // Dynamic shadow opacity based on height
            const shadowAlpha = Math.max(0, 0.4 - (p.z / 400));
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath();
                ctx.arc(0, 0, shadowSize, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.restore();
        }

        if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;

                // Perspective Scale: Things closer to camera (higher Z) look slightly bigger
                const perspective = 1.0 + (p.z * 0.002);

                ctx.rotate(p.rotation);
                const scale = (p.size / 64) * perspective; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'GLOW') {
            // New Handler for Ambient Effects (Snow, Ash, Embers)
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); // Pulse
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.8;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'CHIP') {
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4);

            // Motion Stretch
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(2.0, 1 + speed / 1000);
            ctx.scale(stretch, 1/stretch);

            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;

            // OPTIMIZATION: Removed expensive shadowBlur for thousands of shards
            // ctx.shadowColor = p.color;
            // ctx.shadowBlur = p.vRotation > 5 ? 10 : 0;

            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

            // Highlight edge
            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            // Softer Alpha
            ctx.globalAlpha = (1 - progress) * 0.3;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 
                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 

            // Motion Stretch for Sparks
            const vel = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            if (vel > 50) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                ctx.scale(1 + vel/500, 0.5);
            }

            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG (Procedural)
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // Hex Geometry (Matches TerrainRenderer)
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; // ISO squashing
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); // Smooth fade in/out

        ctx.save();

        if (isChaos) {
            // RED: CRACKED EARTH + RISING MIASMA
            // ... (Red chaos logic unchanged as it uses shadowBlur but it's acceptable for fewer particles) ...
            // 1. Ground Cracks (Base)
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);

            drawHex();
            ctx.clip();

            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();

            ctx.strokeStyle = p.color; // Hot red
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;

            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();

            // 2. Rising Miasma (Volumetric Fog)
            ctx.globalCompositeOperation = 'lighter';

            const puffs = 3;
            for(let i=0; i<puffs; i++) {
                const t = (Date.now() / 1000 + i * 100) % 1;
                const yPos = 10 - t * 60; 
                const scale = 1 + t * 0.5;
                const puffAlpha = fade * (1 - t);

                ctx.globalAlpha = puffAlpha * 0.4;
                ctx.fillStyle = p.color;

                ctx.beginPath();
                ctx.ellipse((Math.sin(t*10 + i)*5), yPos, 15 * scale, 8 * scale, 0, 0, Math.PI*2);
                ctx.fill();
            }

        } else {
            // BLUE: HOLY CONSECRATION + LIGHT DUST

            // 1. Clean Hex Outline (OPTIMIZED: Replaced shadowBlur with double stroke)
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';

            // Glow Pass
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();

            // Core Pass
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();

            // 2. Vertical Light Beams (Stationary)
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#fff';

            const beams = 4;
            for(let i=0; i<beams; i++) {
                const angle = (Date.now() / 2000 + i * (Math.PI*2/beams)) % (Math.PI*2);
                const r = 15;
                const px = Math.cos(angle) * r;
                const py = Math.sin(angle) * r * 0.58;

                const beamHeight = 40 + Math.sin(Date.now()/500 + i)*10;

                const grad = ctx.createLinearGradient(0, py, 0, py - beamHeight);
                grad.addColorStop(0, `rgba(255,255,255,${fade * 0.5})`);
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.fillStyle = grad;
                ctx.fillRect(px - 1, py - beamHeight, 2, beamHeight);
            }
        }

        ctx.restore();
    },

    // 🏛️ BLUE: DIVINE PILLAR (High-End Technical Art)
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;

        let alpha = 0;
        if (lifeRatio > 0.9) alpha = (1 - lifeRatio) * 10; // 0.1s fade in
        else alpha = Math.pow(lifeRatio, 0.5); // Slow decay

        const maxHeight = 1200;
        const currentHeight = maxHeight * (progress < 0.1 ? progress * 10 : 1.0);
        const width = p.size;

        ctx.save();

        // Layer 1: Ground Seal (The Impact Point)
        ctx.save();
        ctx.scale(1, 0.55);
        ctx.globalCompositeOperation = 'screen';

        // OPTIMIZATION: Replaced shadowBlur with multi-pass stroke
        ctx.strokeStyle = '#fff';

        // Glow pass
        ctx.lineWidth = 6;
        ctx.globalAlpha = alpha * 0.3;
        ctx.beginPath(); ctx.arc(0, 0, width * 0.8, 0, Math.PI*2); ctx.stroke();

        // Core pass
        ctx.lineWidth = 3;
        ctx.globalAlpha = alpha;
        ctx.stroke();

        const wave = (progress * 2) % 1;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha * (1 - wave);
        ctx.beginPath(); ctx.arc(0, 0, width * (0.8 + wave * 0.5), 0, Math.PI*2); ctx.stroke();
        ctx.restore();

        // Layer 2: The Beam (Vertical Gradient)
        ctx.globalCompositeOperation = 'screen';

        const coreW = width * 0.3;
        const coreGrad = ctx.createLinearGradient(0, 0, 0, -currentHeight);
        coreGrad.addColorStop(0, 'rgba(255,255,255,0)');
        coreGrad.addColorStop(0.1, 'rgba(255,255,255,0.9)');
        coreGrad.addColorStop(0.8, 'rgba(255,255,255,0.0)');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-coreW/2, -currentHeight, coreW, currentHeight);

        const glowW = width;
        const glowGrad = ctx.createLinearGradient(-glowW, 0, glowW, 0); // Horizontal fade
        glowGrad.addColorStop(0, 'rgba(0,0,0,0)');
        glowGrad.addColorStop(0.2, p.color);
        glowGrad.addColorStop(0.5, 'rgba(255,255,255,0.5)');
        glowGrad.addColorStop(0.8, p.color);
        glowGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.save();
        const vMask = ctx.createLinearGradient(0, 0, 0, -currentHeight);
        vMask.addColorStop(0, 'rgba(0,0,0,0)');
        vMask.addColorStop(0.1, 'rgba(0,0,0,1)'); 

        ctx.fillStyle = glowGrad;
        ctx.globalAlpha = alpha * 0.6;
        const jitter = Math.random() * 10;
        ctx.fillRect(-(glowW + jitter)/2, -currentHeight, glowW + jitter, currentHeight);
        ctx.restore();

        // Layer 3: Interference Lines (Rising Energy)
        ctx.globalAlpha = alpha * 0.5;
        ctx.fillStyle = '#fff';
        const lines = 8;
        for(let i=0; i<lines; i++) {
            const yPos = -((Date.now()/500 + i/lines) % 1) * currentHeight;
            const hRatio = Math.abs(yPos) / currentHeight;
            const lineAlpha = 1 - Math.pow(2 * hRatio - 1, 2); 

            if (lineAlpha > 0.1) {
                ctx.globalAlpha = alpha * lineAlpha * 0.8;
                const lineW = width * (0.5 + Math.random()*0.5);
                ctx.fillRect(-lineW/2, yPos, lineW, 2 + Math.random() * 4);
            }
        }

        ctx.restore();
    },

    // 🩸 RED: BLOOD RITUAL (CHAOS)
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // 1. The Void (Ground Hole)
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); // Black center
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // 2. Cracks / Runes
         ctx.strokeStyle = p.color; // Red/Orange
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();

         // 3. Rising Dark Miasma (Noise)
         ctx.globalCompositeOperation = 'lighter'; // Glowy smoke
         ctx.fillStyle = p.color;
         const bubbles = 5;
         for(let i=0; i<bubbles; i++) {
             const bAngle = i * (Math.PI * 2 / bubbles) + progress * 2;
             const dist = r * 0.6;
             const bx = Math.cos(bAngle) * dist;
             const by = Math.sin(bAngle) * dist;
             const bSize = r * 0.3 * Math.sin(progress * 10 + i);

             ctx.globalAlpha = alpha * 0.3;
             ctx.beginPath(); ctx.arc(bx, by, Math.abs(bSize), 0, Math.PI*2); ctx.fill();
         }

         ctx.restore();

         // 4. Vertical "Heat" Haze (Not a pillar)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;

         ctx.beginPath();
         ctx.moveTo(-r/2, 0); 
         ctx.lineTo(-r/4, -300);
         ctx.lineTo(r/4, -300);
         ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 

        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            // Jagged
            ctx.globalCompositeOperation = 'source-over'; // Darker/Physical
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            // Smooth
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 40;
const BAR_HEIGHT = 5;
const BAR_BORDER = 1;

interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 
}

export class HUDSystem {
    // Active Texts
    damageNumbers: FloatingText[] = [];

    // Memory Pool
    private pool: FloatingText[] = [];

    constructor() {
        // Pre-allocate pool
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false
        };
    }

    public addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        // UX FIX: Prevent Kill Streak Overlap
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; // Ults float very slowly
                life = 2.5; // Stay longer
                size = 24; // Bigger font
            } else {
                vy = -20; // Normal skills float gently
                life = 1.2;
                size = 14; // Smaller to be less intrusive
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; // Stay very long
            size = 32; // HUGE
        } else {
            // DAMAGE / HEAL
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; // Initial jump
        }

        // Get from pool
        let ft: FloatingText;
        if (this.pool.length > 0) {
            ft = this.pool.pop()!;
        } else {
            ft = this.createEmpty();
        }

        // Init
        ft.active = true;
        ft.x = x; ft.y = y;
        ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;

        this.damageNumbers.push(ft);
    }

    private release(ft: FloatingText) {
        ft.active = false;
        this.pool.push(ft);
    }

    update(dt: number) {
        // Reverse iterate to allow removal
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            // Physics integration
            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            // Gravity logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; // Friction
            } else if (d.type === 'KILL_STREAK') {
                d.vy *= 0.92; // Anti-gravity float
            }

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); // Fast remove from active list
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        // 1. Draw HP/MP Bars & Status Labels
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            // Determine Ground Level Logic
            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            this.drawUnitBars(ctx, a, headX, anchorY, isSelected, time);
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        // 2. Draw Floating Text
        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH'; gaugeColor = '#d8b4fe';
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS'; gaugeColor = '#facc15';
            } else {
                iconType = 'BANISH'; gaugeColor = '#7e22ce';
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN'; gaugeColor = '#fbbf24';
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE'; gaugeColor = '#94a3b8';
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean, time: number) {
        const w = BAR_WIDTH;
        const h = BAR_HEIGHT;
        const b = BAR_BORDER;

        ctx.fillStyle = '#000'; 
        const totalHeight = (agent.maxMp > 0) ? (h*1.5 + b*3) : (h + b*2);

        ctx.fillRect(x - w/2 - b, y - b, w + b*2, totalHeight);

        if (isSelected) {
            ctx.save();
            const pulse = 0.6 + Math.sin(time * 8) * 0.4;

            // OPTIMIZATION: Replaced shadowBlur with lighter multi-pass
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = `rgba(255, 255, 255, ${pulse})`;

            // Glow pass
            ctx.lineWidth = 4;
            ctx.globalAlpha = 0.3;
            ctx.strokeRect(x - w/2 - b - 2, y - b - 2, w + b*2 + 4, totalHeight + 4);

            // Core pass
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1.0;
            ctx.strokeRect(x - w/2 - b - 1, y - b - 1, w + b*2 + 2, totalHeight + 2);

            ctx.restore();
        }

        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        ctx.fillStyle = COLORS.HP; 
        ctx.fillRect(x - w/2, y, w * hpPct, h);

        if (agent.maxMp > 0) {
            const mpH = h / 2 + 1;
            const mpY = y + h + b;
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            ctx.fillStyle = COLORS.MP; 
            ctx.fillRect(x - w/2, mpY, w * mpPct, mpH);
        }
    }

    private drawCircularGauge(ctx: CanvasRenderingContext2D, x: number, y: number, pct: number, visualKey: string, color: string, isSkill: boolean) {
        const radius = 14;
        const iconY = y - 18; 

        ctx.save();
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = '#1e293b';
        ctx.fill();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        if (icon) ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        ctx.restore();

        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(0, 0, 0, 0.6)';
        ctx.lineWidth = 4;
        ctx.stroke();

        const safePct = Math.max(0, Math.min(1, pct));

        if (safePct > 0) {
            ctx.beginPath();
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.stroke();
        }

        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)';
        ctx.lineWidth = 1;
        ctx.stroke();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 30;
                    const h = d.size + 16;

                    const bgGrad = ctx.createLinearGradient(-w, 0, w, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.6)'); 
                    bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.6)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w, -h/2, w*2, h);
                    ctx.fillStyle = '#fff';
                    ctx.strokeStyle = '#000';
                    ctx.lineWidth = 3;
                    ctx.strokeText(d.text, 0, 0);
                    ctx.fillText(d.text, 0, 0);
                    ctx.restore();
                } else {
                    ctx.font = `bold italic ${d.size}px "Segoe UI", sans-serif`;
                    ctx.lineWidth = 3;
                    ctx.lineJoin = 'round';
                    ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)'; 
                    ctx.strokeText(d.text, d.x, d.y);
                    ctx.fillStyle = d.color;
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else if (d.type === 'CC') {
                ctx.font = `900 ${d.size}px "Arial Black", sans-serif`; 
                ctx.strokeStyle = 'rgba(0,0,0,1.0)';
                ctx.lineWidth = 3;
                ctx.strokeText(d.text, d.x, d.y);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, d.x, d.y);

            } else {
                ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                ctx.fillStyle = d.color; 
                ctx.strokeStyle = 'rgba(0,0,0,0.8)'; 
                ctx.lineWidth = 3; 
                ctx.strokeText(d.text, d.x, d.y); 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            const op = renderList.next();
            op.type = RenderOpType.UNIT;
            op.y = agent.py + 1; // Sort base
            op.z = 10;

            op.agent = agent;
            op.tx = agent.px; // Draw X
            op.ty = visualY;  // Draw Y (Ground)
            op.time = globalTime;
            op.uSelected = (highlightAgent === agent);
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }
        const visualY = agent.py - h;
        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =========================================================================================
    // 🎨 ASSEMBLY PIPELINE: The core drawing logic
    // =========================================================================================
    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Calculate Scaling
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }
        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        // START MAIN TRANSFORM STACK
        ctx.save();

        // 2. Global Position Transform (Screen Space -> Unit Root)
        ctx.translate(drawX, drawY); 
        ctx.scale(scaleFactor, scaleFactor);

        // Calculate Physics Offsets (Scaled to Local Space)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // 3. LAYER: GROUND (Shadows / Base Plates / Casting Circles)
        // These are drawn relative to physics X/Y but usually stay on ground (Z=0)
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            this.drawGroundElements(ctx, agent, physX, physY, physZ, globalTime);
        }

        // 4. LAYER: UNIT BODY ROOT (Apply Physics Translation)
        // Now we move the context to the unit's actual body center (Chest/Feet)
        ctx.translate(physX, physY - physZ); 

        // 5. Apply Body Physics Rotation (e.g. Knockback spin)
        ctx.rotate(agent.physics.angle); 

        // 6. LAYER: ANIMATED BODY
        this.drawBodyElements(ctx, agent, globalTime, isSilhouette, isSelected, scaleFactor);

        // END MAIN TRANSFORM STACK
        ctx.restore();

        // 7. LAYER: SPAWN INDICATOR (Screen Space / World Space Overlay)
        // This is drawn outside the scale/rotate stack to keep text readable
        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    private drawGroundElements(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        // Base Token / Shadow
        ctx.save();
        // Base stays at feet level (py), ignoring jump height (pz) usually, unless we want shadow to jump
        ctx.translate(px, py - pz); 
        ctx.drawImage(assets.base, -64, -79); 
        ctx.restore();

        // Flying Tether
        if (agent.movementType === MovementType.FLYING) {
            drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }

        // Casting Magic Circle
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                ctx.save(); 
                ctx.translate(px, py - pz); 
                ctx.scale(1, 0.5); 
                ctx.rotate(t * 2);
                ctx.globalAlpha = 0.6;
                ctx.drawImage(circle, -64, -64, 128, 128); 
                ctx.restore();
            }
        }
    }

    private drawBodyElements(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isSelected: boolean, scaleFactor: number) {
        // "Breathing" Animation (Idle Float)
        let bodyFloat = -UNIT_BODY_OFFSET; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat -= Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat -= Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // Spawn / Hit Flash effects
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            spawnAlpha = eased;
            whiteOverlay = 1 - eased; 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= spawnAlpha;
        }

        if (agent.hp <= 0 && !isSilhouette) {
            // Using globalAlpha instead of filter to improve performance on death
            ctx.globalAlpha *= 0.8; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             whiteOverlay = 0.6; 
             // OPTIMIZATION: Removed expensive brightness filter
             // ctx.filter = 'brightness(200%)';
        }

        // Apply Flight VFX (Thrusters)
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, t);
        }

        // Face Direction
        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // Draw Model
        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, t);
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // Hit Flash Overlay (Performant)
        if (whiteOverlay > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; // or 'overlay'
            ctx.globalAlpha = whiteOverlay;
            // Draw a white blob over the unit approximate area
            // Ideally we'd mask the sprite, but a radial gradient bloom works for "Flash"
            const flashGrad = ctx.createRadialGradient(0, -20, 0, 0, -20, 50);
            flashGrad.addColorStop(0, 'rgba(255,255,255,1)');
            flashGrad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = flashGrad;
            ctx.beginPath(); ctx.arc(0, -20, 50, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // Icons
        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, t, 0, 0, scaleFactor);
            drawStatusEffects(ctx, agent, t);
        }
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showUnitDetail, setShowUnitDetail] = useState(false);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    // This allows the engine to drive state changes without prop drilling
    useEffect(() => {
        const engine = engineRef.current;

        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            // If in showcase, auto-restart flow logic is moved here or kept in loop?
            // Actually, hooks can read state better.

            // Logic moved from old onWin prop:
            if (engine.isRunning) engine.stop(); // Ensure stopped

            // Note: We access current value of isShowcaseMode via ref if needed, or rely on state updates
            // Since this effect closes over initial state, we need to be careful.
            // Better to trigger visual updates here.
            setIsPlaying(false);
        };

        engine.bus.on('GAME_OVER', handleGameOver);

        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic (Reactive to winner state)
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            // Speed up the showcase loop significantly
            // 1. Wait a brief moment to see the victory text/effects (500ms)
            const timer = setTimeout(() => {
                // 2. Trigger OUT transition (Blur out + Fly out)
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                // 3. Wait for OUT animation to finish (500ms)
                setTimeout(() => {
                    setupShowcaseMap(); 
                    // 4. Trigger IN transition (Fly in + Blur clear)
                    setTransitionPhase('IN'); 

                    // 5. Wait for IN animation to finish (500ms)
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 500); 
                }, 500); 
            }, 500); // Initial dwell reduced to 0.5s
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        setShowUnitDetail(false);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        // Fisher-Yates shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    // Initial Start
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    // Stats Loop
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    // Time Scale Sync
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    // --- HANDLERS ---

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        // Quick Spawn logic for manual random
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);

        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        // Reuse random logic but start playing immediately
        handleRandomBattlefield();

        // Need to wait a tick for agents to be ready? 
        // handleRandomBattlefield runs synchronously, so we can just play.
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;

        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }

            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
        if (!a) setShowUnitDetail(false);
    };

    // --- RETURN ---
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB,
            showUnitDetail, transitionPhase, showFactionWarning
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, 
            setShowUnitDetail, setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel, // New action
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, // Manual trigger shim
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); // FIX: Explicitly start engine
                setIsPlaying(true); 
            }
        }
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // Speed adjusted: 2.2 for ~0.45s transitions (Ensures it fits in 0.5s window)
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 2.2);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - God View Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">

                        {/* Winner Label */}
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>

                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-4 rounded-xl text-lg font-bold bg-white/5 hover:bg-white/10 border-white/20 text-slate-200 shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Restart className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>

                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: FROSTED GLASS TRANSITIONS (Victory / Map Swap) ---
        // Enhanced Logic: Smoothly handle both Enter (Clear) and Exit (Blur)
        let blurAmount = 0;

        if (engine.isFinishing) {
            // Ramping Up (Active Victory Phase)
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // Bridge Gap: Game finished but transition hasn't started
            blurAmount = 1.0;
        }

        // Transition Overrides
        if (this.transitionPhase === 'OUT') {
            // LEAVING: Fade to Blur (0 -> 1)
            // Use Math.max to ensure if we are already blurred (victory), we stay blurred.
            blurAmount = Math.max(blurAmount, this.transitionT);
        } else if (this.transitionPhase === 'IN') {
            // ENTERING: Fade from Blur (1 -> 0)
            blurAmount = 1.0 - this.transitionT;
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Draw Trail ---
        // Using the pre-calculated visual trail points in op.pTrail
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = op.pColor;

            // Trail Width Logic: Tapering
            // We iterate through the visual points (Screen Space relative to map origin)

            // Draw the line strip
            ctx.beginPath();

            const trail = op.pTrail;
            if (trail.length > 0) {
                // The first point in trail array is the HEAD (newest)
                ctx.moveTo(trail[0].x, trail[0].y);
                for(let i=1; i<trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
            }

            // Style: Fade out
            const grad = ctx.createLinearGradient(trail[0].x, trail[0].y, trail[trail.length-1].x, trail[trail.length-1].y);
            grad.addColorStop(0, op.pColor); // Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Tail

            ctx.strokeStyle = grad;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();

            // Inner Core Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        // Simple blob shadow on ground
        // We use pVisShadowY stored in op
        const shadowAltitude = op.pVisShadowY - op.pVisY; // Difference between ground and air

        // Don't draw shadow if too low (to avoid clipping with sprite)
        // Or if really high, shadow fades
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            // Scale shadow based on height (higher = smaller/blurrier)
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);

            ctx.scale(shadowScale, shadowScale * 0.5); // Flattened ellipse
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // Speed adjusted: 2.0 = Exactly 0.5s duration. 
            // We use 0.5s as the hard constraint requested.
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 2.0);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

