    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showUnitDetail, setShowUnitDetail] = useState(false);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    // This allows the engine to drive state changes without prop drilling
    useEffect(() => {
        const engine = engineRef.current;

        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            // If in showcase, auto-restart flow logic is moved here or kept in loop?
            // Actually, hooks can read state better.

            // Logic moved from old onWin prop:
            if (engine.isRunning) engine.stop(); // Ensure stopped

            // Note: We access current value of isShowcaseMode via ref if needed, or rely on state updates
            // Since this effect closes over initial state, we need to be careful.
            // Better to trigger visual updates here.
            setIsPlaying(false);
        };

        engine.bus.on('GAME_OVER', handleGameOver);

        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic (Reactive to winner state)
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            // Speed up the showcase loop significantly
            // 1. Wait a brief moment to see the victory text/effects (500ms)
            // INCREASED: 800ms buffer allows the user to see the "VICTORY" screen briefly before blur starts.
            const timer = setTimeout(() => {
                // 2. Trigger OUT transition (Blur out + Fly out)
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                // 3. Wait for OUT animation to finish
                // INCREASED: 800ms guarantees the 500ms animation loop inside GameCanvas finishes fully.
                setTimeout(() => {
                    setupShowcaseMap(); 
                    // 4. Trigger IN transition (Fly in + Blur clear)
                    setTransitionPhase('IN'); 

                    // 5. Wait for IN animation to finish
                    // INCREASED: 800ms guarantees smooth landing before units spawn.
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 800); 
                }, 800); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        setShowUnitDetail(false);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        // Fisher-Yates shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    // Initial Start
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    // Stats Loop
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    // Time Scale Sync
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    // --- HANDLERS ---

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        // Quick Spawn logic for manual random
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);

        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        // Reuse random logic but start playing immediately
        handleRandomBattlefield();

        // Need to wait a tick for agents to be ready? 
        // handleRandomBattlefield runs synchronously, so we can just play.
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;

        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }

            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
        if (!a) setShowUnitDetail(false);
    };

    // --- RETURN ---
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB,
            showUnitDetail, transitionPhase, showFactionWarning
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, 
            setShowUnitDetail, setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel, // New action
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, // Manual trigger shim
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); // FIX: Explicitly start engine
                setIsPlaying(true); 
            }
        }
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // SPEED ADJUSTED: 1.8 multiplier = ~0.55s duration.
            // This ensures it doesn't snap instantly but is fast enough for the request.
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 1.8);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - God View Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">

                        {/* Winner Label */}
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>

                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-4 rounded-xl text-lg font-bold bg-white/5 hover:bg-white/10 border-white/20 text-slate-200 shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Restart className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>

                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point } from "../types";

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
}

// FFT Style Isometric Constants
const ANGLE = Math.PI / 4;
const SIN_A = Math.sin(ANGLE);
const COS_A = Math.cos(ANGLE);

// --- Integer Hashing Constants ---
// Hash = (q + 128) << 16 | (r + 128)
const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

// --- VISUAL UTILS ---

/**
 * Calculates the vertical visual offset for map transitions (Flying in/out).
 * CRITICAL OPTIMIZATION: Movements now scale across the available time window (trigger to 1.0)
 * to prevent instant snapping.
 */
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;

    const centerQ = Math.floor(mapConfig.w / 2);
    const centerR = Math.floor(mapConfig.h / 2);
    const hex = HexUtils.fromPx(x, y, mapConfig);

    const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
    const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
    const d = dist / maxDist;

    // Wave Propagation Logic:
    // Stagger based on distance from center.
    const trigger = d * 0.3; // Stagger up to 30% of the timeline

    if (phase === 'OUT') {
        // LEAVING: Fall down
        if (t > trigger) {
            // Map the remaining time (trigger -> 1.0) to (0.0 -> 1.0)
            const duration = 1.0 - trigger;
            const localT = (t - trigger) / duration;
            const fallT = Math.min(1, Math.max(0, localT));

            // Cubic ease in for launch
            return fallT * fallT * fallT * 1200;
        }
    } else if (phase === 'IN') {
        // ARRIVING: Rise up
        if (t > trigger) {
            const duration = 1.0 - trigger;
            const localT = (t - trigger) / duration;
            const riseT = Math.min(1, Math.max(0, localT));

            // Cubic ease out for landing
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1200;
        } else {
            // Before trigger, it's fully offset (hidden)
            return 1200;
        }
    }
    return 0;
}

export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        const q = col - (row - (row & 1)) / 2;
        const r = row;
        return { q: Math.floor(q), r };
    },

    toPx: (q: number, r: number, config: MapConfig): Point => {
        const cx = (Math.sqrt(3) * q + Math.sqrt(3) / 2 * r) * HEX_SIZE;
        const cy = (1.5 * r) * HEX_SIZE; 

        const rx = cx * COS_A - cy * SIN_A;
        const ry = cx * SIN_A + cy * COS_A;

        return { 
            x: config.offsetX + rx, 
            y: config.offsetY + ry * ISO_SCALE_Y 
        };
    },

    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const dx = x - config.offsetX;
        const dy = y - config.offsetY;
        const unsquashedY = dy / ISO_SCALE_Y;

        const cx = dx * COS_A + unsquashedY * SIN_A;
        const cy = -dx * SIN_A + unsquashedY * COS_A;

        const q = (Math.sqrt(3)/3 * cx - 1/3 * cy) / HEX_SIZE;
        const r = (2/3 * cy) / HEX_SIZE;

        return HexUtils.round(q, r);
    },

    round: (q: number, r: number): Hex => {
        let s = -q - r;
        let qi = Math.round(q);
        let ri = Math.round(r);
        let si = Math.round(s);
        const q_diff = Math.abs(qi - q);
        const r_diff = Math.abs(ri - r);
        const s_diff = Math.abs(si - s);

        if (q_diff > r_diff && q_diff > s_diff) qi = -ri - si;
        else if (r_diff > s_diff) ri = -qi - si;

        return { q: qi, r: ri };
    },

    dist: (a: Hex, b: Hex): number => {
        const aq = Math.round(a.q); const ar = Math.round(a.r);
        const bq = Math.round(b.q); const br = Math.round(b.r);
        return (Math.abs(aq - bq) + Math.abs(aq + ar - bq - br) + Math.abs(ar - br)) / 2;
    },

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showUnitDetail, setShowUnitDetail] = useState(false);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    // This allows the engine to drive state changes without prop drilling
    useEffect(() => {
        const engine = engineRef.current;

        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            // If in showcase, auto-restart flow logic is moved here or kept in loop?
            // Actually, hooks can read state better.

            // Logic moved from old onWin prop:
            if (engine.isRunning) engine.stop(); // Ensure stopped

            // Note: We access current value of isShowcaseMode via ref if needed, or rely on state updates
            // Since this effect closes over initial state, we need to be careful.
            // Better to trigger visual updates here.
            setIsPlaying(false);
        };

        engine.bus.on('GAME_OVER', handleGameOver);

        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic (Reactive to winner state)
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            // Speed up the showcase loop significantly
            // 1. Wait a brief moment to see the victory text/effects
            // EXTENDED: 1000ms buffer to match new slower transition
            const timer = setTimeout(() => {
                // 2. Trigger OUT transition (Blur out + Fly out)
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                // 3. Wait for OUT animation to finish
                // EXTENDED: 1000ms for full exit
                setTimeout(() => {
                    setupShowcaseMap(); 
                    // 4. Trigger IN transition (Fly in + Blur clear)
                    setTransitionPhase('IN'); 

                    // 5. Wait for IN animation to finish
                    // EXTENDED: 1000ms for full entry
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1000); 
                }, 1000); 
            }, 1000); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        setShowUnitDetail(false);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        // Fisher-Yates shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    // Initial Start
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    // Stats Loop
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    // Time Scale Sync
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    // --- HANDLERS ---

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        // Quick Spawn logic for manual random
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);

        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        // Reuse random logic but start playing immediately
        handleRandomBattlefield();

        // Need to wait a tick for agents to be ready? 
        // handleRandomBattlefield runs synchronously, so we can just play.
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;

        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }

            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
        if (!a) setShowUnitDetail(false);
    };

    // --- RETURN ---
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB,
            showUnitDetail, transitionPhase, showFactionWarning
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, 
            setShowUnitDetail, setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel, // New action
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, // Manual trigger shim
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); // FIX: Explicitly start engine
                setIsPlaying(true); 
            }
        }
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // SPEED ADJUSTED: 1.3 multiplier = ~0.77s duration.
            // Slower speed allows the "wave" to be seen properly without snapping.
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 1.3);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - God View Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">

                        {/* Winner Label */}
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>

                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-4 rounded-xl text-lg font-bold bg-white/5 hover:bg-white/10 border-white/20 text-slate-200 shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Restart className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>

                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point } from "../types";

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
}

// FFT Style Isometric Constants
const ANGLE = Math.PI / 4;
const SIN_A = Math.sin(ANGLE);
const COS_A = Math.cos(ANGLE);

// --- Integer Hashing Constants ---
// Hash = (q + 128) << 16 | (r + 128)
const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

// --- VISUAL UTILS ---

/**
 * Calculates the vertical visual offset for map transitions (Flying in/out).
 * WAVE LOGIC V3: Continuous motion.
 * No 'trigger wait' dead zone. Everyone moves from T=0.
 * Distance (d) adds 'drag' or 'lag' to the easing function.
 */
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;

    const centerQ = Math.floor(mapConfig.w / 2);
    const centerR = Math.floor(mapConfig.h / 2);
    const hex = HexUtils.fromPx(x, y, mapConfig);

    const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
    const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);

    // Normalize distance 0 to 1
    const d = Math.min(1, dist / maxDist);

    const BASE_OFFSET = 1200;

    if (phase === 'OUT') {
        // LEAVING: Center falls first, edges follow (Wave Out)
        // t goes 0 -> 1
        // We want effectiveT to be slower for edges (high d)
        // Effective T = t ^ (1 + d * lagFactor)

        const lag = 1 + d * 2.0; // Edges are 3x slower to start falling
        const effectiveT = Math.pow(t, lag);

        // Quadratic acceleration down
        return effectiveT * effectiveT * BASE_OFFSET;

    } else if (phase === 'IN') {
        // ARRIVING: Center lands first, edges lag behind (Wave In)
        // t goes 0 -> 1
        // Start position is BASE_OFFSET
        // End position is 0

        // Edges should reach 1.0 (landed) LATER than center
        // Center: reaches 1.0 quickly. Edges: reach 1.0 slowly.
        // We use Power to curve the completion.

        // Invert d for incoming wave? No, center should land first.
        // So edges have higher lag.

        const lag = 1 + d * 1.5; 

        // progress: 0 -> 1
        // We want edge progress to be < center progress at any given t < 1
        const progress = Math.pow(t, lag); 

        // Easing: Elastic overshoot or cubic ease-out
        const eased = 1 - Math.pow(1 - progress, 3);

        return (1 - eased) * BASE_OFFSET;
    }
    return 0;
}

export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        const q = col - (row - (row & 1)) / 2;
        const r = row;
        return { q: Math.floor(q), r };
    },

    toPx: (q: number, r: number, config: MapConfig): Point => {
        const cx = (Math.sqrt(3) * q + Math.sqrt(3) / 2 * r) * HEX_SIZE;
        const cy = (1.5 * r) * HEX_SIZE; 

        const rx = cx * COS_A - cy * SIN_A;
        const ry = cx * SIN_A + cy * COS_A;

        return { 
            x: config.offsetX + rx, 
            y: config.offsetY + ry * ISO_SCALE_Y 
        };
    },

    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const dx = x - config.offsetX;
        const dy = y - config.offsetY;
        const unsquashedY = dy / ISO_SCALE_Y;

        const cx = dx * COS_A + unsquashedY * SIN_A;
        const cy = -dx * SIN_A + unsquashedY * COS_A;

        const q = (Math.sqrt(3)/3 * cx - 1/3 * cy) / HEX_SIZE;
        const r = (2/3 * cy) / HEX_SIZE;

        return HexUtils.round(q, r);
    },

    round: (q: number, r: number): Hex => {
        let s = -q - r;
        let qi = Math.round(q);
        let ri = Math.round(r);
        let si = Math.round(s);
        const q_diff = Math.abs(qi - q);
        const r_diff = Math.abs(ri - r);
        const s_diff = Math.abs(si - s);

        if (q_diff > r_diff && q_diff > s_diff) qi = -ri - si;
        else if (r_diff > s_diff) ri = -qi - si;

        return { q: qi, r: ri };
    },

    dist: (a: Hex, b: Hex): number => {
        const aq = Math.round(a.q); const ar = Math.round(a.r);
        const bq = Math.round(b.q); const br = Math.round(b.r);
        return (Math.abs(aq - bq) + Math.abs(aq + ar - bq - br) + Math.abs(ar - br)) / 2;
    },

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: FROSTED GLASS TRANSITIONS (Victory / Map Swap) ---
        // Enhanced Logic: Smoothly handle both Enter (Clear) and Exit (Blur)
        let blurAmount = 0;

        if (engine.isFinishing) {
            // Ramping Up (Active Victory Phase)
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // Bridge Gap: Game finished but transition hasn't started
            blurAmount = 1.0;
        }

        // Transition Overrides
        if (this.transitionPhase === 'OUT') {
            // LEAVING: Fade to Blur (0 -> 1)
            // Ramp up semi-linear to catch the exit
            blurAmount = Math.max(blurAmount, this.transitionT);
        } else if (this.transitionPhase === 'IN') {
            // ENTERING: Fade from Blur (1 -> 0)
            // FIXED: Using Cosine ease-in to keep blur HIGH during the initial movement
            // t=0 (start) -> blur=1
            // t=0.5 (mid) -> blur=0.7 (still blurry)
            // t=1.0 (end) -> blur=0 (clear)
            blurAmount = Math.cos(this.transitionT * Math.PI / 2);
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Draw Trail ---
        // Using the pre-calculated visual trail points in op.pTrail
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = op.pColor;

            // Trail Width Logic: Tapering
            // We iterate through the visual points (Screen Space relative to map origin)

            // Draw the line strip
            ctx.beginPath();

            const trail = op.pTrail;
            if (trail.length > 0) {
                // The first point in trail array is the HEAD (newest)
                ctx.moveTo(trail[0].x, trail[0].y);
                for(let i=1; i<trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
            }

            // Style: Fade out
            const grad = ctx.createLinearGradient(trail[0].x, trail[0].y, trail[trail.length-1].x, trail[trail.length-1].y);
            grad.addColorStop(0, op.pColor); // Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Tail

            ctx.strokeStyle = grad;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();

            // Inner Core Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        // Simple blob shadow on ground
        // We use pVisShadowY stored in op
        const shadowAltitude = op.pVisShadowY - op.pVisY; // Difference between ground and air

        // Don't draw shadow if too low (to avoid clipping with sprite)
        // Or if really high, shadow fades
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            // Scale shadow based on height (higher = smaller/blurrier)
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);

            ctx.scale(shadowScale, shadowScale * 0.5); // Flattened ellipse
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showUnitDetail, setShowUnitDetail] = useState(false);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    // This allows the engine to drive state changes without prop drilling
    useEffect(() => {
        const engine = engineRef.current;

        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            // If in showcase, auto-restart flow logic is moved here or kept in loop?
            // Actually, hooks can read state better.

            // Logic moved from old onWin prop:
            if (engine.isRunning) engine.stop(); // Ensure stopped

            // Note: We access current value of isShowcaseMode via ref if needed, or rely on state updates
            // Since this effect closes over initial state, we need to be careful.
            // Better to trigger visual updates here.
            setIsPlaying(false);
        };

        engine.bus.on('GAME_OVER', handleGameOver);

        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic (Reactive to winner state)
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            // STEP 1: Battle Ends.
            // Wait 1.5s for Death Animations & "VICTORY" text to sink in.
            const timer = setTimeout(() => {

                // STEP 2: Trigger OUT (Blur Ramps Up + Map Flies Out)
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                // Wait 1.2s for OUT animation to complete fully
                setTimeout(() => {
                    setupShowcaseMap(); 

                    // STEP 3: Trigger IN (Map Flies In + Blur Fades Out)
                    setTransitionPhase('IN'); 

                    // Wait 1.2s for IN animation to land and clear blur
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 1500); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        setShowUnitDetail(false);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        // Fisher-Yates shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    // Initial Start
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    // Stats Loop
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    // Time Scale Sync
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    // --- HANDLERS ---

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        // Quick Spawn logic for manual random
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);

        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        // Reuse random logic but start playing immediately
        handleRandomBattlefield();

        // Need to wait a tick for agents to be ready? 
        // handleRandomBattlefield runs synchronously, so we can just play.
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;

        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }

            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
        if (!a) setShowUnitDetail(false);
    };

    // --- RETURN ---
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB,
            showUnitDetail, transitionPhase, showFactionWarning
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, 
            setShowUnitDetail, setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel, // New action
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, // Manual trigger shim
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); // FIX: Explicitly start engine
                setIsPlaying(true); 
            }
        }
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // SPEED ADJUSTED: 0.8 multiplier = ~1.25s duration.
            // Very slow, deliberate movement to allow the Blur to sync perfectly.
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.8);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - God View Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">

                        {/* Winner Label */}
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>

                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-4 rounded-xl text-lg font-bold bg-white/5 hover:bg-white/10 border-white/20 text-slate-200 shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Restart className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>

                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: FROSTED GLASS TRANSITIONS (Victory / Map Swap) ---
        // Enhanced Logic: Strict Sync
        let blurAmount = 0;

        if (engine.isFinishing) {
            // Ramping Up (Active Victory Phase)
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // Bridge Gap: Game finished but transition hasn't started
            blurAmount = 1.0;
        }

        // Transition Overrides
        // Logic:
        // OUT: Fade Blur In (0 -> 1) as map leaves.
        // IN: Fade Blur Out (1 -> 0) as map enters.
        if (this.transitionPhase === 'OUT') {
            // 0 -> 1
            blurAmount = this.transitionT; 
        } else if (this.transitionPhase === 'IN') {
            // 1 -> 0
            // Linear fade out to perfectly match the tile landing at t=1.0
            blurAmount = 1.0 - this.transitionT;
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Draw Trail ---
        // Using the pre-calculated visual trail points in op.pTrail
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = op.pColor;

            // Trail Width Logic: Tapering
            // We iterate through the visual points (Screen Space relative to map origin)

            // Draw the line strip
            ctx.beginPath();

            const trail = op.pTrail;
            if (trail.length > 0) {
                // The first point in trail array is the HEAD (newest)
                ctx.moveTo(trail[0].x, trail[0].y);
                for(let i=1; i<trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
            }

            // Style: Fade out
            const grad = ctx.createLinearGradient(trail[0].x, trail[0].y, trail[trail.length-1].x, trail[trail.length-1].y);
            grad.addColorStop(0, op.pColor); // Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Tail

            ctx.strokeStyle = grad;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();

            // Inner Core Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        // Simple blob shadow on ground
        // We use pVisShadowY stored in op
        const shadowAltitude = op.pVisShadowY - op.pVisY; // Difference between ground and air

        // Don't draw shadow if too low (to avoid clipping with sprite)
        // Or if really high, shadow fades
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            // Scale shadow based on height (higher = smaller/blurrier)
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);

            ctx.scale(shadowScale, shadowScale * 0.5); // Flattened ellipse
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point } from "../types";

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
}

// FFT Style Isometric Constants
const ANGLE = Math.PI / 4;
const SIN_A = Math.sin(ANGLE);
const COS_A = Math.cos(ANGLE);

// --- Integer Hashing Constants ---
// Hash = (q + 128) << 16 | (r + 128)
const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

// --- VISUAL UTILS ---

/**
 * Calculates the vertical visual offset for map transitions (Flying in/out).
 * WAVE LOGIC V4: Full Range Motion.
 * Ensure at T=1.0, offset is exactly 0.
 * Ensure at T=0.0, offset is Max.
 */
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;

    const centerQ = Math.floor(mapConfig.w / 2);
    const centerR = Math.floor(mapConfig.h / 2);
    const hex = HexUtils.fromPx(x, y, mapConfig);

    const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
    const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);

    // Normalize distance 0 to 1
    const d = Math.min(1, dist / maxDist);
    const BASE_OFFSET = 1200;

    if (phase === 'OUT') {
        // LEAVING: Tiles fly UP.
        // Center leaves first, edges follow.
        // t: 0 -> 1

        // Effective Time with lag
        // Center (d=0): moves immediately
        // Edge (d=1): waits slightly
        const lag = 1 + d * 1.5; 
        const effectiveT = Math.pow(t, lag);

        // Quadratic acceleration UP
        return -effectiveT * effectiveT * BASE_OFFSET;

    } else if (phase === 'IN') {
        // ARRIVING: Tiles fly DOWN from sky.
        // T=0 -> Offset = -1200
        // T=1 -> Offset = 0

        // Lag: Edges arrive later than center
        // Center: fast finish. Edges: slow finish.
        const lag = 1 + d * 1.5;
        const progress = Math.pow(t, lag); 

        // Eased landing
        const eased = 1 - Math.pow(1 - progress, 3);

        // Start at negative offset (Sky) -> 0
        return (eased - 1) * BASE_OFFSET;
    }
    return 0;
}

export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        const q = col - (row - (row & 1)) / 2;
        const r = row;
        return { q: Math.floor(q), r };
    },

    toPx: (q: number, r: number, config: MapConfig): Point => {
        const cx = (Math.sqrt(3) * q + Math.sqrt(3) / 2 * r) * HEX_SIZE;
        const cy = (1.5 * r) * HEX_SIZE; 

        const rx = cx * COS_A - cy * SIN_A;
        const ry = cx * SIN_A + cy * COS_A;

        return { 
            x: config.offsetX + rx, 
            y: config.offsetY + ry * ISO_SCALE_Y 
        };
    },

    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const dx = x - config.offsetX;
        const dy = y - config.offsetY;
        const unsquashedY = dy / ISO_SCALE_Y;

        const cx = dx * COS_A + unsquashedY * SIN_A;
        const cy = -dx * SIN_A + unsquashedY * COS_A;

        const q = (Math.sqrt(3)/3 * cx - 1/3 * cy) / HEX_SIZE;
        const r = (2/3 * cy) / HEX_SIZE;

        return HexUtils.round(q, r);
    },

    round: (q: number, r: number): Hex => {
        let s = -q - r;
        let qi = Math.round(q);
        let ri = Math.round(r);
        let si = Math.round(s);
        const q_diff = Math.abs(qi - q);
        const r_diff = Math.abs(ri - r);
        const s_diff = Math.abs(si - s);

        if (q_diff > r_diff && q_diff > s_diff) qi = -ri - si;
        else if (r_diff > s_diff) ri = -qi - si;

        return { q: qi, r: ri };
    },

    dist: (a: Hex, b: Hex): number => {
        const aq = Math.round(a.q); const ar = Math.round(a.r);
        const bq = Math.round(b.q); const br = Math.round(b.r);
        return (Math.abs(aq - bq) + Math.abs(aq + ar - bq - br) + Math.abs(ar - br)) / 2;
    },

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showUnitDetail, setShowUnitDetail] = useState(false);
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    // This allows the engine to drive state changes without prop drilling
    useEffect(() => {
        const engine = engineRef.current;

        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            // If in showcase, auto-restart flow logic is moved here or kept in loop?
            // Actually, hooks can read state better.

            // Logic moved from old onWin prop:
            if (engine.isRunning) engine.stop(); // Ensure stopped

            // Note: We access current value of isShowcaseMode via ref if needed, or rely on state updates
            // Since this effect closes over initial state, we need to be careful.
            // Better to trigger visual updates here.
            setIsPlaying(false);
        };

        engine.bus.on('GAME_OVER', handleGameOver);

        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic (Reactive to winner state)
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            // STEP 1: Battle Ends.
            // REDUCED: Wait 0.8s (was 1.5s) for quick glance at death animations.
            const timer = setTimeout(() => {

                // STEP 2: Trigger OUT (Blur Ramps Up + Map Falls Down)
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                // Wait 1.2s for OUT animation to complete fully (Cinematic feel)
                setTimeout(() => {
                    setupShowcaseMap(); 

                    // STEP 3: Trigger IN (Map Rises Up + Blur Fades Out)
                    setTransitionPhase('IN'); 

                    // Wait 1.2s for IN animation to assemble
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        setShowUnitDetail(false);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        // Fisher-Yates shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    // Initial Start
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    // Stats Loop
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    // Time Scale Sync
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    // --- HANDLERS ---

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        // Quick Spawn logic for manual random
        const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        });
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };
        for(let i=0; i<5; i++) spawn(Team.BLUE);
        for(let i=0; i<5; i++) spawn(Team.RED);

        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        // Reuse random logic but start playing immediately
        handleRandomBattlefield();

        // Need to wait a tick for agents to be ready? 
        // handleRandomBattlefield runs synchronously, so we can just play.
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;

        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }

            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
        if (!a) setShowUnitDetail(false);
    };

    // --- RETURN ---
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB,
            showUnitDetail, transitionPhase, showFactionWarning
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, 
            setShowUnitDetail, setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel, // New action
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) }, // Manual trigger shim
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); // FIX: Explicitly start engine
                setIsPlaying(true); 
            }
        }
    };
};

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point } from "../types";

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
}

// FFT Style Isometric Constants
const ANGLE = Math.PI / 4;
const SIN_A = Math.sin(ANGLE);
const COS_A = Math.cos(ANGLE);

// --- Integer Hashing Constants ---
// Hash = (q + 128) << 16 | (r + 128)
const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

// --- VISUAL UTILS ---

/**
 * Calculates the vertical visual offset for map transitions (Flying in/out).
 * WAVE LOGIC V5: Inverted Gravity.
 * OUT: Falls DOWN (+Y).
 * IN: Rises UP from below (+Y to 0).
 */
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;

    const centerQ = Math.floor(mapConfig.w / 2);
    const centerR = Math.floor(mapConfig.h / 2);
    const hex = HexUtils.fromPx(x, y, mapConfig);

    const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
    const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);

    // Normalize distance 0 to 1
    const d = Math.min(1, dist / maxDist);
    const BASE_OFFSET = 1200;

    if (phase === 'OUT') {
        // LEAVING: Tiles fall DOWN (Gravity).
        // Center leaves first, edges follow.
        // t: 0 -> 1

        // Effective Time with lag
        // Center (d=0): moves immediately
        // Edge (d=1): waits slightly
        const lag = 1 + d * 1.5; 
        const effectiveT = Math.pow(t, lag);

        // Quadratic acceleration DOWN (Positive Y)
        return effectiveT * effectiveT * BASE_OFFSET;

    } else if (phase === 'IN') {
        // ARRIVING: Tiles rise UP from below (Abyss).
        // T=0 -> Offset = +1200
        // T=1 -> Offset = 0

        // Lag: Edges arrive later than center
        // Center: fast finish. Edges: slow finish.
        const lag = 1 + d * 1.5;
        const progress = Math.pow(t, lag); 

        // Eased landing
        const eased = 1 - Math.pow(1 - progress, 3);

        // Start at positive offset (Below) -> 0
        return (1 - eased) * BASE_OFFSET;
    }
    return 0;
}

export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        const q = col - (row - (row & 1)) / 2;
        const r = row;
        return { q: Math.floor(q), r };
    },

    toPx: (q: number, r: number, config: MapConfig): Point => {
        const cx = (Math.sqrt(3) * q + Math.sqrt(3) / 2 * r) * HEX_SIZE;
        const cy = (1.5 * r) * HEX_SIZE; 

        const rx = cx * COS_A - cy * SIN_A;
        const ry = cx * SIN_A + cy * COS_A;

        return { 
            x: config.offsetX + rx, 
            y: config.offsetY + ry * ISO_SCALE_Y 
        };
    },

    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const dx = x - config.offsetX;
        const dy = y - config.offsetY;
        const unsquashedY = dy / ISO_SCALE_Y;

        const cx = dx * COS_A + unsquashedY * SIN_A;
        const cy = -dx * SIN_A + unsquashedY * COS_A;

        const q = (Math.sqrt(3)/3 * cx - 1/3 * cy) / HEX_SIZE;
        const r = (2/3 * cy) / HEX_SIZE;

        return HexUtils.round(q, r);
    },

    round: (q: number, r: number): Hex => {
        let s = -q - r;
        let qi = Math.round(q);
        let ri = Math.round(r);
        let si = Math.round(s);
        const q_diff = Math.abs(qi - q);
        const r_diff = Math.abs(ri - r);
        const s_diff = Math.abs(si - s);

        if (q_diff > r_diff && q_diff > s_diff) qi = -ri - si;
        else if (r_diff > s_diff) ri = -qi - si;

        return { q: qi, r: ri };
    },

    dist: (a: Hex, b: Hex): number => {
        const aq = Math.round(a.q); const ar = Math.round(a.r);
        const bq = Math.round(b.q); const br = Math.round(b.r);
        return (Math.abs(aq - bq) + Math.abs(aq + ar - bq - br) + Math.abs(ar - br)) / 2;
    },

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: FROSTED GLASS TRANSITIONS (Victory / Map Swap) ---
        // Enhanced Logic: Strict Sync
        let blurAmount = 0;

        if (engine.isFinishing) {
            // 1. Victory Phase: Blur Ramps 0 -> 1
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // 2. Bridge Gap: Blur Holds at 1.0
            blurAmount = 1.0;
        }

        // Transition Overrides
        // Logic:
        // OUT: Map Falls. Blur stays at 1.0 to hide the fall and connect with Victory.
        // IN: Map Rises. Blur fades 1.0 -> 0.0 to reveal the new map.
        if (this.transitionPhase === 'OUT') {
            blurAmount = 1.0; 
        } else if (this.transitionPhase === 'IN') {
            // 1 -> 0
            // Linear fade out to perfectly match the tile landing at t=1.0
            blurAmount = 1.0 - this.transitionT;
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Draw Trail ---
        // Using the pre-calculated visual trail points in op.pTrail
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = op.pColor;

            // Trail Width Logic: Tapering
            // We iterate through the visual points (Screen Space relative to map origin)

            // Draw the line strip
            ctx.beginPath();

            const trail = op.pTrail;
            if (trail.length > 0) {
                // The first point in trail array is the HEAD (newest)
                ctx.moveTo(trail[0].x, trail[0].y);
                for(let i=1; i<trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
            }

            // Style: Fade out
            const grad = ctx.createLinearGradient(trail[0].x, trail[0].y, trail[trail.length-1].x, trail[trail.length-1].y);
            grad.addColorStop(0, op.pColor); // Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Tail

            ctx.strokeStyle = grad;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();

            // Inner Core Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.6;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        // Simple blob shadow on ground
        // We use pVisShadowY stored in op
        const shadowAltitude = op.pVisShadowY - op.pVisY; // Difference between ground and air

        // Don't draw shadow if too low (to avoid clipping with sprite)
        // Or if really high, shadow fades
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            // Scale shadow based on height (higher = smaller/blurrier)
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);

            ctx.scale(shadowScale, shadowScale * 0.5); // Flattened ellipse
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

