    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: FROSTED GLASS TRANSITIONS (Victory / Map Swap) ---
        // Enhanced Logic: Strict Sync
        let blurAmount = 0;

        if (engine.isFinishing) {
            // 1. Victory Phase: Blur Ramps 0 -> 1
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // 2. Bridge Gap: Blur Holds at 1.0
            blurAmount = 1.0;
        }

        // Transition Overrides
        // Logic:
        // OUT: Map Falls. Blur stays at 1.0 to hide the fall and connect with Victory.
        // IN: Map Rises. Blur fades 1.0 -> 0.0 to reveal the new map.
        if (this.transitionPhase === 'OUT') {
            blurAmount = 1.0; 
        } else if (this.transitionPhase === 'IN') {
            // 1 -> 0
            // Linear fade out to perfectly match the tile landing at t=1.0
            blurAmount = 1.0 - this.transitionT;
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Ribbon Trail (Kinetic Energy Look) ---
        if (op.pTrail && op.pTrail.length > 2) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';

            // Build the ribbon polygon
            // For each point, calculate normal vector to get thickness

            const trail = op.pTrail;

            // Helper to get normals
            const getNorm = (idx: number) => {
                let dx, dy;
                if (idx < trail.length - 1) {
                    dx = trail[idx+1].x - trail[idx].x;
                    dy = trail[idx+1].y - trail[idx].y;
                } else {
                    dx = trail[idx].x - trail[idx-1].x;
                    dy = trail[idx].y - trail[idx-1].y;
                }
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len === 0) return { x: 0, y: 0 };
                return { x: -dy/len, y: dx/len };
            };

            // Draw filled polygon for glowy trail
            ctx.beginPath();

            // Forward pass (Right side of ribbon)
            const maxWidth = 6; 
            for(let i=0; i<trail.length; i++) {
                const width = maxWidth * (1 - i / trail.length); // Taper to tail
                const norm = getNorm(i);
                ctx.lineTo(trail[i].x + norm.x * width, trail[i].y + norm.y * width);
            }

            // Backward pass (Left side of ribbon)
            for(let i=trail.length-1; i>=0; i--) {
                const width = maxWidth * (1 - i / trail.length);
                const norm = getNorm(i);
                ctx.lineTo(trail[i].x - norm.x * width, trail[i].y - norm.y * width);
            }
            ctx.closePath();

            // Gradient fill along the path
            const head = trail[0];
            const tail = trail[trail.length-1];
            const grad = ctx.createLinearGradient(head.x, head.y, tail.x, tail.y);
            grad.addColorStop(0, op.pColor); // Bright Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Fade Tail

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.6;
            ctx.fill();

            // Core line
            ctx.beginPath();
            ctx.moveTo(head.x, head.y);
            for(let i=1; i<trail.length; i++) ctx.lineTo(trail[i].x, trail[i].y);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const shadowAltitude = op.pVisShadowY - op.pVisY; 
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);
            ctx.scale(shadowScale, shadowScale * 0.5); 
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);

            // LENS FLARE (Sci-Fi Cross Dazzle)
            if (op.pSkillVis === 'BOLT' || op.pSkillVis === 'ARROW') {
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.8;
                ctx.rotate(-op.pAngle); // Counter-rotate to keep flare upright relative to screen? Or align with motion?
                // Let's align flare with motion
                ctx.rotate(op.pAngle); 

                // Draw cross
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                // Horizontal
                ctx.ellipse(20, 0, 30, 2, 0, 0, Math.PI*2);
                ctx.fill();
                // Vertical
                ctx.beginPath();
                ctx.ellipse(20, 0, 4, 20, 0, 0, Math.PI*2);
                ctx.fill();
            }
        }
        ctx.restore();
    }
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS (Fixes "Floating" feeling) ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.4 - (p.z / 400));
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;
                const perspective = 1.0 + (p.z * 0.002);
                ctx.rotate(p.rotation);
                const scale = (p.size / 64) * perspective; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); // Pulse
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 
            ctx.globalAlpha = fade * 0.8;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'CHIP') {
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4);
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(2.0, 1 + speed / 1000);
            ctx.scale(stretch, 1/stretch);
            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            ctx.globalAlpha = (1 - progress) * 0.3;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                // Modern Helix Beam
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            const vel = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            if (vel > 50) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                ctx.scale(1 + vel/500, 0.5);
            }
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM (Laser with sine wave wrapping)
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        // Move context to start point
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter'; // or 'screen'

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;

        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        // Increased width for punchier look
        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // 1. Core Beam (White hot center)
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 8; // Bloom
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(dist, 0);
        ctx.stroke();
        ctx.shadowBlur = 0; // Reset

        // 2. Glow (Color Aura)
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; // Wider glow
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(dist, 0);
        ctx.stroke();

        // 3. Helix / Sine Wave Wrapper
        const freq = 0.12; // Higher frequency
        const amp = 8 * (1 - progress); // Wider amplitude
        const phase = Date.now() * 0.025; // Faster spin

        ctx.lineWidth = 2; // Thicker lines
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; // Color lines

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Double helix (inverse phase)
        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // 4. Impact Flares (Start & End)
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;

        // Start
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        // End
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG (Procedural)
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; 
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); 

        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);
            drawHex();
            ctx.clip();
            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();

            ctx.globalCompositeOperation = 'lighter';
            const puffs = 3;
            for(let i=0; i<puffs; i++) {
                const t = (Date.now() / 1000 + i * 100) % 1;
                const yPos = 10 - t * 60; 
                const scale = 1 + t * 0.5;
                const puffAlpha = fade * (1 - t);
                ctx.globalAlpha = puffAlpha * 0.4;
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.ellipse((Math.sin(t*10 + i)*5), yPos, 15 * scale, 8 * scale, 0, 0, Math.PI*2);
                ctx.fill();
            }

        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();
            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();

            ctx.shadowBlur = 0;
            ctx.fillStyle = '#fff';
            const beams = 4;
            for(let i=0; i<beams; i++) {
                const angle = (Date.now() / 2000 + i * (Math.PI*2/beams)) % (Math.PI*2);
                const r = 15;
                const px = Math.cos(angle) * r;
                const py = Math.sin(angle) * r * 0.58;
                const beamHeight = 40 + Math.sin(Date.now()/500 + i)*10;
                const grad = ctx.createLinearGradient(0, py, 0, py - beamHeight);
                grad.addColorStop(0, `rgba(255,255,255,${fade * 0.5})`);
                grad.addColorStop(1, 'rgba(255,255,255,0)');
                ctx.fillStyle = grad;
                ctx.fillRect(px - 1, py - beamHeight, 2, beamHeight);
            }
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 3.0 (Solid Beam of Light)
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;
        // Easing: Fade in fast, hold, fade out
        let alpha = lifeRatio > 0.8 ? (1 - lifeRatio) * 5 : (lifeRatio < 0.2 ? lifeRatio * 5 : 1.0);

        const maxHeight = 1200;
        // const currentHeight = maxHeight * (progress < 0.1 ? progress * 10 : 1.0);
        const width = p.size; // Radius

        ctx.save();
        ctx.globalCompositeOperation = 'screen'; // Max brightness

        // 1. Hexagonal Base Ring (Rotating)
        ctx.save();
        ctx.scale(1, 0.58);
        ctx.rotate(Date.now() * 0.002);

        // Fill Base with color (Ground Contact)
        ctx.fillStyle = p.color;
        ctx.globalAlpha = alpha * 0.4;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const a = i * Math.PI / 3;
            const hx = Math.cos(a) * width;
            const hy = Math.sin(a) * width;
            if(i===0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
        }
        ctx.closePath();
        ctx.fill();

        // Stroke
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        ctx.globalAlpha = alpha * 0.8;
        ctx.stroke();

        // Inner Hex (Counter-rotate)
        ctx.rotate(Date.now() * -0.004);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const a = i * Math.PI / 3;
            const hx = Math.cos(a) * (width * 0.6);
            const hy = Math.sin(a) * (width * 0.6);
            if(i===0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
        }
        ctx.closePath();
        ctx.stroke();
        ctx.restore();

        // 2. Central Core Beam (Solid Light Shaft)
        // Using Horizontal Gradient to simulate cylinder volume
        const coreWidth = width * 0.5;
        const beamGrad = ctx.createLinearGradient(-coreWidth, 0, coreWidth, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, '#ffffff'); // Pure white center
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.9;
        ctx.fillRect(-coreWidth, -maxHeight, coreWidth * 2, maxHeight);

        // 3. Floodlight / Outer Aura (Wide)
        const auraWidth = width * 1.5;
        const auraGrad = ctx.createLinearGradient(-auraWidth, 0, auraWidth, 0);
        auraGrad.addColorStop(0, 'rgba(0,0,0,0)');
        auraGrad.addColorStop(0.5, p.color);
        auraGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = auraGrad;
        ctx.globalAlpha = alpha * 0.4;
        ctx.fillRect(-auraWidth, -maxHeight, auraWidth * 2, maxHeight);

        // 4. Rising Particles / Data Blocks (Thicker & Brighter)
        const lines = 8;
        for(let i=0; i<lines; i++) {
            const offsetX = (Math.random() - 0.5) * width * 1.6;
            const speed = 2500 + Math.random() * 1500;
            const yPos = -((Date.now() * speed / 2000 + i * 137) % maxHeight);

            ctx.fillStyle = '#fff';
            // Fake bloom via shadow
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.globalAlpha = alpha * (0.6 + Math.random()*0.4);

            const h = 50 + Math.random() * 100;
            ctx.fillRect(offsetX - 2, yPos, 4, h); // 4px wide lines
            ctx.shadowBlur = 0;
        }

        ctx.restore();
    },

    // 🩸 RED: BLOOD RITUAL (CHAOS)
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // 1. The Void (Ground Hole)
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); // Black center
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // 2. Cracks / Runes
         ctx.strokeStyle = p.color; // Red/Orange
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();

         // 3. Rising Dark Miasma (Noise)
         ctx.globalCompositeOperation = 'lighter'; // Glowy smoke
         ctx.fillStyle = p.color;
         const bubbles = 5;
         for(let i=0; i<bubbles; i++) {
             const bAngle = i * (Math.PI * 2 / bubbles) + progress * 2;
             const dist = r * 0.6;
             const bx = Math.cos(bAngle) * dist;
             const by = Math.sin(bAngle) * dist;
             const bSize = r * 0.3 * Math.sin(progress * 10 + i);

             ctx.globalAlpha = alpha * 0.3;
             ctx.beginPath(); ctx.arc(bx, by, Math.abs(bSize), 0, Math.PI*2); ctx.fill();
         }

         ctx.restore();

         // 4. Vertical "Heat" Haze (Not a pillar)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;

         ctx.beginPath();
         ctx.moveTo(-r/2, 0); 
         ctx.lineTo(-r/4, -300);
         ctx.lineTo(r/4, -300);
         ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 

        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            // Jagged
            ctx.globalCompositeOperation = 'source-over'; // Darker/Physical
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            // Smooth
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset, isChaosStyle } from "../utils";
import { Point } from "../../../../types";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             // Pre-calculate trajectory parameters
             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // --- Helper to get Visual Position (With Arc and Height) ---
             const getVisualPos = (lx: number, ly: number, flightProgress: number): { x: number, y: number, shadowY: number } => {
                 const t = flightProgress;
                 const trajectoryTerrainHeight = hStart + (hEnd - hStart) * t;
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const groundHeight = getTerrainHeight(currentHex.q, currentHex.r);

                 let arcOffset = 0;
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     const distFactor = Math.min(150, totalDist * 0.25);
                     const baseArc = p.skill.visual === 'BOMB' ? 100 : 20;
                     const arcHeight = baseArc + distFactor;
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 10;
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - trajectoryTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - groundHeight + off
                 };
             };

             // 1. Calculate Head Position
             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // 2. Rotation Calculation (Look Ahead)
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));
             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             // 3. Trail Calculation (Visual Points)
             // Map raw trail to visual positions
             const visualTrail: Point[] = [];
             if (p.trail.length > 1) {
                 // Add current head as start of trail
                 visualTrail.push({ x: headVis.x, y: headVis.y });

                 // Process history points
                 for (let i = p.trail.length - 1; i >= 0; i--) {
                     const tp = p.trail[i];
                     const tDist = Vector.dist({x: p.startX, y: p.startY}, tp);
                     const tProg = Math.min(1, Math.max(0, tDist / totalDist));
                     const tv = getVisualPos(tp.x, tp.y, tProg);
                     visualTrail.push({ x: tv.x, y: tv.y });
                 }
             }

             // Submit Op
             const op = renderList.next();
             op.type = RenderOpType.PROJECTILE;
             op.y = p.y + 50 + offsetP; 
             op.z = 20;

             op.proj = p;
             op.pVisX = headVis.x;
             op.pVisY = headVis.y;
             op.pVisShadowY = headVis.shadowY;
             op.pSkillVis = p.skill.visual || 'BOLT';
             op.pColor = p.skill.color;
             op.pIsUlt = p.skill.tag === 'ULT';
             op.pAngle = angle;
             op.pSpin = spin;
             op.pTrail = visualTrail; 
        });
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    // UPDATED: Now performs proper Screen->World transform taking center pivot into account
    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        // Center Pivot Logic (Matching ApplyTransform)
        // Screen = (World - Cam) * Zoom + Center
        // World = (Screen - Center) / Zoom + Cam
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        // Updated Sync: Purely syncs pos/zoom, removed mapConfig args
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (No allocation)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Pass globalTime to TerrainRenderer for animations
                    TerrainRenderer.drawBlockGeometry(
                        ctx, op.tx, op.ty, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, op.tx, op.ty - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, op.tx, op.ty - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oFlash, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, op.tx - OBSTACLE_HALF_WIDTH, op.ty);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, op.tx, op.ty, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(op.tx, op.ty);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        ctx.save();
                        ctx.translate(op.tx, op.ty); // Visual position
                        const pProxy = op.particle;
                        const originalX = pProxy.x; 
                        const originalY = pProxy.y;
                        pProxy.x = 0; pProxy.y = 0; // Relative to context

                        ParticleRenderer.drawSingleParticle(ctx, pProxy, op.vProgress, op.vChaos);

                        pProxy.x = originalX; pProxy.y = originalY; // Restore
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Top VFX (Particles above everything, e.g. Weather or High flying magic)
        // Kept before Post-Process to allow them to glow/bloom properly.
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // --- POST PROCESSING BARRIER (Bloom / Shake) ---
        ctx.restore(); // Exit Camera Space

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma());

        ctx.save(); // Prepare for UI overlays (Screen Space or World Space projection)

        // RE-APPLY CAMERA TRANSFORM for World-Space UI (Tactical Lines, HUD Bars)
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 8. Tactical Overlay Lines (Clean lines, no bloom/ghosting)
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 9. HUD (Health bars, floating text)
        // PASSED highlight Agent for Selection Glow
        this.hud.draw(ctx, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); // Exit Camera Space

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        // 11. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);

        // --- FINAL PASS: FROSTED GLASS TRANSITIONS (Victory / Map Swap) ---
        // Enhanced Logic: Strict Sync
        let blurAmount = 0;

        if (engine.isFinishing) {
            // 1. Victory Phase: Blur Ramps 0 -> 1
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            // 2. Bridge Gap: Blur Holds at 1.0
            blurAmount = 1.0;
        }

        // Transition Overrides
        // Logic:
        // OUT: Map Falls. Blur stays at 1.0 to hide the fall and connect with Victory.
        // IN: Map Rises. Blur fades 1.0 -> 0.0 to reveal the new map.
        if (this.transitionPhase === 'OUT') {
            blurAmount = 1.0; 
        } else if (this.transitionPhase === 'IN') {
            // 1 -> 0
            // Linear fade out to perfectly match the tile landing at t=1.0
            blurAmount = 1.0 - this.transitionT;
        }

        if (blurAmount > 0) {
            const clampedProgress = Math.max(0, Math.min(1, blurAmount));
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, clampedProgress);
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- 1. Ribbon Trail (Kinetic Energy Look) ---
        if (op.pTrail && op.pTrail.length > 2) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';

            // Build the ribbon polygon
            // For each point, calculate normal vector to get thickness

            const trail = op.pTrail;

            // Helper to get normals
            const getNorm = (idx: number) => {
                let dx, dy;
                if (idx < trail.length - 1) {
                    dx = trail[idx+1].x - trail[idx].x;
                    dy = trail[idx+1].y - trail[idx].y;
                } else {
                    dx = trail[idx].x - trail[idx-1].x;
                    dy = trail[idx].y - trail[idx-1].y;
                }
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len === 0) return { x: 0, y: 0 };
                return { x: -dy/len, y: dx/len };
            };

            // Draw filled polygon for glowy trail
            ctx.beginPath();

            // Forward pass (Right side of ribbon)
            const maxWidth = 6; 
            for(let i=0; i<trail.length; i++) {
                const width = maxWidth * (1 - i / trail.length); // Taper to tail
                const norm = getNorm(i);
                ctx.lineTo(trail[i].x + norm.x * width, trail[i].y + norm.y * width);
            }

            // Backward pass (Left side of ribbon)
            for(let i=trail.length-1; i>=0; i--) {
                const width = maxWidth * (1 - i / trail.length);
                const norm = getNorm(i);
                ctx.lineTo(trail[i].x - norm.x * width, trail[i].y - norm.y * width);
            }
            ctx.closePath();

            // Gradient fill along the path
            const head = trail[0];
            const tail = trail[trail.length-1];
            const grad = ctx.createLinearGradient(head.x, head.y, tail.x, tail.y);
            grad.addColorStop(0, op.pColor); // Bright Head
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Fade Tail

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.6;
            ctx.fill();

            // Core line
            ctx.beginPath();
            ctx.moveTo(head.x, head.y);
            for(let i=1; i<trail.length; i++) ctx.lineTo(trail[i].x, trail[i].y);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2; // Increased from 1 to 2
            ctx.stroke();

            ctx.restore();
        }

        // --- 2. Draw Shadow ---
        const shadowAltitude = op.pVisShadowY - op.pVisY; 
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(op.pVisX, op.pVisShadowY);
            const shadowScale = Math.max(0.2, 1 - Math.abs(shadowAltitude)/600);
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);
            ctx.scale(shadowScale, shadowScale * 0.5); 
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        // --- 3. Draw Projectile Head ---
        ctx.save();
        ctx.translate(op.pVisX, op.pVisY);

        if (op.pSkillVis === 'BOMB') ctx.rotate(op.pSpin);
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            if (op.pSkillVis === 'BOMB' || op.pSkillVis === 'FIREBALL') scale *= 1.2;

            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);

            // LENS FLARE (Sci-Fi Cross Dazzle)
            if (op.pSkillVis === 'BOLT' || op.pSkillVis === 'ARROW') {
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.8;
                ctx.rotate(-op.pAngle); // Counter-rotate to keep flare upright relative to screen? Or align with motion?
                // Let's align flare with motion
                ctx.rotate(op.pAngle); 

                // Draw cross
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                // Horizontal
                ctx.ellipse(20, 0, 30, 2, 0, 0, Math.PI*2);
                ctx.fill();
                // Vertical
                ctx.beginPath();
                ctx.ellipse(20, 0, 4, 20, 0, 0, Math.PI*2);
                ctx.fill();
            }
        }
        ctx.restore();
    }
}

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

// Pseudo-Random Noise generator for textures
function pseudoNoise(x: number, y: number, seed: number) {
    const n = Math.sin(x * 12.9898 + y * 78.233 + seed) * 43758.5453;
    return n - Math.floor(n);
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         // Modern "Hot Core" Glow
         const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
         grad.addColorStop(0, '#ffffff');        // White hot center
         grad.addColorStop(0.2, color);          // Intense inner color
         grad.addColorStop(0.5, color);          // Falloff start
         grad.addColorStop(1, 'rgba(0,0,0,0)');  // Fade out

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable plasma blob with spikes
             ctx.beginPath();
             const spikes = 16;
             for(let i=0; i<spikes; i++) {
                 const angle = (i / spikes) * Math.PI * 2;
                 // Randomize radius for jagged look
                 const rad = r * (0.6 + Math.random() * 0.4);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Smooth Sphere with Halo
             ctx.beginPath(); 
             ctx.arc(cx, cy, r * 0.8, 0, Math.PI * 2); 
             ctx.fill();

             // Lens Flare Ring
             ctx.strokeStyle = 'rgba(255,255,255,0.3)';
             ctx.lineWidth = 1;
             ctx.beginPath(); ctx.arc(cx, cy, r * 0.5, 0, Math.PI*2); ctx.stroke();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        // Multi-layered noise cloud
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.2; // Softer base

        // Draw multiple overlapping blobs to simulate volume
        for(let i=0; i<16; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.35);
            const size = FOG_SIZE * (0.1 + Math.random() * 0.15);

            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, size, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            // Chaos Rune: Spiky, Broken
            ctx.beginPath();
            const points = 7; // Odd number for asymmetry
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                const r = radius * (0.8 + Math.random() * 0.2); 
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            // Inner Scratch
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 20, cy - 20); ctx.lineTo(cx + 20, cy + 20);
            ctx.moveTo(cx + 20, cy - 20); ctx.lineTo(cx - 20, cy + 20);
            ctx.stroke();

        } else {
            // Order Rune: Geometric, Perfect
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1.5;
            if (isUlt) {
                // Complex Mandala
                const drawPoly = (sides: number, r: number, offset: number) => {
                    ctx.beginPath();
                    for (let i = 0; i <= sides; i++) {
                        const angle = offset + (i * Math.PI * 2) / sides;
                        const x = cx + Math.cos(angle) * r;
                        const y = cy + Math.sin(angle) * r;
                        if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.closePath();
                    ctx.stroke();
                };

                drawPoly(3, radius, -Math.PI/2); // Triangle Up
                drawPoly(3, radius, Math.PI/2);  // Triangle Down (Star of David style)

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.4, 0, Math.PI*2); ctx.stroke();

            } else {
                // Simple Rune
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(Math.PI/4);
                ctx.strokeRect(-radius * 0.6, -radius * 0.6, radius * 1.2, radius * 1.2);
                ctx.restore();

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.8, 0, Math.PI*2); ctx.stroke();
            }
        }

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;

        // Modern "Neon" Style - Less blur, more bloom
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // High-Tech Arrow (Kinetic Rod)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 3;
                ctx.beginPath(); ctx.moveTo(20, cy); ctx.lineTo(70, cy); ctx.stroke();

                // Glowing Head
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(80, cy); 
                ctx.lineTo(60, cy - 6); 
                ctx.lineTo(65, cy); 
                ctx.lineTo(60, cy + 6);
                ctx.fill();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Plasma Orb
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 18);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.3, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;

                ctx.beginPath(); ctx.arc(cx + 20, cy, 16, 0, Math.PI * 2); ctx.fill();

                // Trailing arcs
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.6;
                ctx.beginPath();
                ctx.arc(cx + 20, cy, 12, Math.PI * 0.2, Math.PI * 1.8);
                ctx.stroke();
                break;

            case 'SLASH':
                // Energy Wave
                ctx.translate(cx, cy);
                ctx.beginPath();
                ctx.arc(0, 0, 30, -Math.PI/3, Math.PI/3, false);
                ctx.arc(-10, 0, 25, Math.PI/3, -Math.PI/3, true);
                ctx.closePath();
                ctx.fillStyle = '#fff';
                ctx.fill();

                ctx.strokeStyle = color;
                ctx.lineWidth = 4;
                ctx.stroke();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                // Sci-Fi Energy Slug
                const boltPath = new Path2D();
                boltPath.moveTo(cx + 40, cy);      // Tip
                boltPath.lineTo(cx + 10, cy - 8);  // Top
                boltPath.lineTo(cx - 20, cy);      // Tail Center
                boltPath.lineTo(cx + 10, cy + 8);  // Bottom
                boltPath.closePath();

                ctx.fillStyle = '#fff';
                ctx.fill(boltPath);

                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.stroke(boltPath);

                // Side vents
                ctx.beginPath();
                ctx.moveTo(cx, cy - 10); ctx.lineTo(cx - 10, cy - 15);
                ctx.moveTo(cx, cy + 10); ctx.lineTo(cx - 10, cy + 15);
                ctx.stroke();
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        // Isometric Flatten
        ctx.scale(1, 0.5); 

        // 1. Cracks (Voronoi-like lines)
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        for(let i=0; i<8; i++) {
            const angle = (i / 8) * Math.PI * 2;
            const r1 = 10;
            const r2 = 40 + Math.random() * 20;
            ctx.moveTo(cx + Math.cos(angle)*r1, cy*2 + Math.sin(angle)*r1);
            // Jagged line
            const mx = cx + Math.cos(angle + 0.2) * (r1+r2)/2;
            const my = cy*2 + Math.sin(angle + 0.2) * (r1+r2)/2;
            ctx.lineTo(mx, my);
            ctx.lineTo(cx + Math.cos(angle)*r2, cy*2 + Math.sin(angle)*r2);
        }
        ctx.stroke();

        // 2. Central Scorch Mark
        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 45);
        if (isChaos) {
            grad.addColorStop(0, '#000'); 
            grad.addColorStop(0.6, 'rgba(0,0,0,0.8)');
            grad.addColorStop(1, 'transparent');
        } else {
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.3, color);
            grad.addColorStop(1, 'transparent');
        }

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.9;
        ctx.beginPath(); ctx.arc(cx, cy * 2, 45, 0, Math.PI*2); ctx.fill();

        return canvas;
    },

    generateJaggedShockwave(): HTMLCanvasElement {
        const size = 128;
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 4;
        ctx.lineJoin = 'miter';

        // Draw jagged expanding ring
        ctx.beginPath();
        const segments = 16;
        const r = 40;
        for(let i=0; i<=segments; i++) {
            const a = (i / segments) * Math.PI * 2;
            const spike = (i % 2 === 0) ? 10 : -10;
            const x = cx + Math.cos(a) * (r + spike);
            const y = cy + Math.sin(a) * (r + spike);
            if (i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.stroke();

        return canvas;
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); // Lighter shadow
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Stretched by velocity)
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            const stretch = Math.min(3.0, 1.0 + speed / 300); // Stretch based on speed
            const angle = Math.atan2(p.vy, p.vx); // Align with motion

            ctx.rotate(angle);
            ctx.scale(stretch, 1.0 / Math.sqrt(stretch)); // Maintain volume perception (stretch X, squash Y)

            ctx.globalCompositeOperation = 'lighter'; // Additive blending for glow
            ctx.globalAlpha = (1 - progress); 

            // Diamond Shape (Sharper than circle)
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.moveTo(p.size, 0);
            ctx.lineTo(0, p.size * 0.6);
            ctx.lineTo(-p.size, 0);
            ctx.lineTo(0, -p.size * 0.6);
            ctx.fill();

            // White Hot Core
            ctx.fillStyle = '#fff';
            ctx.scale(0.5, 0.5);
            ctx.beginPath();
            ctx.moveTo(p.size, 0);
            ctx.lineTo(0, p.size * 0.6);
            ctx.lineTo(-p.size, 0);
            ctx.lineTo(0, -p.size * 0.6);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE (Cluster of puffs)
            const scale = 0.5 + progress * 1.5; // Expands
            const alpha = (1 - progress) * 0.4;

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress); // Slowly rotates
            ctx.globalAlpha = alpha;
            ctx.fillStyle = p.color;

            // Draw cluster
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.arc(p.size*0.5, p.size*0.5, p.size*0.6, 0, Math.PI*2);
            ctx.arc(-p.size*0.4, -p.size*0.3, p.size*0.7, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 ENERGY RIPPLE (Sonic Boom)
            ctx.scale(1, 0.55); // Isometric
            const r = progress * p.size * 2; // Expands outward

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;

            // Main Ring
            ctx.lineWidth = (1 - progress) * 4;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

            // Echo Ring (Inner)
            if (progress > 0.2) {
                ctx.lineWidth = (1 - progress) * 2;
                ctx.globalAlpha = (1 - progress) * 0.5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
            }

        } else if (p.type === 'BLAST') {
            // 💥 SPIKED EXPLOSION
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 6; 
            ctx.globalAlpha = (1 - progress);

            // Spiky Circle
            ctx.beginPath(); 
            const spikes = 12;
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                // Add noise to radius
                const rad = r * (1.0 + (i%2===0 ? 0.2 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 SPINNING DEBRIS
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;

            // Rim Light effect by drawing border
            ctx.strokeStyle = 'rgba(255,255,255,0.8)';
            ctx.lineWidth = 1;

            if (p.type === 'CHIP') {
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            } else {
                // Irregular triangle
                ctx.beginPath();
                ctx.moveTo(-p.size, -p.size/2); 
                ctx.lineTo(p.size, 0); 
                ctx.lineTo(0, p.size); 
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }

        } else if (p.type === 'GLOW') {
            // ✨ STATIC GLOW ORB (Pre-rendered)
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); // Pulse: Fade In -> Fade Out
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.9;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;
                const perspective = 1.0 + (p.z * 0.002);
                ctx.rotate(p.rotation);
                const scale = (p.size / 64) * perspective; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM (Optimized)
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Helix
        const freq = 0.12; 
        const amp = 8 * (1 - progress); 
        const phase = Date.now() * 0.025; 

        ctx.lineWidth = 2; 
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; 

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Flares
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; 
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);
            drawHex();
            ctx.clip();
            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();
        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();
            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 3.0
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;
        let alpha = lifeRatio > 0.8 ? (1 - lifeRatio) * 5 : (lifeRatio < 0.2 ? lifeRatio * 5 : 1.0);
        const maxHeight = 1200;
        const width = p.size; 

        ctx.save();
        ctx.globalCompositeOperation = 'screen'; 

        // Base
        ctx.save();
        ctx.scale(1, 0.58);
        ctx.rotate(Date.now() * 0.002);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = alpha * 0.4;
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = p.color; ctx.lineWidth = 3; ctx.globalAlpha = alpha * 0.8; ctx.stroke();
        ctx.restore();

        // Beam
        const coreWidth = width * 0.5;
        const beamGrad = ctx.createLinearGradient(-coreWidth, 0, coreWidth, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, '#ffffff'); 
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.9;
        ctx.fillRect(-coreWidth, -maxHeight, coreWidth * 2, maxHeight);

        // Data Streams
        const lines = 8;
        for(let i=0; i<lines; i++) {
            const offsetX = (Math.random() - 0.5) * width * 1.6;
            const speed = 2500 + Math.random() * 1500;
            const yPos = -((Date.now() * speed / 2000 + i * 137) % maxHeight);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha * (0.6 + Math.random()*0.4);
            ctx.fillRect(offsetX - 2, yPos, 4, 100); 
        }
        ctx.restore();
    },

    // 🩸 BLOOD RITUAL
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // Void Hole
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); 
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Cracks
         ctx.strokeStyle = p.color; 
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();
         ctx.restore();

         // Rising Heat
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); ctx.lineTo(-r/4, -300); ctx.lineTo(r/4, -300); ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";
import { VFXFactory } from "../../graphics/VFXFactory"; 

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

// --- 1. FACTION ULTIMATES ---

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100; 
    p.type = 'PILLAR'; 
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 120; 
    p.type = 'DOMAIN'; 
    p.delay = 0;
    system.state.particles.push(p);

    // Add rising debris
    for(let i=0; i<8; i++) {
        const d = system.state.getParticle();
        d.x = x + (Math.random()-0.5)*50; 
        d.y = y + (Math.random()-0.5)*30; 
        d.z = 0;
        d.vx = (Math.random()-0.5)*50;
        d.vy = (Math.random()-0.5)*50;
        d.vz = 100 + Math.random() * 200; 
        d.life = life * 0.8; d.maxLife = life * 0.8;
        d.color = '#000'; 
        d.size = 5 + Math.random() * 8;
        d.type = 'DEBRIS';
        d.rotation = Math.random();
        d.vRotation = Math.random();
        system.state.particles.push(d);
    }
}

// --- 2. IMPACTS & EXPLOSIONS ---

export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.2; p.maxLife = 1.2;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);

    if (Math.random() > 0.5) {
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = 10;
        s.vx = 0; s.vy = 0; s.vz = 150; 
        s.life = 0.4; s.maxLife = 0.4;
        s.color = color; s.size = 20;
        s.type = 'SPARK';
        s.delay = delay;
        system.state.particles.push(s);
    }
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 3;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y + (Math.random()-0.5)*15;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 10 + Math.random() * 20; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 25 + Math.random() * 25; // Larger puffs
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    // Blast
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 20;
    blast.vx = 0; blast.vy = 0; blast.vz = 0;
    blast.life = 0.2; blast.maxLife = 0.2;
    blast.color = '#00ffff'; 
    blast.size = 100;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    // High Velocity Shards
    const shardCount = 12;
    for(let i=0; i<shardCount; i++) {
        const p = system.state.getParticle();
        const angle = (Math.PI * 2 * i) / shardCount;
        const speed = 400 + Math.random() * 400; 
        p.x = x; p.y = y; p.z = 30;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 300; 
        p.life = 0.5 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = Math.random() > 0.5 ? color : '#e2e8f0'; 
        p.size = 5 + Math.random() * 5;
        p.type = 'SHARD';
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 30; 
        system.state.particles.push(p);
    }

    // Chips
    const glitchCount = 8;
    for(let i=0; i<glitchCount; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*40;
        p.y = y + (Math.random()-0.5)*40;
        p.z = 40;
        p.vx = (Math.random()-0.5) * 50; 
        p.vy = (Math.random()-0.5) * 50;
        p.vz = 0;
        p.life = 0.3; p.maxLife = 0.3;
        p.color = Math.random() > 0.5 ? '#00ffff' : '#ff00ff';
        p.size = 4 + Math.random() * 4;
        p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = 10;
    const spread = 0.8; 

    // Directional Cone Sparks
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 400 + Math.random() * 400; // Faster sparks
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; 

        p.life = 0.3 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 4 + Math.random() * 6; // Larger kinetic sparks
        p.type = 'SPARK'; 
        p.delay = 0;
        system.state.particles.push(p);
    }

    if (isPhysical) {
        spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
    } else {
        // Magical impact ring
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = color;
        p.size = 20; 
        p.type = 'RING';
        system.state.particles.push(p);
    }
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 
        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 
        p.vx = Math.cos(angle) * dist; p.vy = Math.sin(angle) * dist; p.vz = vZ;
        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff'; p.size = 64 * scale; 
        p.type = 'SPRITE'; p.image = img;
        p.rotation = Math.random() * Math.PI * 2; p.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(p);
    };

    const baseColor = '#52525b';
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 50 + Math.random() * 100; 
        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor; p.size = 10 + Math.random() * 10;
        p.type = 'SHARD'; p.rotation = angle; p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    spawnSprite(assets.icon, 0.6, 70, 300);   

    addDecal(system, x, y, '#000'); 
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        // Higher velocity spread for kinetic feel
        const spd = Math.random() * 200 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 200 + 100) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        // Size varies more
        p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 20 + 20;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         // Modern "Hot Core" Glow
         const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
         grad.addColorStop(0, '#ffffff');        // White hot center
         grad.addColorStop(0.2, color);          // Intense inner color
         grad.addColorStop(0.5, color);          // Falloff start
         grad.addColorStop(1, 'rgba(0,0,0,0)');  // Fade out

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable plasma blob with spikes
             ctx.beginPath();
             const spikes = 16;
             for(let i=0; i<spikes; i++) {
                 const angle = (i / spikes) * Math.PI * 2;
                 // Randomize radius for jagged look
                 const rad = r * (0.6 + Math.random() * 0.4);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Smooth Sphere with Halo
             ctx.beginPath(); 
             ctx.arc(cx, cy, r * 0.8, 0, Math.PI * 2); 
             ctx.fill();

             // Lens Flare Ring
             ctx.strokeStyle = 'rgba(255,255,255,0.3)';
             ctx.lineWidth = 1;
             ctx.beginPath(); ctx.arc(cx, cy, r * 0.5, 0, Math.PI*2); ctx.stroke();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        // Multi-layered noise cloud
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.2; // Softer base

        // Draw multiple overlapping blobs to simulate volume
        for(let i=0; i<16; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.35);
            const size = FOG_SIZE * (0.1 + Math.random() * 0.15);

            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, size, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            // Chaos Rune: Spiky, Broken
            ctx.beginPath();
            const points = 7; // Odd number for asymmetry
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                const r = radius * (0.8 + Math.random() * 0.2); 
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            // Inner Scratch
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 20, cy - 20); ctx.lineTo(cx + 20, cy + 20);
            ctx.moveTo(cx + 20, cy - 20); ctx.lineTo(cx - 20, cy + 20);
            ctx.stroke();

        } else {
            // Order Rune: Geometric, Perfect
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1.5;
            if (isUlt) {
                // Complex Mandala
                const drawPoly = (sides: number, r: number, offset: number) => {
                    ctx.beginPath();
                    for (let i = 0; i <= sides; i++) {
                        const angle = offset + (i * Math.PI * 2) / sides;
                        const x = cx + Math.cos(angle) * r;
                        const y = cy + Math.sin(angle) * r;
                        if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.closePath();
                    ctx.stroke();
                };

                drawPoly(3, radius, -Math.PI/2); // Triangle Up
                drawPoly(3, radius, Math.PI/2);  // Triangle Down (Star of David style)

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.4, 0, Math.PI*2); ctx.stroke();

            } else {
                // Simple Rune
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(Math.PI/4);
                ctx.strokeRect(-radius * 0.6, -radius * 0.6, radius * 1.2, radius * 1.2);
                ctx.restore();

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.8, 0, Math.PI*2); ctx.stroke();
            }
        }

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;

        // Modern "Neon" Style - Less blur, more bloom
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // High-Tech Arrow (Kinetic Rod)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 3;
                ctx.beginPath(); ctx.moveTo(20, cy); ctx.lineTo(70, cy); ctx.stroke();

                // Glowing Head
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(80, cy); 
                ctx.lineTo(60, cy - 6); 
                ctx.lineTo(65, cy); 
                ctx.lineTo(60, cy + 6);
                ctx.fill();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Plasma Orb
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 18);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.3, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;

                ctx.beginPath(); ctx.arc(cx + 20, cy, 16, 0, Math.PI * 2); ctx.fill();

                // Trailing arcs
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.6;
                ctx.beginPath();
                ctx.arc(cx + 20, cy, 12, Math.PI * 0.2, Math.PI * 1.8);
                ctx.stroke();
                break;

            case 'SLASH':
                // Energy Wave
                ctx.translate(cx, cy);
                ctx.beginPath();
                ctx.arc(0, 0, 30, -Math.PI/3, Math.PI/3, false);
                ctx.arc(-10, 0, 25, Math.PI/3, -Math.PI/3, true);
                ctx.closePath();
                ctx.fillStyle = '#fff';
                ctx.fill();

                ctx.strokeStyle = color;
                ctx.lineWidth = 4;
                ctx.stroke();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                // Sci-Fi Energy Slug
                const boltPath = new Path2D();
                boltPath.moveTo(cx + 40, cy);      // Tip
                boltPath.lineTo(cx + 10, cy - 8);  // Top
                boltPath.lineTo(cx - 20, cy);      // Tail Center
                boltPath.lineTo(cx + 10, cy + 8);  // Bottom
                boltPath.closePath();

                ctx.fillStyle = '#fff';
                ctx.fill(boltPath);

                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.stroke(boltPath);

                // Side vents
                ctx.beginPath();
                ctx.moveTo(cx, cy - 10); ctx.lineTo(cx - 10, cy - 15);
                ctx.moveTo(cx, cy + 10); ctx.lineTo(cx - 10, cy + 15);
                ctx.stroke();
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        // Isometric Flatten
        ctx.scale(1, 0.5); 

        // 1. Scorch Marks (Not cracks)
        // Draw irregular blobs
        ctx.fillStyle = isChaos ? '#000' : '#475569';
        ctx.globalAlpha = 0.5;

        for(let i=0; i<3; i++) {
            ctx.beginPath();
            const r = 30 + Math.random() * 20;
            const offset = (Math.random() - 0.5) * 20;
            ctx.ellipse(cx + offset, cy*2 + offset, r, r * 0.6, Math.random(), 0, Math.PI*2);
            ctx.fill();
        }

        // 2. Energy Residual (Outer Ring)
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.4;
        ctx.beginPath(); ctx.arc(cx, cy * 2, 45, 0, Math.PI*2); ctx.stroke();

        // 3. Central Hotspot
        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 30);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.3;
        ctx.beginPath(); ctx.arc(cx, cy * 2, 30, 0, Math.PI*2); ctx.fill();

        return canvas;
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); // Lighter shadow
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Light Streaks)
            // No gravity feel. Just pure energy moving fast.
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            // Stretch based on speed, but clamp it
            const stretch = Math.min(4.0, 1.0 + speed / 150); 
            const angle = Math.atan2(p.vy, p.vx); // Align with motion

            ctx.rotate(angle);
            ctx.scale(stretch, 0.6); // Stretch length, squash width

            ctx.globalCompositeOperation = 'lighter'; // Additive blending for glow
            ctx.globalAlpha = Math.pow(1 - progress, 2); // Fade out non-linearly

            // Streamlined Shape
            const grad = ctx.createLinearGradient(-p.size, 0, p.size, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.2, p.color);
            grad.addColorStop(0.8, '#fff'); // Bright head
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE (Cluster of puffs)
            const scale = 0.5 + progress * 1.5; // Expands
            const alpha = (1 - progress) * 0.4;

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress); // Slowly rotates
            ctx.globalAlpha = alpha;
            ctx.fillStyle = p.color;

            // Draw cluster
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.arc(p.size*0.5, p.size*0.5, p.size*0.6, 0, Math.PI*2);
            ctx.arc(-p.size*0.4, -p.size*0.3, p.size*0.7, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 ENERGY RIPPLE (Sonic Boom)
            ctx.scale(1, 0.55); // Isometric
            const r = progress * p.size * 2; // Expands outward

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;

            // Main Ring
            ctx.lineWidth = (1 - progress) * 4;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

            // Echo Ring (Inner)
            if (progress > 0.2) {
                ctx.lineWidth = (1 - progress) * 2;
                ctx.globalAlpha = (1 - progress) * 0.5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
            }

        } else if (p.type === 'BLAST') {
            // 💥 SPIKED EXPLOSION
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 6; 
            ctx.globalAlpha = (1 - progress);

            // Spiky Circle
            ctx.beginPath(); 
            const spikes = 12;
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                // Add noise to radius
                const rad = r * (1.0 + (i%2===0 ? 0.2 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 ENERGY SHARD / MATERIAL CHIP
            // Only used for Unit Shatter effect now.
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;

            // Rim Light effect by drawing border
            ctx.strokeStyle = 'rgba(255,255,255,0.8)';
            ctx.lineWidth = 1;

            if (p.type === 'CHIP') {
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            } else {
                // Irregular triangle
                ctx.beginPath();
                ctx.moveTo(-p.size, -p.size/2); 
                ctx.lineTo(p.size, 0); 
                ctx.lineTo(0, p.size); 
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }

        } else if (p.type === 'GLOW') {
            // ✨ STATIC GLOW ORB (Pre-rendered)
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); // Pulse: Fade In -> Fade Out
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.9;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;
                const perspective = 1.0 + (p.z * 0.002);
                ctx.rotate(p.rotation);
                const scale = (p.size / 64) * perspective; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM (Optimized)
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Helix
        const freq = 0.12; 
        const amp = 8 * (1 - progress); 
        const phase = Date.now() * 0.025; 

        ctx.lineWidth = 2; 
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; 

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Flares
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; 
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);
            drawHex();
            ctx.clip();
            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();
        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();
            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 3.0
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;
        let alpha = lifeRatio > 0.8 ? (1 - lifeRatio) * 5 : (lifeRatio < 0.2 ? lifeRatio * 5 : 1.0);
        const maxHeight = 1200;
        const width = p.size; 

        ctx.save();
        ctx.globalCompositeOperation = 'screen'; 

        // Base
        ctx.save();
        ctx.scale(1, 0.58);
        ctx.rotate(Date.now() * 0.002);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = alpha * 0.4;
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = p.color; ctx.lineWidth = 3; ctx.globalAlpha = alpha * 0.8; ctx.stroke();
        ctx.restore();

        // Beam
        const coreWidth = width * 0.5;
        const beamGrad = ctx.createLinearGradient(-coreWidth, 0, coreWidth, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, '#ffffff'); 
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.9;
        ctx.fillRect(-coreWidth, -maxHeight, coreWidth * 2, maxHeight);

        // Data Streams
        const lines = 8;
        for(let i=0; i<lines; i++) {
            const offsetX = (Math.random() - 0.5) * width * 1.6;
            const speed = 2500 + Math.random() * 1500;
            const yPos = -((Date.now() * speed / 2000 + i * 137) % maxHeight);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha * (0.6 + Math.random()*0.4);
            ctx.fillRect(offsetX - 2, yPos, 4, 100); 
        }
        ctx.restore();
    },

    // 🩸 BLOOD RITUAL
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // Void Hole
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); 
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Cracks
         ctx.strokeStyle = p.color; 
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();
         ctx.restore();

         // Rising Heat
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); ctx.lineTo(-r/4, -300); ctx.lineTo(r/4, -300); ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";
import { VFXFactory } from "../../graphics/VFXFactory"; 

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

// --- 1. FACTION ULTIMATES ---

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100; 
    p.type = 'PILLAR'; 
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 120; 
    p.type = 'DOMAIN'; 
    p.delay = 0;
    system.state.particles.push(p);

    // Add rising debris
    for(let i=0; i<8; i++) {
        const d = system.state.getParticle();
        d.x = x + (Math.random()-0.5)*50; 
        d.y = y + (Math.random()-0.5)*30; 
        d.z = 0;
        d.vx = (Math.random()-0.5)*50;
        d.vy = (Math.random()-0.5)*50;
        d.vz = 100 + Math.random() * 200; 
        d.life = life * 0.8; d.maxLife = life * 0.8;
        d.color = '#000'; 
        d.size = 5 + Math.random() * 8;
        d.type = 'DEBRIS';
        d.rotation = Math.random();
        d.vRotation = Math.random();
        system.state.particles.push(d);
    }
}

// --- 2. IMPACTS & EXPLOSIONS ---

export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.2; p.maxLife = 1.2;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);

    if (Math.random() > 0.5) {
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = 10;
        s.vx = 0; s.vy = 0; s.vz = 150; 
        s.life = 0.4; s.maxLife = 0.4;
        s.color = color; s.size = 20;
        s.type = 'SPARK';
        s.delay = delay;
        system.state.particles.push(s);
    }
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 3;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y + (Math.random()-0.5)*15;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 10 + Math.random() * 20; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 25 + Math.random() * 25; // Larger puffs
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    // Blast
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 20;
    blast.vx = 0; blast.vy = 0; blast.vz = 0;
    blast.life = 0.2; blast.maxLife = 0.2;
    blast.color = '#00ffff'; 
    blast.size = 100;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    // High Velocity Shards (Energy, not stone)
    const shardCount = 12;
    for(let i=0; i<shardCount; i++) {
        const p = system.state.getParticle();
        const angle = (Math.PI * 2 * i) / shardCount;
        const speed = 400 + Math.random() * 400; 
        p.x = x; p.y = y; p.z = 30;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 300; 
        p.life = 0.5 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = Math.random() > 0.5 ? color : '#e2e8f0'; 
        p.size = 5 + Math.random() * 5;
        p.type = 'SHARD';
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 30; 
        system.state.particles.push(p);
    }

    // Chips
    const glitchCount = 8;
    for(let i=0; i<glitchCount; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*40;
        p.y = y + (Math.random()-0.5)*40;
        p.z = 40;
        p.vx = (Math.random()-0.5) * 50; 
        p.vy = (Math.random()-0.5) * 50;
        p.vz = 0;
        p.life = 0.3; p.maxLife = 0.3;
        p.color = Math.random() > 0.5 ? '#00ffff' : '#ff00ff';
        p.size = 4 + Math.random() * 4;
        p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = 10;
    const spread = 0.8; 

    // Directional Cone Sparks (High speed light streaks)
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 400 + Math.random() * 400; // Faster sparks
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; 

        p.life = 0.3 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 4 + Math.random() * 6; // Larger kinetic sparks
        p.type = 'SPARK'; 
        p.delay = 0;
        system.state.particles.push(p);
    }

    if (isPhysical) {
        spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
    } else {
        // Magical impact ring
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = color;
        p.size = 20; 
        p.type = 'RING';
        system.state.particles.push(p);
    }
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 
        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 
        p.vx = Math.cos(angle) * dist; p.vy = Math.sin(angle) * dist; p.vz = vZ;
        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff'; p.size = 64 * scale; 
        p.type = 'SPRITE'; p.image = img;
        p.rotation = Math.random() * Math.PI * 2; p.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(p);
    };

    const baseColor = '#52525b';
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 50 + Math.random() * 100; 
        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor; p.size = 10 + Math.random() * 10;
        p.type = 'SHARD'; p.rotation = angle; p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    spawnSprite(assets.icon, 0.6, 70, 300);   

    addDecal(system, x, y, '#000'); 
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        // Higher velocity spread for kinetic feel
        const spd = Math.random() * 200 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 200 + 100) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        // Size varies more
        p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 20 + 20;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { TerrainRenderer } from "./TerrainRenderer";

export const AOERenderer = {
    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visual: string,
        progress: number,
        globalTime: number,
        q: number, r: number,
        state: 'ACTIVE' | 'BROKEN' = 'ACTIVE',
        fadeRatio: number = 1.0
    ) {
        if (state === 'BROKEN') return;

        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        ctx.save();

        // Base Opacity charges up
        const opacity = 0.2 + progress * 0.4;
        ctx.globalAlpha = opacity;

        // --- A. SMASH / EARTH (Growing Fissures) ---
        if (visual === 'SMASH') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.setLineDash([10, 5]); 
            trace();
            ctx.stroke();

            // Fissures growing from center
            const seed = Math.abs(q * 73 + r * 19); 
            const crackCount = 3 + Math.floor(seed % 3);

            ctx.strokeStyle = color;
            ctx.lineWidth = 1 + progress * 2; 
            ctx.setLineDash([]);

            ctx.beginPath();
            for(let i=0; i<crackCount; i++) {
                const angle = (seed + i * (Math.PI * 2 / crackCount)) % (Math.PI * 2);
                // Length grows with progress
                const len = size * 0.8 * progress; 

                let cx = x; 
                let cy = y;
                ctx.moveTo(cx, cy);

                // Jagged line
                const segments = 3;
                for(let s=1; s<=segments; s++) {
                    const step = len / segments;
                    const zig = (s % 2 === 0 ? 1 : -1) * 5;
                    cx += Math.cos(angle) * step + Math.sin(angle) * zig;
                    cy += Math.sin(angle) * step * 0.55 + Math.cos(angle) * zig * 0.55; 
                    ctx.lineTo(cx, cy);
                }
            }
            ctx.stroke();

        // --- B. FIREBALL / BOMB (Expanding Core) ---
        } else if (visual === 'FIREBALL' || visual === 'BOMB') {
            const pulse = 1 + Math.sin(globalTime * 15) * 0.05;

            // Expanding fill
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.ellipse(x, y, size * progress * pulse, size * 0.55 * progress * pulse, 0, 0, Math.PI*2);
            ctx.fill();

            // Outer Ring
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.setLineDash([2, 4]);
            trace();
            ctx.stroke();

            // Core Heat (White center)
            if (progress > 0.5) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = (progress - 0.5) * 0.5;
                ctx.beginPath();
                ctx.ellipse(x, y, size * 0.3, size * 0.3 * 0.55, 0, 0, Math.PI*2);
                ctx.fill();
            }

        // --- C. ARROW (Reticle) ---
        } else if (visual === 'ARROW') {
            // Locking On animation
            const currentScale = 1.5 - (progress * 0.7);

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;

            const s = size * currentScale;
            const w = s * 0.3; // Corner length

            ctx.beginPath();
            // Corners
            ctx.moveTo(x - s, y - s * 0.55 + w * 0.55); ctx.lineTo(x - s, y - s * 0.55); ctx.lineTo(x - s + w, y - s * 0.55);
            ctx.moveTo(x + s - w, y - s * 0.55); ctx.lineTo(x + s, y - s * 0.55); ctx.lineTo(x + s, y - s * 0.55 + w * 0.55);
            ctx.moveTo(x + s, y + s * 0.55 - w * 0.55); ctx.lineTo(x + s, y + s * 0.55); ctx.lineTo(x + s - w, y + s * 0.55);
            ctx.moveTo(x - s + w, y + s * 0.55); ctx.lineTo(x - s, y + s * 0.55); ctx.lineTo(x - s, y + s * 0.55 - w * 0.55);
            ctx.stroke();

            if (progress > 0.8) {
                ctx.fillStyle = '#ff0000';
                ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
            }

            ctx.lineWidth = 1;
            ctx.setLineDash([2, 8]);
            ctx.globalAlpha = 0.3;
            trace();
            ctx.stroke();

        // --- D. DEFAULT (Rune Circle) ---
        } else {
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5 * progress;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, 0.55);
            ctx.rotate(globalTime * 2);
            ctx.setLineDash([15, 10]);
            ctx.beginPath(); ctx.arc(0, 0, size, 0, Math.PI*2); ctx.stroke();
            ctx.restore();

            if (progress > 0.2) {
                ctx.globalAlpha = progress * 0.5;
                ctx.fillStyle = color;
                ctx.beginPath();
                const pts = 3;
                const r = size * progress * 0.8;
                for(let i=0; i<pts; i++) {
                    const ang = globalTime + i * (Math.PI*2/pts);
                    const px = x + Math.cos(ang) * r;
                    const py = y + Math.sin(ang) * r * 0.55;
                    if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
                }
                ctx.closePath();
                ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                // Only spawn impact if it wasn't a projectile hit (which handles its own visuals)
                // or if it's a direct instant damage event.
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'PROJECTILE_HIT': 
                this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05); // Minimal impact
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                // New: High Impact Cast Break
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); // High trauma to feel the "SNAP"
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     // Very slight nudge on Ult finish
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // 1. FACTION RITUAL (The Ground Effect)
            if (faction === Team.BLUE) {
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 1.5, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 1.2);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            // 2. AOE RIPPLE (The Spread)
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                // Spawn sequential explosions
                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(centerHex, h);
                        const delay = dist * 0.08; 

                        VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, color, faction, delay);

                        if (skill.ccType === 'DOT' || skill.ccType === 'SILENCE') {
                            VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 4.0, delay);
                        }
                    }
                });
            } else {
                // Single Target Ult
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }
        } else {
            // --- NORMAL SKILLS (Specific Visuals) ---

            // 1. SMASH: Heavy Ground Impact
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Debris flies up
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
                if (skill?.type === 'AOE') {
                    VFXSpawners.addDecal(vfx, event.pos.x, centerVisualY, color);
                }
            } 
            // 2. SLASH: Directional Energy
            else if (visualType === 'SLASH') {
                // Direction calculated relative to source
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            // 3. FIREBALL / BOMB: Volumetric Explosion
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
                if (skill?.type === 'AOE') VFXSpawners.addDecal(vfx, event.pos.x, centerVisualY, '#000');
            }
            // 4. BOLT / ARROW / BEAM: High Precision
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }

            // Apply AOE secondary effects (Smoke/Decals)
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affected = HexUtils.range(centerHex, radius);

                affected.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(centerHex, h);

                        if (dist <= radius) {
                            if (Math.random() < 0.3) { 
                                VFXSpawners.spawnExplosion(vfx, tilePos.x, tileVisualY, 0, 3, color, 0.5, 0.5, 'SPARK');
                            }
                            if (skill.ccType === 'DOT') {
                                VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 3.0, dist * 0.05);
                            }
                        }
                    }
                });
            }
        }
    }
}

