import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex, MovementType, LogActionType, BattleField } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS, LOG_COLORS } from "../constants";

// Core Entities
import { Agent, SpecialVisualStatus } from "./core/Agent";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { EventBus } from "./events/EventBus";
import type { GameRenderer } from "./renderer";

export { Agent, SpecialVisualStatus };

// Constants
export const VICTORY_PHASE_DURATION = 0.5; // Reduced to 0.5s for snappier finish

export class GameEngine {
    public agents: Agent[] = [];
    public fields: BattleField[] = []; // NEW: Persistent Ground Effects

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;

    // Time & Speed Control
    public timeScale: number = 1.0;
    public targetTimeScale: number = 1.0; // New: For smooth slow-mo transitions

    public battleTime: number = 0;
    public mapVersion: number = 0; 

    // Finishing Sequence State
    public isFinishing: boolean = false;
    public victoryTimer: number = 0;
    public winningTeam: Team | null = null;

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.isFinishing = false;
            this.winningTeam = null;
            this.targetTimeScale = 1.0;
            this.timeScale = 1.0;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.isFinishing = false;
        this.winningTeam = null;
        this.targetTimeScale = 1.0;
        this.timeScale = 1.0;
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });
        this.combat.projectiles = []; 
        this.fields = []; // Reset fields
        this.events = []; 
        this.battleTime = 0;
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.combat.projectiles = [];
        this.fields = [];
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    tick(dt: number) {
        if (!this.isRunning) return;

        // 1. Time Dilation Logic (Smooth Slow Mo)
        if (Math.abs(this.targetTimeScale - this.timeScale) > 0.01) {
            this.timeScale += (this.targetTimeScale - this.timeScale) * 5.0 * dt; // Soft lerp
        } else {
            this.timeScale = this.targetTimeScale;
        }

        this.events.length = 0;
        this.updateDirector(dt);

        // 2. Victory Check Logic
        if (this.isFinishing) {
            this.victoryTimer -= dt;
            // Continue animating death falls and particles
            this.updateEntities(dt);

            if (this.victoryTimer <= 0) {
                this.stop();
                // Reset timescale for next run
                this.targetTimeScale = 1.0;
                this.timeScale = 1.0;
                this.bus.emit('GAME_OVER', { winner: this.winningTeam });
            }
            return;
        }

        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }

        if ((blue === 0 && red > 0) || (red === 0 && blue > 0)) { 
            // Enter Finishing Sequence
            this.isFinishing = true;
            this.winningTeam = blue === 0 ? Team.RED : Team.BLUE;
            this.victoryTimer = VICTORY_PHASE_DURATION; // Use Constant
            // Note: The slow motion trigger (0.1x) happens in SkillResolutionSystem on the lethal hit.
            // Here we ensure it doesn't stay frozen forever, drifting back up to 0.4x for the fall.
            this.targetTimeScale = 0.4; 
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;
            this.movement.updatePhysics(a, dt, this);
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.status.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        // If current target is dead, force reset
        if (this.directorTargetId) {
            const current = this.agents.find(a => a.id === this.directorTargetId);
            if (!current || current.hp <= 0) {
                this.directorTimer = -1;
            }
        }

        if (this.directorTimer <= 0) {
            let candidates: Agent[] = [];
            let ultCasters: Agent[] = [];

            // Single loop to find candidates (Avoids array allocation of .filter)
            for (const a of this.agents) {
                if (a.hp > 0) {
                    candidates.push(a);
                    if (a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT') {
                        ultCasters.push(a);
                    }
                }
            }

            if (candidates.length > 0) {
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0; // Stay longer on Ult
                } else {
                     this.directorTargetId = candidates[Math.floor(Math.random() * candidates.length)].id;
                     this.directorTimer = 3.0;
                }
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 
            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, 'CAST', '詠唱', targetName, `開始引導 ${a.skills[i]!.name} (需 ${a.skills[i]!.cast} 秒)`);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    log(agent: Agent | null, typeOrAction: LogActionType | string, actionNameOrTarget: string | null, detailOrTargetInfo: string, legacyDetail?: string) {
        const time = this.battleTime.toFixed(1);
        let actionType: LogActionType = 'SYSTEM';
        let actionName = 'Action';
        let targetInfo = '';
        let detail = '';
        let color = LOG_COLORS.SYSTEM;

        const isLegacy = !this.isLogActionType(typeOrAction);

        if (isLegacy) {
            const rawAction = typeOrAction as string;
            actionName = rawAction;
            targetInfo = actionNameOrTarget || '';
            detail = detailOrTargetInfo;
            if (rawAction === '死亡') { actionType = 'DEATH'; color = LOG_COLORS.DEATH; }
            else if (rawAction === '放逐結束') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '中斷') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '命中') { actionType = 'HIT'; color = LOG_COLORS.HIT; }
            else { actionType = 'SYSTEM'; }
        } else {
            actionType = typeOrAction as LogActionType;
            actionName = actionNameOrTarget || '';
            targetInfo = detailOrTargetInfo || '';
            detail = legacyDetail || '';
            switch(actionType) {
                case 'MOVE': color = LOG_COLORS.MOVE; break;
                case 'CAST': color = LOG_COLORS.CAST; break;
                case 'HIT': color = LOG_COLORS.HIT; break;
                case 'HEAL': color = LOG_COLORS.HEAL; break;
                case 'DECISION': color = LOG_COLORS.DECISION; break;
                case 'DEATH': color = LOG_COLORS.DEATH; break;
                case 'CC': color = LOG_COLORS.CC; break;
                default: color = LOG_COLORS.SYSTEM; break;
            }
        }

        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            turn: Math.floor(this.battleTime * 10),
            agentId: agent?.id || 'SYSTEM',
            team: agent?.team,
            location: agent ? `(${agent.q},${agent.r})` : 'global',
            actionType: actionType,
            actionName: actionName,
            targetInfo: targetInfo,
            detail: detail,
            visualColor: color,
            action: actionName,
            target: targetInfo,
            loc: agent ? `@(${agent.q},${agent.r})` : ''
        };

        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }

    private isLogActionType(val: any): val is LogActionType {
        return ['MOVE','CAST','HIT','DECISION','DEATH','SYSTEM','HEAL','CC'].includes(val);
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, BattleField } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { SkillResolutionSystem } from "./combat/SkillResolutionSystem";
import { HexUtils } from "../utils";
import { HEX_SIZE } from "../../constants";
import * as VFXSpawners from "./vfx/spawners";

const FIELD_TICK_RATE = 0.5; // Damage every 0.5s

export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public skillResolution: SkillResolutionSystem;

    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.skillResolution = new SkillResolutionSystem();
    }

    // Proxy for accessors to maintain GameEngine compatibility
    get projectiles(): Projectile[] { return this.projectileSystem.projectiles; }
    set projectiles(v: Projectile[]) { this.projectileSystem.projectiles = v; }

    public update(dt: number, engine: GameEngine) {
        // 1. Casting Updates (Logic)
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.skillResolution.updateCasting(a, dt, engine);
            }
        });

        // 2. Projectile Physics & Impacts
        this.projectileSystem.update(dt, engine, this.skillResolution);

        // 3. Update Persistent Ground Fields (Poison clouds, etc.)
        this.updateFields(dt, engine);
    }

    private updateFields(dt: number, engine: GameEngine) {
        // Reverse iterate to remove expired fields safely
        for (let i = engine.fields.length - 1; i >= 0; i--) {
            const field = engine.fields[i];

            field.duration -= dt;
            field.tickTimer -= dt;

            // Handle Logic Tick
            if (field.tickTimer <= 0) {
                field.tickTimer = FIELD_TICK_RATE;
                this.resolveFieldTick(field, engine);
            }

            // Expiry
            if (field.duration <= 0) {
                engine.fields.splice(i, 1);
            }
        }
    }

    private resolveFieldTick(field: BattleField, engine: GameEngine) {
        const source = engine.agents.find(a => a.id === field.sourceId);
        // Even if source is dead, field might persist, but we need a source for damage attribution.
        // If source missing, we can create a dummy or just skip damage attribution log?
        // Let's create a dummy logic proxy if needed, but usually we just skip attribution text.

        // Find agents in radius
        // Optimization: Use squared distance
        const rPx = field.radiusPx * field.radiusPx;

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished || agent.team === field.team) return; // Friendly fire OFF

            const dx = agent.px - field.pos.x;
            const dy = agent.py - field.pos.y;
            const distSq = dx * dx + dy * dy;

            if (distSq <= rPx) {
                // Determine damage. 
                // Logic: Fields usually do dotDamage (ccForce) or a fraction of power.
                // We use ccForce if available, otherwise 20% of power.
                const damage = field.skill.ccForce || (field.skill.power * 0.2) || 10;

                // Direct HP modification to avoid triggering full "Hit" animation every 0.5s which looks jerky
                agent.hp = Math.max(0, agent.hp - damage);

                // Add tiny floating text without spamming the log
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damage), 
                    color: field.color 
                });

                // Apply Status Effect if applicable (Refresh DoT timer)
                if (field.skill.ccType && field.skill.ccType !== 'NONE') {
                    // Re-apply status with 1s duration just to keep it active while in field
                    this.skillResolution.applyCC(
                        source || agent, agent, field.skill, 
                        field.skill.ccType, 1.0, 0, undefined, engine
                    );
                }
            }
        });
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }

    public spawnField(source: Agent, skill: Skill, pos: {x: number, y: number}, engine: GameEngine) {
        // Convert radius to pixels
        const radiusGrid = skill.aoeRadius || 1;
        const radiusPx = radiusGrid * HEX_SIZE * 1.5; // Approximation for coverage

        // Determine Duration: Use ccDur if > 0, else default 5s
        const duration = (skill.ccDur && skill.ccDur > 0) ? skill.ccDur : 5.0;

        const field: BattleField = {
            id: Math.random().toString(36).substr(2, 5),
            pos: pos,
            q: 0, r: 0, // Not strictly needed for collision if we use PX, but good for debug
            radius: radiusGrid,
            radiusPx: radiusPx,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            duration: duration,
            tickTimer: 0, // Tick immediately on spawn
            visualType: skill.visual || 'SMOKE',
            color: skill.color
        };

        engine.fields.push(field);

        // Spawn Visuals immediately
        // Note: The VFXSpawner `spawnLingeringField` spawns particles with life = duration.
        // This matches perfectly.
        VFXSpawners.spawnLingeringField(engine.renderer!.vfx, pos.x, pos.y, skill.color, 'SMOKE', duration, 0);
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillResolutionSystem } from "./SkillResolutionSystem";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public update(dt: number, engine: GameEngine, skillResolver: SkillResolutionSystem) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            // Homing logic: update target position if unit moves
            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = p.speed * dt;

            // TRAIL UPDATE
            // Only add trail point if moved enough to prevent stacking
            // Limit trail buffer size for performance
            const lastTrail = p.trail.length > 0 ? p.trail[p.trail.length - 1] : null;
            if (!lastTrail || Vector.dist(lastTrail, {x: p.x, y: p.y}) > 10) {
                p.trail.push({x: p.x, y: p.y});
                if (p.trail.length > 12) p.trail.shift(); // Keep trail shorter but smoother
            }

            // Hit Detection
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId) || engine.agents[0]; 

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const radius = p.skill.aoeRadius || 1;
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);

                    targets.forEach(t => { 
                        if (source) skillResolver.resolveHit(source, t, p.skill, hitPos, engine); 
                    });

                    // NEW: Persistent Field Logic
                    // If AOE has DOT or specific lingering tag, spawn a Field
                    if (p.skill.ccType === 'DOT' || p.skill.name.includes("霧") || p.skill.name.includes("雨") || p.skill.name.includes("暴風")) {
                        if (source) engine.combat.spawnField(source, p.skill, hitPos, engine);
                    }

                    // IMPACT EVENT
                    engine.events.push({ type: 'IMPACT_AOE', pos: {x: hitPos.x, y: hitPos.y}, skill: p.skill, color: p.skill.color });
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: hitPos.x, y: hitPos.y}, skill: p.skill });

                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) skillResolver.resolveHit(source, target, p.skill, undefined, engine);
                    }
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: p.x, y: p.y}, skill: p.skill });
                }

                const lastIdx = this.projectiles.length - 1;
                if (i !== lastIdx) {
                    this.projectiles[i] = this.projectiles[lastIdx];
                }
                this.projectiles.pop();

            } else {
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        // Fallback Visual: Ensure no invisible projectiles
        if (!skill.visual) {
            skill.visual = 'BOLT'; 
        }

        let tx = 0, ty = 0;
        let tid = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 tx = p.x; ty = p.y;
                 tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 tx = source.target.px; ty = source.target.py;
                 tid = source.target.id;
             } else {
                 return; // No target
             }
             targetPos = {x: tx, y: ty};
             this.createProjectile(source, skill, targetPos, tid, engine);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });

        } else {
            // Single Target Projectile
            const targets = (source.target && !source.target.banished && source.target.hp > 0 ? [source.target] : []);
            targets.forEach(t => {
                 targetPos = {x: t.px, y: t.py};
                 this.createProjectile(source, skill, targetPos, t.id, engine);
                 engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: t.id });
            });
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string, engine: GameEngine) {
        this.projectiles.push({
            id: Math.random().toString(),
            x: source.px, 
            y: source.py, 
            startX: source.px, 
            startY: source.py,
            targetId: targetId,
            targetPos: targetPos,
            speed: skill.projectileSpeed || 600, // Safe default
            skill: skill,
            sourceId: source.id,
            team: source.team,
            trail: []
        });
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                // Only spawn impact if it wasn't a projectile hit (which handles its own visuals)
                // or if it's a direct instant damage event.
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                // NEW: Explicit large blast for AOE impacts
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); // Screen shake for AOE
                break;

            case 'PROJECTILE_HIT': 
                // Only handle special visuals if not handled by IMPACT_AOE
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05); // Minimal impact
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                // High Impact Cast Break
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     // Very slight nudge on Ult finish
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // 1. FACTION RITUAL (The Ground Effect)
            if (faction === Team.BLUE) {
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 1.5, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 1.2);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            // Single Target Ult
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');

        } else {
            // --- NORMAL SKILLS (Specific Visuals) ---

            // 1. SMASH: Heavy Ground Impact
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Debris flies up
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            // 2. SLASH: Directional Energy
            else if (visualType === 'SLASH') {
                // Direction calculated relative to source
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            // 3. FIREBALL / BOMB: Volumetric Explosion
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            // 4. BOLT / ARROW / BEAM: High Precision
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { BLOCK_HEIGHT, COMBAT_PARAM } from "../../../constants";

export class SkillResolutionSystem {

    // =================================================================================
    // 🧠 LOGIC LAYER: ORCHESTRATION
    // =================================================================================

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks (Stun / Silence / Banish / Death)
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0 || a.hp <= 0) {
            this.handleInterruption(a, engine);
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            this.completeCast(a, engine);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;

        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            const skillName = s.name;
            engine.log(a, 'CC', '中斷', skillName, '詠唱被打斷');

            // Determine Visual Center for Break Effect
            let centerPos = { x: a.px, y: a.py };
            if (s.type === 'AOE') {
                const centerHex = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : {q: a.q, r: a.r});
                centerPos = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(centerHex.q, centerHex.r);
                centerPos.y -= h;
            } else {
                centerPos.y -= engine.map.getTerrainHeight(a.q, a.r);
            }

            engine.events.push({
                type: 'CAST_BREAK',
                pos: centerPos,
                value: s.aoeRadius || 1, 
                color: s.color,
                skill: s
            });
        }

        // Reset State
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.IDLE); 
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;

        // Resource & CD
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd;

        // Branch: Projectile vs Instant
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             engine.combat.spawnProjectile(a, s, engine);
        } else {
            this.executeInstantSkill(a, s, engine);
        }

        // Reset State
        a.castingSkillIdx = -1;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; // Default to caster

        // Target Acquisition (Logic)
        if (skill.type === 'AOE') {
            const centerHex = source.targetHex || (source.target ? { q: source.target.q, r: source.target.r } : { q: source.q, r: source.r });
            targets = engine.agents.filter(e => 
                e.team !== source.team && e.hp > 0 && !e.banished && HexUtils.dist(centerHex!, e) <= radius
            );

            // For AOE, the impulse origin should be the CENTER of the blast, not the caster
            const p = HexUtils.toPx(centerHex!.q, centerHex!.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };

            // NEW: Spawn Persistent Field if CC Type is DOT (e.g. Poison Cloud, Blizzard)
            if (skill.ccType === 'DOT' || skill.name.includes("霧") || skill.name.includes("雨")) {
                engine.combat.spawnField(source, skill, origin, engine);
            }

            // AOE Impact Event
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effectiveRange) targets = [source.target];
            }
        }

        // Apply Hits
        targets.forEach(t => {
            // Visuals
            const dist = HexUtils.dist(source, t);
            if (dist > 2) engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            else if (dist === 2) engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });

            this.resolveHit(source, t, skill, origin, engine);
        });

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        // 1. Math: Calculate final damage and effects
        const calc = this.calculateDamageValues(source, target, skill);
        const oldHp = Math.ceil(target.hp);

        // --- MATRIX SLOW MOTION CHECK ---
        if (calc.finalDamage >= target.hp && !engine.isFinishing) {
            // Check if this is the LAST unit of the team
            const alliesAlive = engine.agents.filter(a => a.team === target.team && a.hp > 0 && a.id !== target.id).length;

            if (alliesAlive === 0) {
                // THE FINAL BLOW!
                engine.timeScale = 0.1; // Snap to instant slow-mo
                engine.targetTimeScale = 0.1; // Hold it
                // We don't set isFinishing here, Engine.tick will detect the death next frame and handle the victory sequence.
                // This just ensures the hit itself is felt.
            }
        }

        // 2. State Mutation: Apply Damage/Heal
        target.hp = Math.min(target.maxHp, target.hp - calc.finalDamage);

        // 3. State Mutation: Vamp
        if (calc.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + calc.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: calc.vampAmount, color: '#86efac' });
        }

        // 4. State Mutation: Mana Burn
        if (calc.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - calc.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + calc.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${calc.manaBurn} MP`, color: "#3b82f6" });
        }

        // 5. State Mutation: Mana Restore
        if (calc.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + calc.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${calc.manaRestore} MP`, color: "#60a5fa" });
        }

        // 6. Visuals & Physics
        if (calc.finalDamage > 0) {
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            // Force origin to be what was passed (explosion center), fall back to source if undefined (e.g. projectile)
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const impulse = this.calculateImpulseVector(originPx, {x: target.px, y: target.py}, calc.finalDamage);
            target.physics.vx += impulse.x;
            target.physics.vy += impulse.y;
            target.physics.vAngle += (Math.random() - 0.5) * 0.5;
        }

        // 7. Events & Logging
        if (calc.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });

        engine.events.push({
            type: calc.finalDamage > 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: -calc.finalDamage,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // Apply CC
        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        engine.log(source, calc.finalDamage > 0 ? 'HIT' : 'HEAL', skill.name, target.id, `${calc.finalDamage > 0 ? '造成傷害' : '回復生命'} ${Math.abs(calc.finalDamage)} (HP: ${oldHp} -> ${newHp})`);

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type || type === 'NONE') return;

        // 1. Math: Diminishing Returns Calculation
        const { effectiveDuration, isImmune, isReduced } = this.calculateControlDuration(target, type, dur || 0);

        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫!", color: "#9ca3af" });
            return;
        }
        if (isReduced) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py - 20}, text: "抵抗", color: "#9ca3af" });
        }

        // Apply DR Stack (State Mutation)
        if (['STUN', 'SILENCE', 'BANISH'].includes(type)) {
            target.drStacks[type] = (target.drStacks[type] || 0) + 1;
            target.drTimers[type] = COMBAT_PARAM.DR_RESET_TIME;
        }

        // 2. Logic: Apply Effect
        let statusText = "";
        let statusColor = "#fff";

        if (type === 'STUN') {
            if (effectiveDuration > target.stunTimer) {
                target.stunTimer = effectiveDuration;
                target.stunMax = effectiveDuration;
            }
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            statusText = "暈眩";
            statusColor = "#facc15"; 
            if (this.isIceSkill(skill)) target.visualStatus = 'FROZEN';

        } else if (type === 'SILENCE') {
            if (effectiveDuration > target.silenceTimer) {
                target.silenceTimer = effectiveDuration;
                target.silenceMax = effectiveDuration;
            }
            statusText = "沉默";
            statusColor = "#94a3b8"; 

        } else if (type === 'BANISH') {
            if (effectiveDuration > target.banishTimer) {
                target.banishTimer = effectiveDuration;
                target.banishMax = effectiveDuration;
            }
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            statusText = "放逐";
            statusColor = "#c084fc"; 

            // Visual Sub-types
            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; statusText = "變形";
            } else if (skill.name.includes("無敵") || skill.name.includes("金身") || skill.name.includes("干涉")) {
                target.visualStatus = 'STASIS'; statusText = "凝滯";
            } else {
                target.visualStatus = 'NONE';
            }

        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
            if (result.applied) {
                statusText = type === 'PULL' ? "牽引" : "擊退";
                statusColor = "#fff";
                target.setAnim(AnimState.HIT);
                target.physics.vz += 200;
            } else {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
            }

        } else if (type === 'DOT') {
            target.dotDmg = force || 5;
            target.dotTimer = effectiveDuration || 3;
            statusText = "中毒";
            statusColor = "#10b981";

        } else if (type === 'HOT') {
            target.hotVal = force || 5;
            target.hotTimer = effectiveDuration || 3;
            statusText = "再生";
            statusColor = "#86efac";
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
        }
    }

    // =================================================================================
    // 🧮 MATH LAYER: PURE CALCULATIONS
    // =================================================================================

    private calculateDamageValues(source: Agent, target: Agent, skill: Skill) {
        let rawDmg = skill.power;
        let isExecute = false;

        // Execute Logic
        const isExec1 = skill.effectType === 'EXECUTE';
        const isExec2 = skill.effectType2 === 'EXECUTE';
        if ((isExec1 || isExec2) && target.hp < target.maxHp * COMBAT_PARAM.EXECUTE_THRESHOLD) {
            const multiplier = (isExec1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_EXECUTE_MULTIPLIER;
            rawDmg = Math.floor(rawDmg * multiplier);
            isExecute = true;
        }

        // Vamp Logic
        let vampAmount = 0;
        const isVamp1 = skill.effectType === 'VAMP';
        const isVamp2 = skill.effectType2 === 'VAMP';
        if (rawDmg > 0 && (isVamp1 || isVamp2)) {
            const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_VAMP_PCT;
            vampAmount = Math.floor(rawDmg * vampPct);
        }

        // Mana Calculations
        let manaBurn = 0;
        let manaRestore = 0;
        const e1 = skill.effectType; const e2 = skill.effectType2;
        const v1 = skill.effectVal; const v2 = skill.effectVal2;

        if (e1 === 'MANA_BURN') manaBurn += (v1 || COMBAT_PARAM.MANA_BURN_DEFAULT);
        if (e2 === 'MANA_BURN') manaBurn += (v2 || COMBAT_PARAM.MANA_BURN_DEFAULT);

        if (e1 === 'MANA_RESTORE') manaRestore += (v1 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        if (e2 === 'MANA_RESTORE') manaRestore += (v2 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);

        return { finalDamage: rawDmg, isExecute, vampAmount, manaBurn, manaRestore };
    }

    private calculateControlDuration(target: Agent, type: string, baseDuration: number) {
        // Diminishing Returns (DR)
        const isHardCC = ['STUN', 'SILENCE', 'BANISH'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false, isReduced: false };

        const currentStack = target.drStacks[type] || 0;
        // Formula: 1 / (2 ^ stack)
        let drMultiplier = Math.pow(0.5, currentStack);
        if (drMultiplier < 0.2) drMultiplier = 0;

        return {
            effectiveDuration: baseDuration * drMultiplier,
            isImmune: drMultiplier === 0,
            isReduced: drMultiplier < 1.0 && drMultiplier > 0
        };
    }

    private calculateImpulseVector(origin: {x: number, y: number}, target: {x: number, y: number}, damage: number) {
        const dx = target.x - origin.x;
        const dy = target.y - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);

        // If center hit, random scatter
        if (len <= 0) {
            const ang = Math.random() * Math.PI * 2;
            return {
                x: Math.cos(ang) * COMBAT_PARAM.HIT_IMPULSE_MIN,
                y: Math.sin(ang) * COMBAT_PARAM.HIT_IMPULSE_MIN
            };
        }

        // Dynamic Force Calculation
        // Use a much stronger multiplier to be visible against physics stiffness
        const force = Math.min(COMBAT_PARAM.HIT_IMPULSE_MAX, Math.max(COMBAT_PARAM.HIT_IMPULSE_MIN, damage * 1.5));

        return {
            x: (dx / len) * force,
            y: (dy / len) * force
        };
    }

    private calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 
        const tilesToPush = Math.max(0, rawForce - resistance);

        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

        let currentH = {q: target.q, r: target.r};
        let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
        let finalH = currentH;

        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN = null;
            let bestDot = -99;

            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                const dot = nDir.x * vector.x + nDir.y * vector.y;

                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }

            if (bestN) {
                if (!engine.isValid(bestN.q, bestN.r)) break; 
                if (engine.hasObstacle(bestN.q, bestN.r)) break; 

                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > currentHeight + BLOCK_HEIGHT) break; // Can't push up too high
                if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) break; // Can't push off huge cliff safely

                currentH = bestN;
                currentHeight = nextHeight;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            return { applied: true };
        }
        return { applied: false };
    }

    private isIceSkill(skill: Skill): boolean {
        const c = skill.color.toLowerCase();
        const n = skill.name;
        return c.includes('blue') || c.includes('#60a5fa') || c.includes('#e0f2fe') || 
               n.includes("冰") || n.includes("凍") || n.includes("雪");
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, BattleField } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { SkillResolutionSystem } from "./combat/SkillResolutionSystem";
import { HexUtils } from "../utils";
import { HEX_SIZE } from "../../constants";
import * as VFXSpawners from "./vfx/spawners";

const FIELD_TICK_RATE = 0.5; // Damage every 0.5s

export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public skillResolution: SkillResolutionSystem;

    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.skillResolution = new SkillResolutionSystem();
    }

    // Proxy for accessors to maintain GameEngine compatibility
    get projectiles(): Projectile[] { return this.projectileSystem.projectiles; }
    set projectiles(v: Projectile[]) { this.projectileSystem.projectiles = v; }

    public update(dt: number, engine: GameEngine) {
        // 1. Casting Updates (Logic)
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.skillResolution.updateCasting(a, dt, engine);
            }
        });

        // 2. Projectile Physics & Impacts
        this.projectileSystem.update(dt, engine, this.skillResolution);

        // 3. Update Persistent Ground Fields (Poison clouds, etc.)
        this.updateFields(dt, engine);
    }

    private updateFields(dt: number, engine: GameEngine) {
        // Reverse iterate to remove expired fields safely
        for (let i = engine.fields.length - 1; i >= 0; i--) {
            const field = engine.fields[i];

            field.duration -= dt;
            field.tickTimer -= dt;

            // Handle Logic Tick
            if (field.tickTimer <= 0) {
                field.tickTimer = FIELD_TICK_RATE;
                this.resolveFieldTick(field, engine);
            }

            // Expiry
            if (field.duration <= 0) {
                engine.fields.splice(i, 1);
            }
        }
    }

    private resolveFieldTick(field: BattleField, engine: GameEngine) {
        const source = engine.agents.find(a => a.id === field.sourceId);
        // Even if source is dead, field might persist, but we need a source for damage attribution.
        // If source missing, we can create a dummy or just skip damage attribution log?
        // Let's create a dummy logic proxy if needed, but usually we just skip attribution text.

        // Find agents in radius
        // Optimization: Use squared distance
        const rPx = field.radiusPx * field.radiusPx;

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished || agent.team === field.team) return; // Friendly fire OFF

            const dx = agent.px - field.pos.x;
            const dy = agent.py - field.pos.y;
            const distSq = dx * dx + dy * dy;

            if (distSq <= rPx) {
                // Determine damage. 
                // Logic: Fields usually do dotDamage (ccForce) or a fraction of power.
                // We use ccForce if available, otherwise 20% of power.
                const damage = field.skill.ccForce || (field.skill.power * 0.2) || 10;

                // Direct HP modification to avoid triggering full "Hit" animation every 0.5s which looks jerky
                agent.hp = Math.max(0, agent.hp - damage);

                // Add tiny floating text without spamming the log
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damage), 
                    color: field.color 
                });

                // Apply Status Effect if applicable (Refresh DoT timer)
                if (field.skill.ccType) {
                    // Re-apply status with 1s duration just to keep it active while in field
                    this.skillResolution.applyCC(
                        source || agent, agent, field.skill, 
                        field.skill.ccType, 1.0, 0, undefined, engine
                    );
                }
            }
        });
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }

    public spawnField(source: Agent, skill: Skill, pos: {x: number, y: number}, engine: GameEngine) {
        // Convert radius to pixels
        const radiusGrid = skill.aoeRadius || 1;
        const radiusPx = radiusGrid * HEX_SIZE * 1.5; // Approximation for coverage

        // Determine Duration: Use ccDur if > 0, else default 5s
        const duration = (skill.ccDur && skill.ccDur > 0) ? skill.ccDur : 5.0;

        const field: BattleField = {
            id: Math.random().toString(36).substr(2, 5),
            pos: pos,
            q: 0, r: 0, // Not strictly needed for collision if we use PX, but good for debug
            radius: radiusGrid,
            radiusPx: radiusPx,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            duration: duration,
            tickTimer: 0, // Tick immediately on spawn
            visualType: skill.visual || 'SMOKE',
            color: skill.color
        };

        engine.fields.push(field);

        // Spawn Visuals immediately
        // Note: The VFXSpawner `spawnLingeringField` spawns particles with life = duration.
        // This matches perfectly.
        VFXSpawners.spawnLingeringField(engine.renderer!.vfx, pos.x, pos.y, skill.color, 'SMOKE', duration, 0);
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { BLOCK_HEIGHT, COMBAT_PARAM } from "../../../constants";

export class SkillResolutionSystem {

    // =================================================================================
    // 🧠 LOGIC LAYER: ORCHESTRATION
    // =================================================================================

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks (Stun / Silence / Banish / Death)
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0 || a.hp <= 0) {
            this.handleInterruption(a, engine);
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            this.completeCast(a, engine);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;

        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            const skillName = s.name;
            engine.log(a, 'CC', '中斷', skillName, '詠唱被打斷');

            // Determine Visual Center for Break Effect
            let centerPos = { x: a.px, y: a.py };
            if (s.type === 'AOE') {
                const centerHex = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : {q: a.q, r: a.r});
                centerPos = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(centerHex.q, centerHex.r);
                centerPos.y -= h;
            } else {
                centerPos.y -= engine.map.getTerrainHeight(a.q, a.r);
            }

            engine.events.push({
                type: 'CAST_BREAK',
                pos: centerPos,
                value: s.aoeRadius || 1, 
                color: s.color,
                skill: s
            });
        }

        // Reset State
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.IDLE); 
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;

        // Resource & CD
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd;

        // Branch: Projectile vs Instant
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             engine.combat.spawnProjectile(a, s, engine);
        } else {
            this.executeInstantSkill(a, s, engine);
        }

        // Reset State
        a.castingSkillIdx = -1;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; // Default to caster

        // Target Acquisition (Logic)
        if (skill.type === 'AOE') {
            const centerHex = source.targetHex || (source.target ? { q: source.target.q, r: source.target.r } : { q: source.q, r: source.r });
            targets = engine.agents.filter(e => 
                e.team !== source.team && e.hp > 0 && !e.banished && HexUtils.dist(centerHex!, e) <= radius
            );

            // For AOE, the impulse origin should be the CENTER of the blast, not the caster
            const p = HexUtils.toPx(centerHex!.q, centerHex!.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };

            // NEW: Spawn Persistent Field if CC Type is DOT (e.g. Poison Cloud, Blizzard)
            if (skill.ccType === 'DOT' || skill.name.includes("霧") || skill.name.includes("雨")) {
                engine.combat.spawnField(source, skill, origin, engine);
            }

            // AOE Impact Event
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effectiveRange) targets = [source.target];
            }
        }

        // Apply Hits
        targets.forEach(t => {
            // Visuals
            const dist = HexUtils.dist(source, t);
            if (dist > 2) engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            else if (dist === 2) engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });

            this.resolveHit(source, t, skill, origin, engine);
        });

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        // 1. Math: Calculate final damage and effects
        const calc = this.calculateDamageValues(source, target, skill);
        const oldHp = Math.ceil(target.hp);

        // --- MATRIX SLOW MOTION CHECK ---
        if (calc.finalDamage >= target.hp && !engine.isFinishing) {
            // Check if this is the LAST unit of the team
            const alliesAlive = engine.agents.filter(a => a.team === target.team && a.hp > 0 && a.id !== target.id).length;

            if (alliesAlive === 0) {
                // THE FINAL BLOW!
                engine.timeScale = 0.1; // Snap to instant slow-mo
                engine.targetTimeScale = 0.1; // Hold it
                // We don't set isFinishing here, Engine.tick will detect the death next frame and handle the victory sequence.
                // This just ensures the hit itself is felt.
            }
        }

        // 2. State Mutation: Apply Damage/Heal
        target.hp = Math.min(target.maxHp, target.hp - calc.finalDamage);

        // 3. State Mutation: Vamp
        if (calc.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + calc.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: calc.vampAmount, color: '#86efac' });
        }

        // 4. State Mutation: Mana Burn
        if (calc.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - calc.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + calc.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${calc.manaBurn} MP`, color: "#3b82f6" });
        }

        // 5. State Mutation: Mana Restore
        if (calc.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + calc.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${calc.manaRestore} MP`, color: "#60a5fa" });
        }

        // 6. Visuals & Physics
        if (calc.finalDamage > 0) {
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            // Force origin to be what was passed (explosion center), fall back to source if undefined (e.g. projectile)
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const impulse = this.calculateImpulseVector(originPx, {x: target.px, y: target.py}, calc.finalDamage);
            target.physics.vx += impulse.x;
            target.physics.vy += impulse.y;
            target.physics.vAngle += (Math.random() - 0.5) * 0.5;
        }

        // 7. Events & Logging
        if (calc.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });

        engine.events.push({
            type: calc.finalDamage > 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: -calc.finalDamage,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // Apply CC
        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        engine.log(source, calc.finalDamage > 0 ? 'HIT' : 'HEAL', skill.name, target.id, `${calc.finalDamage > 0 ? '造成傷害' : '回復生命'} ${Math.abs(calc.finalDamage)} (HP: ${oldHp} -> ${newHp})`);

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type || type === 'NONE') return;

        // 1. Math: Diminishing Returns Calculation
        const { effectiveDuration, isImmune, isReduced } = this.calculateControlDuration(target, type, dur || 0);

        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫!", color: "#9ca3af" });
            return;
        }
        if (isReduced) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py - 20}, text: "抵抗", color: "#9ca3af" });
        }

        // Apply DR Stack (State Mutation)
        if (['STUN', 'SILENCE', 'BANISH'].includes(type)) {
            target.drStacks[type] = (target.drStacks[type] || 0) + 1;
            target.drTimers[type] = COMBAT_PARAM.DR_RESET_TIME;
        }

        // 2. Logic: Apply Effect
        let statusText = "";
        let statusColor = "#fff";

        if (type === 'STUN') {
            if (effectiveDuration > target.stunTimer) {
                target.stunTimer = effectiveDuration;
                target.stunMax = effectiveDuration;
            }
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            statusText = "暈眩";
            statusColor = "#facc15"; 
            if (this.isIceSkill(skill)) target.visualStatus = 'FROZEN';

        } else if (type === 'SILENCE') {
            if (effectiveDuration > target.silenceTimer) {
                target.silenceTimer = effectiveDuration;
                target.silenceMax = effectiveDuration;
            }
            statusText = "沉默";
            statusColor = "#94a3b8"; 

        } else if (type === 'BANISH') {
            if (effectiveDuration > target.banishTimer) {
                target.banishTimer = effectiveDuration;
                target.banishMax = effectiveDuration;
            }
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            statusText = "放逐";
            statusColor = "#c084fc"; 

            // Visual Sub-types
            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; statusText = "變形";
            } else if (skill.name.includes("無敵") || skill.name.includes("金身") || skill.name.includes("干涉")) {
                target.visualStatus = 'STASIS'; statusText = "凝滯";
            } else {
                target.visualStatus = 'NONE';
            }

        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
            if (result.applied) {
                statusText = type === 'PULL' ? "牽引" : "擊退";
                statusColor = "#fff";
                target.setAnim(AnimState.HIT);
                // Visual pop-up when knocked
                target.physics.vz += 200;
            } else {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
            }

        } else if (type === 'DOT') {
            target.dotDmg = force || 5;
            target.dotTimer = effectiveDuration || 3;
            statusText = "中毒";
            statusColor = "#10b981";

        } else if (type === 'HOT') {
            target.hotVal = force || 5;
            target.hotTimer = effectiveDuration || 3;
            statusText = "再生";
            statusColor = "#86efac";
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
        }
    }

    // =================================================================================
    // 🧮 MATH LAYER: PURE CALCULATIONS
    // =================================================================================

    private calculateDamageValues(source: Agent, target: Agent, skill: Skill) {
        let rawDmg = skill.power;
        let isExecute = false;

        // Execute Logic
        const isExec1 = skill.effectType === 'EXECUTE';
        const isExec2 = skill.effectType2 === 'EXECUTE';
        if ((isExec1 || isExec2) && target.hp < target.maxHp * COMBAT_PARAM.EXECUTE_THRESHOLD) {
            const multiplier = (isExec1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_EXECUTE_MULTIPLIER;
            rawDmg = Math.floor(rawDmg * multiplier);
            isExecute = true;
        }

        // Vamp Logic
        let vampAmount = 0;
        const isVamp1 = skill.effectType === 'VAMP';
        const isVamp2 = skill.effectType2 === 'VAMP';
        if (rawDmg > 0 && (isVamp1 || isVamp2)) {
            const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_VAMP_PCT;
            vampAmount = Math.floor(rawDmg * vampPct);
        }

        // Mana Calculations
        let manaBurn = 0;
        let manaRestore = 0;
        const e1 = skill.effectType; const e2 = skill.effectType2;
        const v1 = skill.effectVal; const v2 = skill.effectVal2;

        if (e1 === 'MANA_BURN') manaBurn += (v1 || COMBAT_PARAM.MANA_BURN_DEFAULT);
        if (e2 === 'MANA_BURN') manaBurn += (v2 || COMBAT_PARAM.MANA_BURN_DEFAULT);

        if (e1 === 'MANA_RESTORE') manaRestore += (v1 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        if (e2 === 'MANA_RESTORE') manaRestore += (v2 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);

        return { finalDamage: rawDmg, isExecute, vampAmount, manaBurn, manaRestore };
    }

    private calculateControlDuration(target: Agent, type: string, baseDuration: number) {
        // Diminishing Returns (DR)
        const isHardCC = ['STUN', 'SILENCE', 'BANISH'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false, isReduced: false };

        const currentStack = target.drStacks[type] || 0;
        // Formula: 1 / (2 ^ stack)
        let drMultiplier = Math.pow(0.5, currentStack);
        if (drMultiplier < 0.2) drMultiplier = 0;

        return {
            effectiveDuration: baseDuration * drMultiplier,
            isImmune: drMultiplier === 0,
            isReduced: drMultiplier < 1.0 && drMultiplier > 0
        };
    }

    private calculateImpulseVector(origin: {x: number, y: number}, target: {x: number, y: number}, damage: number) {
        const dx = target.x - origin.x;
        const dy = target.y - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);

        // If center hit, random scatter
        if (len <= 0) {
            const ang = Math.random() * Math.PI * 2;
            return {
                x: Math.cos(ang) * COMBAT_PARAM.HIT_IMPULSE_MIN,
                y: Math.sin(ang) * COMBAT_PARAM.HIT_IMPULSE_MIN
            };
        }

        // Dynamic Force Calculation
        // Use a much stronger multiplier to be visible against physics stiffness
        const force = Math.min(COMBAT_PARAM.HIT_IMPULSE_MAX, Math.max(COMBAT_PARAM.HIT_IMPULSE_MIN, damage * 1.5));

        return {
            x: (dx / len) * force,
            y: (dy / len) * force
        };
    }

    private calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 

        // --- PHYSICS RULE: Force must exceed resistance to move ---
        const tilesToPush = Math.max(0, rawForce - resistance);

        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

        let currentH = {q: target.q, r: target.r};
        let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
        let finalH = currentH;

        // --- KNOCKBACK ITERATION ---
        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN = null;
            let bestDot = -99;

            // Find direction
            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                const dot = nDir.x * vector.x + nDir.y * vector.y;

                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }

            if (bestN) {
                // 1. Map Bounds
                if (!engine.isValid(bestN.q, bestN.r)) break; 

                // 2. Unit Collision (Block if another unit is there)
                // We pass 'target.id' as ignoreId, because we don't want to collide with ourselves, 
                // but we DO want to collide with everyone else.
                if (engine.isBlocked(bestN.q, bestN.r, target.id, target.movementType)) break;

                // 3. PULL Special Rule: Do not pull INTO the source (Stop adjacent)
                // If the next tile is the source tile, and it's a pull, stop here.
                if (type === 'PULL' && bestN.q === source.q && bestN.r === source.r) break;

                // 4. Height Check (Walls/Cliffs)
                // Knockback ignores some height rules but shouldn't push up a 50m wall
                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > currentHeight + BLOCK_HEIGHT * 2) break; // Can't push up too high
                if (nextHeight < currentHeight - BLOCK_HEIGHT * 3) break; // Can't push off huge cliff safely

                currentH = bestN;
                currentHeight = nextHeight;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            // Visual: Reset path interpolation to avoid glitching
            if (target.isMoving) {
                target.isMoving = false;
                target.path = [];
            }
            return { applied: true };
        }
        return { applied: false };
    }

    private isIceSkill(skill: Skill): boolean {
        const c = skill.color.toLowerCase();
        const n = skill.name;
        return c.includes('blue') || c.includes('#60a5fa') || c.includes('#e0f2fe') || 
               n.includes("冰") || n.includes("凍") || n.includes("雪");
    }
}

