                <div className="flex flex-col gap-1 opacity-20 px-1 cursor-grab active:cursor-grabbing">
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';
import { Helpers, ROLE_MAP } from '../inspector/InspectorConstants';
import { BehaviorTreeTab } from '../inspector/tabs/BehaviorTreeTab';
import { UnitStatusTab } from '../inspector/tabs/UnitStatusTab';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    engine: GameEngine;
    onClose: () => void;
}

type TabType = 'NONE' | 'AI' | 'SKILLS';

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, engine, onClose }) => {
    const [viewMode, setViewMode] = useState<TabType>('NONE'); // NONE = Compact, AI/SKILLS = Expanded
    const [isMinimized, setIsMinimized] = useState(false);
    const [isConfigExpanded, setIsConfigExpanded] = useState(false); // Config Drawer State
    const [version, setVersion] = useState(0); // For forcing UI refresh

    // The ref moves the outer container
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 20
    });

    // Refresh Loop for visual updates (Health, AI Nodes) when expanded
    useEffect(() => {
        if (!isMinimized) {
            const interval = setInterval(() => setVersion(n => n + 1), 100);
            return () => clearInterval(interval);
        }
    }, [viewMode, isMinimized]);

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/30' : 'border-red-500/30';
    const glowClass = isBlue ? 'shadow-[0_8px_32px_rgba(59,130,246,0.15)]' : 'shadow-[0_8px_32px_rgba(239,68,68,0.15)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-5 h-5" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-5 h-5" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-5 h-5" />;
            case Role.MAGE: return <Icons.RoleMage className="w-5 h-5" />;
            case Role.SUPPORT: return <Icons.RoleSupport className="w-5 h-5" />;
            default: return null;
        }
    };

    const setRole = (r: string) => { 
        if (agent) {
            agent.role = r as Role; 
            setVersion(v => v + 1);
        }
    };

    return (
        <div 
            ref={ref}
            className={`z-30 pointer-events-auto select-none transition-all duration-300 ease-out`}
            style={{ 
                ...style, 
                width: isMinimized ? 'auto' : (viewMode === 'NONE' ? '320px' : '420px'),
                maxWidth: '95vw'
            }}
        >
            {isMinimized ? (
                // --- MINIMIZED PILL ---
                <div 
                    {...dragHandlers}
                    className={`liquid-card !rounded-full p-2 pl-3 flex items-center gap-3 cursor-grab active:cursor-grabbing border-l-4 ${borderColor} ${glowClass} bg-black/80`}
                >
                    <div className={`w-2 h-2 rounded-full ${isBlue ? 'bg-blue-500 box-shadow-[0_0_10px_blue]' : 'bg-red-500 box-shadow-[0_0_10px_red]'} animate-pulse`}></div>
                    <span className="font-mono font-bold text-xs text-white tracking-widest">{agent.id}</span>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsMinimized(false); }}
                        onPointerDown={e => e.stopPropagation()}
                        className="w-8 h-8 flex items-center justify-center rounded-full bg-white/5 hover:bg-white/20 text-slate-300 hover:text-white transition-all"
                    >
                        <Icons.Expand className="w-4 h-4" />
                    </button>
                </div>
            ) : (
                // --- FULL CARD ---
                <div className={`liquid-card !rounded-[24px] overflow-hidden flex flex-col ${glowClass} border border-white/10 backdrop-blur-xl bg-slate-900/90`}>

                    {/* Header - DRAGGABLE */}
                    <div 
                        {...dragHandlers}
                        className={`p-3 bg-gradient-to-b from-white/10 to-transparent relative cursor-grab active:cursor-grabbing ${isDragging ? 'cursor-grabbing' : ''}`}
                    >
                        <div className="flex justify-between items-start gap-4">
                            {/* Identity & Config Toggle */}
                            <div className="flex items-center gap-3 flex-1 min-w-0">
                                <div className={`w-10 h-10 flex items-center justify-center rounded-xl bg-black/40 border ${borderColor} ${themeColor} shadow-inner shrink-0`}>
                                    {renderRoleIcon(agent.role)}
                                </div>
                                <div className="flex flex-col min-w-0">
                                    <div className={`font-mono font-bold text-sm ${themeColor} leading-none tracking-tight truncate`}>{agent.id}</div>
                                    <div className="flex items-center gap-2 mt-1.5">
                                        <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider truncate">{agent.role}</span>
                                        {/* Config Button (Larger & clearer) */}
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setIsConfigExpanded(!isConfigExpanded); }}
                                            onPointerDown={e => e.stopPropagation()}
                                            className={`w-7 h-7 flex items-center justify-center rounded-lg transition-all ${isConfigExpanded ? 'bg-cyan-500 text-white shadow-md' : 'bg-white/10 text-slate-400 hover:text-white hover:bg-white/20'}`}
                                            title="Edit Unit Stats"
                                        >
                                            <Icons.Settings className={`w-4 h-4 ${isConfigExpanded ? 'animate-spin-slow' : ''}`} />
                                        </button>
                                    </div>
                                </div>
                            </div>

                            {/* Controls */}
                            <div className="flex gap-1 items-center shrink-0" onPointerDown={e => e.stopPropagation()}>
                                {/* Mode Toggles */}
                                <div className="flex bg-black/40 rounded-lg p-0.5 border border-white/5 mr-2">
                                    <button 
                                        onClick={() => setViewMode(viewMode === 'AI' ? 'NONE' : 'AI')} 
                                        className={`px-3 py-1.5 rounded-md text-[9px] font-bold transition-all ${viewMode === 'AI' ? 'bg-amber-500/20 text-amber-300 shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}
                                        title="AI Monitor"
                                    >
                                        AI
                                    </button>
                                    <button 
                                        onClick={() => setViewMode(viewMode === 'SKILLS' ? 'NONE' : 'SKILLS')} 
                                        className={`px-3 py-1.5 rounded-md text-[9px] font-bold transition-all ${viewMode === 'SKILLS' ? 'bg-cyan-500/20 text-cyan-300 shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}
                                        title="Linkage"
                                    >
                                        LINK
                                    </button>
                                </div>

                                <button onClick={() => setIsMinimized(true)} className="liquid-icon-btn w-8 h-8 text-[10px] bg-white/5 hover:bg-white/20 text-slate-400 hover:text-white border-transparent">
                                    <Icons.Minimize className="w-3 h-3" />
                                </button>
                                <button onClick={onClose} className="liquid-icon-btn w-8 h-8 text-[10px] bg-red-500/10 hover:bg-red-500/30 text-red-400 border-transparent">
                                    <Icons.Close className="w-3 h-3" />
                                </button>
                            </div>
                        </div>

                        {/* CONFIG DRAWER */}
                        <div 
                            className={`overflow-hidden transition-all duration-300 ease-out ${isConfigExpanded ? 'max-h-32 opacity-100 mt-3 pb-1 scale-100' : 'max-h-0 opacity-0 scale-95 origin-top'}`}
                            onPointerDown={e => e.stopPropagation()}
                        >
                            <div className="grid grid-cols-3 gap-2 bg-black/40 p-2 rounded-xl border border-white/10 shadow-inner">
                                <div className="space-y-1">
                                    <label className="text-[8px] font-bold text-slate-500 uppercase tracking-widest block text-center">Class</label>
                                    <select 
                                        className="liquid-input h-8 w-full text-[10px] font-bold bg-black/50 !rounded-lg border-white/10 focus:border-cyan-500/50 p-0 pl-2 text-white"
                                        value={agent.role} 
                                        onChange={(e) => setRole(e.target.value)}
                                    >
                                        {Object.values(Role).map(r => <option key={r} value={r} className="bg-slate-900">{ROLE_MAP[r].label.split(' ')[0]}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[8px] font-bold text-green-500/70 uppercase tracking-widest block text-center">HP</label>
                                    <input 
                                        type="number" 
                                        className="liquid-input h-8 w-full text-center text-green-400 font-mono font-bold text-xs bg-black/50 !rounded-lg border-white/10 focus:border-green-500/50 p-0"
                                        value={Math.round(agent.maxHp)} 
                                        onChange={(e) => { const v = parseInt(e.target.value); agent.maxHp = v; agent.hp = v; setVersion(n=>n+1); }} 
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[8px] font-bold text-blue-500/70 uppercase tracking-widest block text-center">MP</label>
                                    <input 
                                        type="number" 
                                        className="liquid-input h-8 w-full text-center text-blue-400 font-mono font-bold text-xs bg-black/50 !rounded-lg border-white/10 focus:border-blue-500/50 p-0"
                                        value={Math.round(agent.maxMp)} 
                                        onChange={(e) => { agent.maxMp = parseInt(e.target.value); setVersion(n=>n+1); }} 
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Vitals Bars */}
                        <div className="space-y-1 mt-3 pointer-events-none">
                            <div className="h-1.5 bg-black/50 rounded-full overflow-hidden w-full flex border border-white/5">
                                <div className="h-full bg-emerald-500 transition-all duration-300" style={{width: `${Math.max(0, hpPct)}%`}}></div>
                            </div>
                            {agent.maxMp > 0 && (
                                <div className="h-1 bg-black/50 rounded-full overflow-hidden w-full flex border border-white/5">
                                    <div className="h-full bg-cyan-500 transition-all duration-300" style={{width: `${mpPct}%`}}></div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Compact Status */}
                    {viewMode === 'NONE' && (
                        <div className="px-3 pb-3 cursor-default" onPointerDown={e => e.stopPropagation()}>
                            <div className="flex justify-between items-center bg-black/20 rounded-lg p-2 border border-white/5">
                                <div className="flex flex-col">
                                    <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">CURRENT STATE</span>
                                    <span className={`text-xs font-mono font-bold ${agent.hp <= 0 ? 'text-slate-600' : 'text-cyan-300'}`}>
                                        {Helpers.getStatusLabel(agent.btStatus)}
                                    </span>
                                </div>
                                <div className="flex gap-1">
                                    {agent.stunTimer > 0 && <span className="liquid-tag bg-amber-500/20 border-amber-500/50 text-amber-300 text-[9px] px-1.5">STUN</span>}
                                    {agent.silenceTimer > 0 && <span className="liquid-tag bg-slate-700/50 border-slate-500 text-slate-300 text-[9px] px-1.5">MUTE</span>}
                                    {agent.banished && <span className="liquid-tag bg-purple-500/20 border-purple-500/50 text-purple-300 text-[9px] px-1.5">BANISH</span>}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* EXPANDED CONTENT AREA */}
                    {viewMode !== 'NONE' && (
                        <div 
                            className="border-t border-white/5 bg-black/20 animate-slide-down overflow-hidden flex flex-col transition-all"
                            style={{ height: '320px' }} 
                            onPointerDown={e => e.stopPropagation()}
                        >
                            {viewMode === 'AI' ? (
                                <div className="w-full h-full relative">
                                    <BehaviorTreeTab agent={agent} version={version} engine={engine} />
                                    <div className="absolute bottom-2 right-2 text-[9px] text-white/20 font-mono pointer-events-none">
                                        LIVE MONITORING
                                    </div>
                                </div>
                            ) : (
                                <div className="w-full h-full relative p-2">
                                    <UnitStatusTab agent={agent} db={engine.skillDB} onUpdate={() => setVersion(n => n+1)} />
                                </div>
                            )}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useRef, useEffect } from 'react';
import { Agent } from '../../../engine/game';
import { Role, Skill, Team } from '../../../types';
import { ROLE_MAP, TAG_MAP } from '../InspectorConstants';
import { SkillIcon } from '../parts/SkillIcon';
import { Icons } from '../../ui/icons';

interface UnitStatusTabProps {
    agent: Agent;
    db: Skill[];
    onHoverSkill?: (skill: Skill | null) => void;
    onUpdate: () => void;
}

export const UnitStatusTab: React.FC<UnitStatusTabProps> = ({ agent, db, onHoverSkill, onUpdate }) => {

    const setSkill = (idx: number, id: string) => {
        agent.skillIds[idx] = id || null; 
        onUpdate();
    };

    // --- GRAB & DRAG SCROLL LOGIC ---
    const scrollRef = useRef<HTMLDivElement>(null);
    const rafRef = useRef<number>(0);
    const dragState = useRef({
        isDown: false,
        startY: 0,
        scrollTop: 0,
        lastY: 0,
        velocity: 0,
        lastTime: 0
    });

    const stopMomentum = () => {
        if (rafRef.current) {
            cancelAnimationFrame(rafRef.current);
            rafRef.current = 0;
        }
    };

    const handlePointerDown = (e: React.PointerEvent) => {
        if (!scrollRef.current) return;
        if ((e.target as HTMLElement).tagName === 'SELECT') return;

        e.stopPropagation();
        e.preventDefault();

        dragState.current.isDown = true;
        dragState.current.startY = e.pageY;
        dragState.current.scrollTop = scrollRef.current.scrollTop;
        dragState.current.lastY = e.pageY;
        dragState.current.velocity = 0;
        dragState.current.lastTime = performance.now();

        stopMomentum();
        (e.target as Element).setPointerCapture(e.pointerId);
        scrollRef.current.style.cursor = 'grabbing';
        scrollRef.current.style.userSelect = 'none';
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!dragState.current.isDown || !scrollRef.current) return;
        e.preventDefault();
        e.stopPropagation();

        const now = performance.now();
        const y = e.pageY;
        const delta = y - dragState.current.startY;
        scrollRef.current.scrollTop = dragState.current.scrollTop - delta;

        const timeDelta = now - dragState.current.lastTime;
        if (timeDelta > 0) {
            const dist = y - dragState.current.lastY;
            dragState.current.velocity = dist; 
            dragState.current.lastY = y;
            dragState.current.lastTime = now;
        }
    };

    const handlePointerUp = (e: React.PointerEvent) => {
        if (!dragState.current.isDown) return;
        dragState.current.isDown = false;
        (e.target as Element).releasePointerCapture(e.pointerId);
        if (scrollRef.current) {
            scrollRef.current.style.cursor = 'grab';
            scrollRef.current.style.removeProperty('user-select');
        }
        startMomentum();
    };

    const startMomentum = () => {
        stopMomentum();
        const step = () => {
            if (!scrollRef.current) return;
            dragState.current.velocity *= 0.95; 
            if (Math.abs(dragState.current.velocity) > 0.5) {
                scrollRef.current.scrollTop -= dragState.current.velocity;
                rafRef.current = requestAnimationFrame(step);
            } else {
                dragState.current.velocity = 0;
            }
        };
        step();
    };

    useEffect(() => { return () => stopMomentum(); }, []);

    return (
        <div className="flex flex-col h-full w-full bg-transparent overflow-hidden">

            <div 
                ref={scrollRef}
                className="flex-1 overflow-y-auto custom-scrollbar min-h-0 px-4 py-4 cursor-grab active:cursor-grabbing touch-none"
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
            >
                <div className="text-[9px] font-bold text-slate-500 uppercase tracking-[0.2em] flex items-center gap-2 mb-3 sticky top-0 bg-slate-900/95 backdrop-blur z-10 py-2 border-b border-white/5 pointer-events-none">
                    <Icons.Database className="w-3 h-3" />
                    NEURAL LINKAGE
                </div>

                <div className="space-y-3 pb-24">
                    {['ULT', 'ACTIVE', 'BASIC'].map((tag, i) => {
                        const currentSkillId = agent.skillIds[i];
                        const currentSkill = db.find(s => s.id === currentSkillId);

                        const availableSkills = db.filter(s => s.tag === tag);
                        const skillsByRole: Record<string, Skill[]> = {};
                        availableSkills.forEach(s => {
                            if(!skillsByRole[s.role]) skillsByRole[s.role] = [];
                            skillsByRole[s.role].push(s);
                        });
                        const roleOrder = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

                        return (
                            <div key={i} className="liquid-card !bg-slate-900/40 border border-white/5 transition-all hover:border-white/20 group !rounded-xl overflow-visible" onMouseEnter={() => onHoverSkill && onHoverSkill(currentSkill || null)} onMouseLeave={() => onHoverSkill && onHoverSkill(null)}>
                                <div className="flex items-center gap-3 p-3 bg-white/[0.02]">
                                    <SkillIcon skill={currentSkill || null} className="w-10 h-10 !rounded-lg shadow-lg shrink-0 border border-white/10 bg-black/50" />
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-center mb-1">
                                            <span className={`text-[9px] font-bold uppercase tracking-wider px-1.5 rounded border ${tag === 'ULT' ? 'text-purple-300 border-purple-500/30 bg-purple-500/10' : (tag === 'ACTIVE' ? 'text-cyan-300 border-cyan-500/30 bg-cyan-500/10' : 'text-slate-300 border-slate-500/30 bg-slate-500/10')}`}>
                                                {TAG_MAP[tag].label} SLOT
                                            </span>
                                            {currentSkill && <span className="text-[9px] text-slate-500 font-mono">{currentSkill.id}</span>}
                                        </div>
                                        <div className="relative">
                                            <select 
                                                className={`liquid-input h-8 w-full text-xs font-bold appearance-none cursor-pointer uppercase tracking-wide !rounded-lg pr-8 text-white ${!currentSkillId ? 'text-slate-500 !bg-black/30' : 'text-slate-200 !bg-black/50 hover:!bg-black/70'}`}
                                                value={agent.skillIds[i] || ""} 
                                                onChange={(e) => setSkill(i, e.target.value)}
                                                onPointerDown={(e) => e.stopPropagation()} 
                                            >
                                                <option value="" className="bg-slate-900 text-slate-500">-- NO LINKAGE --</option>
                                                {roleOrder.map(role => {
                                                    const skills = skillsByRole[role];
                                                    if (!skills || skills.length === 0) return null;
                                                    return (
                                                        <optgroup key={role} label={ROLE_MAP[role].label} className="bg-slate-900 text-slate-400">
                                                            {skills.map(s => (
                                                                <option key={s.id} value={s.id} className="text-white bg-slate-900">
                                                                    {s.name} {s.team !== undefined ? (s.team === Team.BLUE ? '🔵' : '🔴') : ''}
                                                                </option>
                                                            ))}
                                                        </optgroup>
                                                    );
                                                })}
                                            </select>
                                            <div className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none text-[8px]">▼</div>
                                        </div>
                                    </div>
                                </div>

                                {currentSkill && (
                                    <div className="px-3 py-2 text-xs bg-black/20 border-t border-white/5 pointer-events-none">
                                        <div className="text-slate-400 italic mb-2 leading-relaxed border-l-2 border-white/10 pl-2 text-[10px]">
                                            {currentSkill.desc}
                                        </div>
                                        <div className="grid grid-cols-4 gap-2 text-[9px] font-mono text-slate-400">
                                            <div className="bg-black/30 rounded px-1 py-0.5 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">PWR</span> <span className="text-slate-200">{currentSkill.power}</span></div>
                                            <div className="bg-black/30 rounded px-1 py-0.5 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">CD</span> <span className="text-slate-200">{currentSkill.cd}s</span></div>
                                            <div className="bg-black/30 rounded px-1 py-0.5 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">MP</span> <span className="text-blue-300">{currentSkill.cost}</span></div>
                                            <div className="bg-black/30 rounded px-1 py-0.5 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">RNG</span> <span className="text-slate-200">{currentSkill.range}</span></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

import React, { useRef } from 'react';
import { Team } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';

interface PlaybackHUDProps {
    hidden: boolean;
    isPlaying: boolean;
    winner: Team | null;
    timeScale: number;
    onTogglePlay: () => void;
    onRestart: () => void;
    onRandom: () => void;
    onSetTimeScale: (v: number) => void;
    onShowcase: () => void;
}

export const PlaybackHUD: React.FC<PlaybackHUDProps> = ({
    hidden, isPlaying, winner, timeScale, onTogglePlay, onRestart, onRandom, onSetTimeScale, onShowcase
}) => {
    const ref = useRef<HTMLDivElement>(null);

    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-center',
        margin: 30
    });

    // Determine visual status color based on state
    const statusColor = winner ? (winner === Team.BLUE ? 'text-blue-400' : 'text-red-400') : (isPlaying ? 'text-emerald-400' : 'text-amber-400');
    const glowClass = winner ? (winner === Team.BLUE ? 'shadow-[0_0_20px_rgba(59,130,246,0.3)]' : 'shadow-[0_0_20px_rgba(239,68,68,0.3)]') : (isPlaying ? 'shadow-[0_0_20px_rgba(16,185,129,0.2)]' : '');

    return (
        <div 
            ref={ref}
            className={`z-40 transition-all duration-500 ${hidden ? 'opacity-0 translate-y-10 pointer-events-none' : 'opacity-100 translate-y-0'}`}
            style={style}
            {...dragHandlers}
        >
            {/* Main Capsule Container */}
            <div className={`liquid-card !rounded-[24px] p-2 pr-4 flex items-center gap-4 select-none cursor-grab active:cursor-grabbing bg-slate-900/90 backdrop-blur-xl border border-white/10 ${glowClass} ${isDragging ? 'cursor-grabbing scale-105' : ''}`}>

                {/* 1. Play/Pause (Primary Action) */}
                <div className="relative group">
                    <div className={`absolute inset-0 rounded-2xl blur-md opacity-20 group-hover:opacity-40 transition-opacity ${isPlaying ? 'bg-emerald-500' : 'bg-amber-500'}`}></div>
                    <button 
                        onClick={(e) => { e.stopPropagation(); onTogglePlay(); }}
                        onPointerDown={(e) => e.stopPropagation()} // CRITICAL: Prevents drag start
                        disabled={winner !== null}
                        className={`relative w-14 h-14 rounded-2xl flex items-center justify-center text-2xl transition-all duration-200 border shadow-inner
                            ${isPlaying 
                                ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/20' 
                                : 'bg-amber-500/10 text-amber-400 border-amber-500/30 hover:bg-amber-500/20'}
                            disabled:opacity-50 disabled:cursor-not-allowed`}
                    >
                        {isPlaying ? <Icons.Pause className="w-6 h-6 fill-current" /> : <Icons.Play className="w-6 h-6 fill-current" />}
                    </button>
                </div>

                <div className="h-8 w-px bg-white/10"></div>

                {/* 2. Secondary Controls (Reset / Random) */}
                <div className="flex gap-2">
                    <button 
                        onClick={(e) => { e.stopPropagation(); onRestart(); }}
                        onPointerDown={(e) => e.stopPropagation()}
                        className="w-10 h-10 rounded-xl bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white border border-white/5 hover:border-white/20 flex items-center justify-center transition-all active:scale-95"
                        title="重置 (Reset)"
                    >
                        <Icons.Restart className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={(e) => { e.stopPropagation(); onRandom(); }}
                        onPointerDown={(e) => e.stopPropagation()}
                        className="w-10 h-10 rounded-xl bg-purple-500/10 hover:bg-purple-500/20 text-purple-400 hover:text-purple-200 border border-purple-500/20 hover:border-purple-500/40 flex items-center justify-center transition-all active:scale-95"
                        title="隨機戰場 (Random)"
                    >
                        <Icons.Dice className="w-5 h-5" />
                    </button>
                </div>

                <div className="h-8 w-px bg-white/10"></div>

                {/* 3. Time Dilation Control */}
                <div className="flex flex-col w-32 gap-1.5" onPointerDown={(e) => e.stopPropagation()}>
                    <div className="flex justify-between items-center px-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">SPEED</span>
                        <span className={`text-[10px] font-mono font-bold ${timeScale > 1.0 ? 'text-cyan-400 text-glow-cyan' : 'text-slate-300'}`}>
                            {timeScale.toFixed(1)}x
                        </span>
                    </div>

                    {/* Enhanced Slider Track */}
                    <div className="relative h-6 w-full flex items-center group cursor-pointer">
                        {/* Background Track */}
                        <div className="absolute left-0 right-0 h-2 bg-black/50 rounded-full border border-white/10 overflow-hidden">
                            {/* Fill Progress */}
                            <div 
                                className="h-full bg-gradient-to-r from-cyan-900 to-cyan-500 transition-all duration-100 ease-out" 
                                style={{width: `${(timeScale/3)*100}%`}}
                            ></div>
                        </div>

                        {/* Thumb Knob (Visual Only, follows logic) */}
                        <div 
                            className="absolute h-4 w-1.5 bg-white rounded-full shadow-[0_0_10px_cyan] pointer-events-none transition-all duration-100 ease-out"
                            style={{left: `calc(${(timeScale/3)*100}% - 3px)`}}
                        ></div>

                        {/* Invisible Touch Target */}
                        <input 
                            type="range" min="0.1" max="3.0" step="0.1" 
                            value={timeScale} onChange={(e) => onSetTimeScale(parseFloat(e.target.value))}
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                        />
                    </div>
                </div>

                <div className="h-8 w-px bg-white/10"></div>

                {/* 4. Showcase / System */}
                <button 
                    onClick={(e) => { e.stopPropagation(); onShowcase(); }}
                    onPointerDown={(e) => e.stopPropagation()}
                    className="w-10 h-10 rounded-xl hover:bg-cyan-950/50 text-slate-500 hover:text-cyan-400 transition-all flex items-center justify-center group"
                    title="展示模式 (Showcase)"
                >
                    <Icons.TV className="w-5 h-5 group-hover:scale-110 transition-transform" />
                </button>

                {/* Drag Handle Indicator */}
                <div className="w-1.5 h-8 flex flex-col justify-center gap-1 opacity-20 cursor-grab">
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                </div>
            </div>
        </div>
    );
};

import React, { useRef } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;
}

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle
    } = props;

    // Draggable Hook
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-center',
        margin: 40
    });

    const isUnitTool = tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED;
    const isObstacleTool = tool === ToolType.OBSTACLE;

    return (
        <div 
            ref={ref}
            className={`z-40 flex flex-col items-center gap-2`}
            style={style}
            {...dragHandlers}
        >
            {/* MAIN TOOLBAR */}
            <div className={`liquid-card !bg-slate-900/90 !backdrop-blur-3xl !rounded-full p-2 flex items-center gap-2 shadow-[0_10px_40px_rgba(0,0,0,0.5)] cursor-grab ${isDragging ? 'cursor-grabbing ring-2 ring-cyan-500/30' : ''}`}>

                {/* Drag Handle */}
                <div className="w-6 flex flex-col gap-1 items-center justify-center opacity-30 hover:opacity-100 transition-opacity px-2 border-r border-white/10" onPointerDown={dragHandlers.onPointerDown}>
                    <div className="w-1 h-1 bg-white rounded-full"></div>
                    <div className="w-1 h-1 bg-white rounded-full"></div>
                    <div className="w-1 h-1 bg-white rounded-full"></div>
                </div>

                {/* 1. SELECT */}
                <button 
                    onClick={() => setTool(ToolType.SELECT)} 
                    onPointerDown={(e) => e.stopPropagation()}
                    className={`liquid-icon-btn ${tool === ToolType.SELECT ? 'bg-white/20 text-white border-white/40 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'text-slate-400 border-transparent bg-transparent hover:bg-white/10'}`}
                    title="選取 / 移動"
                >
                    <Icons.Select className="w-5 h-5" />
                </button>

                <div className="w-px h-6 bg-white/10 mx-1"></div>

                {/* 2. BLUE TEAM */}
                <button 
                    onClick={() => setTool(ToolType.ADD_BLUE)} 
                    onPointerDown={(e) => e.stopPropagation()}
                    className={`liquid-icon-btn ${tool === ToolType.ADD_BLUE ? 'bg-blue-500/20 text-blue-400 border-blue-400/50 shadow-[0_0_15px_rgba(59,130,246,0.4)]' : 'text-slate-500 border-transparent bg-transparent hover:text-blue-400 hover:bg-blue-500/10'}`}
                    title="部署藍軍"
                >
                    <Icons.Deploy className="w-5 h-5" />
                </button>

                {/* 3. RED TEAM */}
                <button 
                    onClick={() => setTool(ToolType.ADD_RED)} 
                    onPointerDown={(e) => e.stopPropagation()}
                    className={`liquid-icon-btn ${tool === ToolType.ADD_RED ? 'bg-red-500/20 text-red-400 border-red-400/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 border-transparent bg-transparent hover:text-red-400 hover:bg-red-500/10'}`}
                    title="部署紅軍"
                >
                    <Icons.Deploy className="w-5 h-5" />
                </button>

                <div className="w-px h-6 bg-white/10 mx-1"></div>

                {/* 4. OBSTACLE */}
                <button 
                    onClick={() => setTool(ToolType.OBSTACLE)} 
                    onPointerDown={(e) => e.stopPropagation()}
                    className={`liquid-icon-btn ${tool === ToolType.OBSTACLE ? 'bg-amber-500/20 text-amber-400 border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)]' : 'text-slate-500 border-transparent bg-transparent hover:text-amber-400 hover:bg-amber-500/10'}`}
                    title="地形編輯"
                >
                    <Icons.Obstacle className="w-5 h-5" />
                </button>

                {/* 5. DELETE */}
                <button 
                    onClick={() => setTool(ToolType.DELETE)} 
                    onPointerDown={(e) => e.stopPropagation()}
                    className={`liquid-icon-btn ${tool === ToolType.DELETE ? 'bg-red-900/50 text-red-500 border-red-800 shadow-inner' : 'text-slate-500 border-transparent bg-transparent hover:text-red-500 hover:bg-red-900/20'}`}
                    title="移除"
                >
                    <Icons.Delete className="w-5 h-5" />
                </button>
            </div>

            {/* SUB MENU: UNIT SETTINGS */}
            {isUnitTool && (
                <div className="liquid-card !rounded-2xl p-2 flex items-center gap-3 animate-slide-down origin-top shadow-xl border-t-0" onPointerDown={e => e.stopPropagation()}>
                    {/* HP Input */}
                    <div className="flex items-center gap-1 bg-black/40 rounded-lg px-2 py-1 border border-white/5">
                        <span className="text-[10px] font-bold text-green-500">HP</span>
                        <input 
                            type="number" 
                            value={hpInput} 
                            onChange={(e) => setHpInput(Math.max(1, parseInt(e.target.value)))} 
                            className="w-10 bg-transparent text-white text-xs font-mono text-center outline-none"
                        />
                    </div>

                    {/* Mode Toggle */}
                    <div className="flex bg-black/40 rounded-lg p-0.5 border border-white/5">
                        <button onClick={() => setSpawnMode('RANDOM')} className={`px-2 py-1 rounded text-[10px] font-bold transition-all ${spawnMode === 'RANDOM' ? 'bg-cyan-500/20 text-cyan-300' : 'text-slate-500 hover:text-slate-300'}`}>RND</button>
                        <button onClick={() => setSpawnMode('DRAFT')} className={`px-2 py-1 rounded text-[10px] font-bold transition-all ${spawnMode === 'DRAFT' ? 'bg-amber-500/20 text-amber-300' : 'text-slate-500 hover:text-slate-300'}`}>FIX</button>
                    </div>

                    {/* Role Select (Only in Draft) */}
                    {spawnMode === 'DRAFT' && (
                        <select 
                            value={draftRole} 
                            onChange={(e) => setDraftRole(e.target.value as Role)} 
                            className="bg-black/40 text-xs text-white rounded-lg px-2 py-1 border border-white/5 outline-none cursor-pointer hover:border-cyan-500/30"
                        >
                            {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                    )}
                </div>
            )}

            {/* SUB MENU: OBSTACLE SETTINGS */}
            {isObstacleTool && (
                <div className="liquid-card !rounded-2xl p-2 flex items-center gap-3 animate-slide-down origin-top shadow-xl border-t-0" onPointerDown={e => e.stopPropagation()}>
                    <select 
                        value={selectedObstacle} 
                        onChange={(e) => setSelectedObstacle(e.target.value)} 
                        className="bg-black/40 text-xs text-white rounded-lg px-3 py-1.5 border border-white/5 outline-none cursor-pointer hover:border-amber-500/30 w-32"
                    >
                        {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                    </select>

                    {/* Scene Select Shortcut */}
                    <select value={currentSceneId} onChange={(e) => onSetScene(e.target.value)} className="bg-black/40 text-[10px] text-slate-400 rounded-lg px-2 py-1.5 border border-white/5 outline-none cursor-pointer hover:text-white w-24">
                        {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                </div>
            )}
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';
import { Helpers, ROLE_MAP } from '../inspector/InspectorConstants';
import { BehaviorTreeTab } from '../inspector/tabs/BehaviorTreeTab';
import { UnitStatusTab } from '../inspector/tabs/UnitStatusTab';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    engine: GameEngine;
    onClose: () => void;
}

type TabType = 'NONE' | 'AI' | 'SKILLS';

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, engine, onClose }) => {
    const [viewMode, setViewMode] = useState<TabType>('NONE'); // NONE = Compact, AI/SKILLS = Expanded
    const [isMinimized, setIsMinimized] = useState(false);
    const [isConfigExpanded, setIsConfigExpanded] = useState(false); // Config Drawer State
    const [version, setVersion] = useState(0); // For forcing UI refresh

    // The ref moves the outer container
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 20
    });

    // Refresh Loop for visual updates (Health, AI Nodes) when expanded
    useEffect(() => {
        if (!isMinimized) {
            const interval = setInterval(() => setVersion(n => n + 1), 100);
            return () => clearInterval(interval);
        }
    }, [viewMode, isMinimized]);

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/30' : 'border-red-500/30';
    const glowClass = isBlue ? 'shadow-[0_8px_32px_rgba(59,130,246,0.15)]' : 'shadow-[0_8px_32px_rgba(239,68,68,0.15)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-5 h-5" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-5 h-5" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-5 h-5" />;
            case Role.MAGE: return <Icons.RoleMage className="w-5 h-5" />;
            case Role.SUPPORT: return <Icons.RoleSupport className="w-5 h-5" />;
            default: return null;
        }
    };

    const setRole = (r: string) => { 
        if (agent) {
            agent.role = r as Role; 
            setVersion(v => v + 1);
        }
    };

    return (
        <div 
            ref={ref}
            className={`z-30 pointer-events-auto select-none transition-all duration-300 ease-out`}
            style={{ 
                ...style, 
                width: isMinimized ? 'auto' : (viewMode === 'NONE' ? '320px' : '420px'),
                maxWidth: '95vw'
            }}
        >
            {isMinimized ? (
                // --- MINIMIZED PILL ---
                <div 
                    {...dragHandlers}
                    className={`liquid-card !rounded-full p-2 pl-3 flex items-center gap-3 cursor-grab active:cursor-grabbing border-l-4 ${borderColor} ${glowClass} bg-black/80`}
                >
                    <div className={`w-2 h-2 rounded-full ${isBlue ? 'bg-blue-500 box-shadow-[0_0_10px_blue]' : 'bg-red-500 box-shadow-[0_0_10px_red]'} animate-pulse`}></div>
                    <span className="font-mono font-bold text-xs text-white tracking-widest">{agent.id}</span>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsMinimized(false); }}
                        onPointerDown={e => e.stopPropagation()}
                        className="w-8 h-8 flex items-center justify-center rounded-full bg-white/5 hover:bg-white/20 text-slate-300 hover:text-white transition-all"
                    >
                        <Icons.Expand className="w-4 h-4" />
                    </button>
                </div>
            ) : (
                // --- FULL CARD ---
                <div className={`liquid-card !rounded-[24px] overflow-hidden flex flex-col ${glowClass} border border-white/10 backdrop-blur-xl bg-slate-900/90`}>

                    {/* Header - DRAGGABLE */}
                    <div 
                        {...dragHandlers}
                        className={`p-3 bg-gradient-to-b from-white/10 to-transparent relative cursor-grab active:cursor-grabbing ${isDragging ? 'cursor-grabbing' : ''}`}
                    >
                        <div className="flex justify-between items-start gap-4">
                            {/* Identity & Config Toggle */}
                            <div className="flex items-center gap-3 flex-1 min-w-0">
                                <div className={`w-10 h-10 flex items-center justify-center rounded-xl bg-black/40 border ${borderColor} ${themeColor} shadow-inner shrink-0`}>
                                    {renderRoleIcon(agent.role)}
                                </div>
                                <div className="flex flex-col min-w-0">
                                    <div className={`font-mono font-bold text-sm ${themeColor} leading-none tracking-tight truncate`}>{agent.id}</div>
                                    <div className="flex items-center gap-2 mt-1.5">
                                        <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider truncate">{agent.role}</span>
                                        {/* Config Button (Larger & clearer) */}
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setIsConfigExpanded(!isConfigExpanded); }}
                                            onPointerDown={e => e.stopPropagation()}
                                            className={`w-7 h-7 flex items-center justify-center rounded-lg transition-all ${isConfigExpanded ? 'bg-cyan-500 text-white shadow-md' : 'bg-white/10 text-slate-400 hover:text-white hover:bg-white/20'}`}
                                            title="Edit Unit Stats"
                                        >
                                            <Icons.Settings className={`w-4 h-4 ${isConfigExpanded ? 'animate-spin-slow' : ''}`} />
                                        </button>
                                    </div>
                                </div>
                            </div>

                            {/* Controls */}
                            <div className="flex gap-1 items-center shrink-0" onPointerDown={e => e.stopPropagation()}>
                                {/* Mode Toggles */}
                                <div className="flex bg-black/40 rounded-lg p-0.5 border border-white/5 mr-2">
                                    <button 
                                        onClick={() => setViewMode(viewMode === 'AI' ? 'NONE' : 'AI')} 
                                        className={`px-3 py-1.5 rounded-md text-[9px] font-bold transition-all ${viewMode === 'AI' ? 'bg-amber-500/20 text-amber-300 shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}
                                        title="AI Monitor"
                                    >
                                        AI
                                    </button>
                                    <button 
                                        onClick={() => setViewMode(viewMode === 'SKILLS' ? 'NONE' : 'SKILLS')} 
                                        className={`px-3 py-1.5 rounded-md text-[9px] font-bold transition-all ${viewMode === 'SKILLS' ? 'bg-cyan-500/20 text-cyan-300 shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}
                                        title="Linkage"
                                    >
                                        LINK
                                    </button>
                                </div>

                                <button onClick={() => setIsMinimized(true)} className="liquid-icon-btn w-8 h-8 text-[10px] bg-white/5 hover:bg-white/20 text-slate-400 hover:text-white border-transparent">
                                    <Icons.Minimize className="w-3 h-3" />
                                </button>
                                <button onClick={onClose} className="liquid-icon-btn w-8 h-8 text-[10px] bg-red-500/10 hover:bg-red-500/30 text-red-400 border-transparent">
                                    <Icons.Close className="w-3 h-3" />
                                </button>
                            </div>
                        </div>

                        {/* CONFIG DRAWER */}
                        <div 
                            className={`overflow-hidden transition-all duration-300 ease-out ${isConfigExpanded ? 'max-h-32 opacity-100 mt-3 pb-1 scale-100' : 'max-h-0 opacity-0 scale-95 origin-top'}`}
                            onPointerDown={e => e.stopPropagation()}
                        >
                            <div className="grid grid-cols-3 gap-2 bg-black/40 p-2 rounded-xl border border-white/10 shadow-inner">
                                <div className="space-y-1">
                                    <label className="text-[8px] font-bold text-slate-500 uppercase tracking-widest block text-center">Class</label>
                                    <select 
                                        className="liquid-input h-8 w-full text-[10px] font-bold bg-black/50 !rounded-lg border-white/10 focus:border-cyan-500/50 p-0 pl-2 text-white"
                                        value={agent.role} 
                                        onChange={(e) => setRole(e.target.value)}
                                    >
                                        {Object.values(Role).map(r => <option key={r} value={r} className="bg-slate-900">{ROLE_MAP[r].label.split(' ')[0]}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[8px] font-bold text-green-500/70 uppercase tracking-widest block text-center">HP</label>
                                    <input 
                                        type="number" 
                                        className="liquid-input h-8 w-full text-center text-green-400 font-mono font-bold text-xs bg-black/50 !rounded-lg border-white/10 focus:border-green-500/50 p-0"
                                        value={Math.round(agent.maxHp)} 
                                        onChange={(e) => { const v = parseInt(e.target.value); agent.maxHp = v; agent.hp = v; setVersion(n=>n+1); }} 
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[8px] font-bold text-blue-500/70 uppercase tracking-widest block text-center">MP</label>
                                    <input 
                                        type="number" 
                                        className="liquid-input h-8 w-full text-center text-blue-400 font-mono font-bold text-xs bg-black/50 !rounded-lg border-white/10 focus:border-blue-500/50 p-0"
                                        value={Math.round(agent.maxMp)} 
                                        onChange={(e) => { agent.maxMp = parseInt(e.target.value); setVersion(n=>n+1); }} 
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Vitals Bars */}
                        <div className="space-y-1 mt-3 pointer-events-none">
                            <div className="h-1.5 bg-black/50 rounded-full overflow-hidden w-full flex border border-white/5">
                                <div className="h-full bg-emerald-500 transition-all duration-300" style={{width: `${Math.max(0, hpPct)}%`}}></div>
                            </div>
                            {agent.maxMp > 0 && (
                                <div className="h-1 bg-black/50 rounded-full overflow-hidden w-full flex border border-white/5">
                                    <div className="h-full bg-cyan-500 transition-all duration-300" style={{width: `${mpPct}%`}}></div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Compact Status */}
                    {viewMode === 'NONE' && (
                        <div className="px-3 pb-3 cursor-default" onPointerDown={e => e.stopPropagation()}>
                            <div className="flex justify-between items-center bg-black/20 rounded-lg p-2 border border-white/5">
                                <div className="flex flex-col">
                                    <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">CURRENT STATE</span>
                                    <span className={`text-xs font-mono font-bold ${agent.hp <= 0 ? 'text-slate-600' : 'text-cyan-300'}`}>
                                        {Helpers.getStatusLabel(agent.btStatus)}
                                    </span>
                                </div>
                                <div className="flex gap-1">
                                    {agent.stunTimer > 0 && <span className="liquid-tag bg-amber-500/20 border-amber-500/50 text-amber-300 text-[9px] px-1.5">STUN</span>}
                                    {agent.silenceTimer > 0 && <span className="liquid-tag bg-slate-700/50 border-slate-500 text-slate-300 text-[9px] px-1.5">MUTE</span>}
