                    {/* Enhanced Slider Track */}
                    <div className="relative h-6 w-full flex items-center group cursor-pointer">
                        {/* Background Track */}
                        <div className="absolute left-0 right-0 h-2 bg-black/40 rounded-full border border-white/10 overflow-hidden">
