export const Helpers = {
    getRoleConfig: (role: Role) => ROLE_MAP[role] || { label: role, color: 'text-slate-400', border: 'border-slate-500' },

    getTeamConfig: (team: Team) => TEAM_MAP[team] || { label: 'Unknown', color: 'text-slate-400', bg: 'bg-slate-800' },

    getTagLabel: (tag: string) => TAG_MAP[tag]?.label || tag,

    getCCColor: (type?: string) => CC_TYPES.find(c => c.value === type)?.color || '#fff',

    getEffectLabel: (type?: string) => EFFECT_TYPES.find(e => e.value === type)?.label || type,

    getStatusLabel: (status: string) => {
        // Mapping raw strings from game engine to friendly UI labels
        if(status === '待機') return 'IDLE';
        if(status === '移動') return 'MOVING';
        if(status === '暈眩') return 'STUNNED';
        if(status === '放逐') return 'BANISHED';
        if(status === '沉默') return 'SILENCED';
        if(status === '死亡') return 'KIA';
        if(status === '被控') return 'DISABLED';
        if(status === '等待') return 'WAITING';
        if(status.startsWith('詠唱')) return 'CASTING';
        return status.toUpperCase();
    }
};

import React, { useRef, useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../../engine/game';
import { TreeNode } from '../parts/TreeNode';

interface BehaviorTreeTabProps {
    agent: Agent;
    version: number; // Force update trigger
    engine: GameEngine;
}

export const BehaviorTreeTab: React.FC<BehaviorTreeTabProps> = ({ agent, version, engine }) => {
    // BT Interaction State
    const [btScale, setBtScale] = useState(0.9); // Increased default scale for readability
    const [btPos, setBtPos] = useState({x: 0, y: 30});
    const btContainerRef = useRef<HTMLDivElement>(null);
    const [btFps, setBtFps] = useState(20); 

    // Local state to force re-render when we lazy-build the AI
    const [, forceUpdate] = useState(0);

    // Dragging Logic
    const isDraggingBT = useRef(false);
    const lastMousePos = useRef<{x: number, y: number} | null>(null);

    // Auto-Build AI if missing
    useEffect(() => {
        if (!agent.bt && engine) {
            agent.bt = engine.ai.buildAI(agent, engine);
            forceUpdate(n => n + 1);
        }
    }, [agent, engine]);

    // Reset view on agent change
    useEffect(() => {
        setBtPos({x: 0, y: 30});
        setBtScale(0.9);
    }, [agent.id]);

    const handleBtWheel = (e: React.WheelEvent) => {
        e.stopPropagation();
        const delta = e.deltaY > 0 ? -0.05 : 0.05;
        setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta)));
    };

    // --- POINTER EVENTS (Robust Dragging) ---
    const handlePointerDown = (e: React.PointerEvent) => { 
        e.preventDefault();
        e.stopPropagation(); // Prevent bubbling to parent Window Drag

        isDraggingBT.current = true;
        lastMousePos.current = { x: e.clientX, y: e.clientY };

        // Capture pointer so we keep receiving events even if cursor leaves the div
        (e.target as Element).setPointerCapture(e.pointerId);

        // Change cursor to grabbing
        if (btContainerRef.current) btContainerRef.current.style.cursor = 'grabbing';
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (isDraggingBT.current && lastMousePos.current) {
            e.preventDefault();
            e.stopPropagation();

            const dx = e.clientX - lastMousePos.current.x;
            const dy = e.clientY - lastMousePos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastMousePos.current = { x: e.clientX, y: e.clientY };
        }
    };

    const handlePointerUp = (e: React.PointerEvent) => { 
        if (isDraggingBT.current) {
            isDraggingBT.current = false; 
            lastMousePos.current = null;

            (e.target as Element).releasePointerCapture(e.pointerId);

            // Restore cursor
            if (btContainerRef.current) btContainerRef.current.style.cursor = 'grab';
        }
    };

    return (
        <div 
            className="flex-1 relative overflow-hidden flex flex-col min-h-0 w-full h-full cursor-grab active:cursor-grabbing select-none" 
            ref={btContainerRef} 
            onWheel={handleBtWheel} 
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp}
            // onPointerLeave is not needed because we use setPointerCapture
            style={{ touchAction: 'none' }}
        >
            {/* UI Overlay - Minimal for embedded view */}
            <div className="absolute top-2 right-2 z-20 px-2 py-1 text-[9px] font-mono text-slate-500 bg-black/40 rounded border border-white/5 pointer-events-none">
                {Math.round(btScale * 100)}%
            </div>

            {/* Content Layer */}
            <div 
                className="absolute inset-0 w-full h-full flex justify-center items-start origin-top will-change-transform pointer-events-none"
                style={{
                    transform: `translate(${btPos.x}px, ${btPos.y}px) scale(${btScale})`, 
                    // No background color here to allow game to show through
                }}
            >
                <div className="inline-block min-w-max pt-4 pb-20">
                    {agent.bt ? (
                        <TreeNode node={agent.bt} version={version} now={Date.now()} />
                    ) : (
                        <div className="flex flex-col items-center justify-center pt-10 opacity-50">
                            <span className="text-slate-400 font-mono text-xs">NO SIGNAL...</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { BTNode } from '../../../engine/behaviorTree';
import { NodeState } from '../../../types';

interface TreeNodeProps {
    node: BTNode;
    version: number;
    now: number;
}

export const TreeNode: React.FC<TreeNodeProps> = ({ node, version, now }) => {
    // Logic for Visual Persistence
    const timeDiff = now - node.lastRunTime;
    let visualState: NodeState | null = node.status;
    let isFading = false;
    let opacity = 1.0;

    if (!visualState && node.lastResult) {
        if (timeDiff < 1000) { 
            visualState = node.lastResult;
            isFading = true;
            if (timeDiff > 200) opacity = 0.7;
            if (timeDiff > 500) opacity = 0.4;
        }
    }

    const statusStyle = (s: NodeState | null) => {
        switch (s) {
            case NodeState.RUNNING: return "border-amber-500/80 bg-amber-950/80 text-amber-100 shadow-[0_0_20px_rgba(245,158,11,0.4)] ring-1 ring-amber-400 animate-pulse-glow z-10 scale-105";
            case NodeState.SUCCESS: return "border-emerald-500/50 bg-emerald-950/60 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]";
            case NodeState.FAILURE: return "border-red-800/50 bg-red-950/60 text-red-200 opacity-60";
            default: return "border-slate-700 bg-slate-800/80 text-slate-500 backdrop-blur-sm";
        }
    };

    const typeSymbol = (t: string) => {
        if(t === '?') return <span className="text-purple-400 font-bold mr-3 text-xl drop-shadow-md">?</span>;
        if(t === '->') return <span className="text-blue-400 font-bold mr-3 text-xl drop-shadow-md">➜</span>;
        if(t === 'COND') return <span className="text-pink-400 text-base mr-3 font-bold">◆</span>;
        if(t === 'ACT') return <span className="text-yellow-400 text-base mr-3 font-bold">⚡</span>;
        return null;
    }

    return (
        <div className="flex flex-col items-center">
            <div 
                className={`flex items-center px-6 py-4 rounded-2xl border transition-all duration-200 cursor-default select-none min-w-[160px] justify-center backdrop-blur-md ${statusStyle(visualState)}`}
                style={{ opacity: opacity }}
            >
                {typeSymbol(node.type)}
                <span className="whitespace-nowrap truncate max-w-[200px] font-bold text-sm tracking-wider font-mono">{node.n}</span>
            </div>
            {node.c && node.c.length > 0 && (
                <div className="flex flex-col items-center">
                    <div className={`w-px h-8 ${isFading ? 'bg-slate-600/30' : 'bg-slate-600/60'}`}></div>
                    <div className="flex items-start gap-6">
                        {node.c.map((child, idx) => (
                            <div key={child.id} className="flex flex-col items-center relative">
                                {/* Connector Lines */}
                                <div className="absolute top-0 left-0 w-full h-8 -mt-8 pointer-events-none">
                                     {node.c.length > 1 && (
                                         <>
                                            {idx === 0 && <div className="absolute right-0 top-0 w-1/2 h-px bg-slate-600/60 translate-y-8"></div>}
                                            {idx === node.c.length - 1 && <div className="absolute left-0 top-0 w-1/2 h-px bg-slate-600/60 translate-y-8"></div>}
                                            {idx > 0 && idx < node.c.length - 1 && <div className="absolute left-0 top-0 w-full h-px bg-slate-600/60 translate-y-8"></div>}
                                         </>
                                     )}
                                     <div className="absolute left-1/2 top-0 w-px h-8 bg-slate-600/60 translate-y-8 -translate-x-1/2"></div>
                                </div>

                                <div className="pt-8">
                                    <TreeNode node={child} version={version} now={now} />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 44; // Slightly wider for liquid look
const BAR_HEIGHT = 6; // Thicker for better gradient
const BAR_PADDING = 3;

interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 
}

export class HUDSystem {
    // Active Texts
    damageNumbers: FloatingText[] = [];

    // Memory Pool
    private pool: FloatingText[] = [];

    constructor() {
        // Pre-allocate pool
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false
        };
    }

    public addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        // UX FIX: Prevent Kill Streak Overlap
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; // Ults float very slowly
                life = 2.5; // Stay longer
                size = 24; // Bigger font
            } else {
                vy = -20; // Normal skills float gently
                life = 1.2;
                size = 14; // Smaller to be less intrusive
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; // Stay very long
            size = 32; // HUGE
        } else {
            // DAMAGE / HEAL
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; // Initial jump
        }

        // Get from pool
        let ft: FloatingText;
        if (this.pool.length > 0) {
            ft = this.pool.pop()!;
        } else {
            ft = this.createEmpty();
        }

        // Init
        ft.active = true;
        ft.x = x; ft.y = y;
        ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;

        this.damageNumbers.push(ft);
    }

    private release(ft: FloatingText) {
        ft.active = false;
        this.pool.push(ft);
    }

    update(dt: number) {
        // Reverse iterate to allow removal
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            // Physics integration
            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            // Gravity logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; // Friction
            } else if (d.type === 'KILL_STREAK') {
                d.vy *= 0.92; // Anti-gravity float
            }

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); // Fast remove from active list
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        // 1. Draw HP/MP Bars & Status Labels
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            // Determine Ground Level Logic
            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            this.drawUnitBars(ctx, a, headX, anchorY, isSelected, time);
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        // 2. Draw Floating Text
        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH'; gaugeColor = '#d8b4fe';
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS'; gaugeColor = '#facc15';
            } else {
                iconType = 'BANISH'; gaugeColor = '#7e22ce';
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN'; gaugeColor = '#fbbf24';
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE'; gaugeColor = '#94a3b8';
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean, time: number) {
        // --- LIQUID GLASS DESIGN ---
        const hasMp = agent.maxMp > 0;

        // Dimensions
        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; // Slight offset upwards

        // 1. Glass Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(startX, startY, totalW, totalH, 6);
        } else {
            ctx.rect(startX, startY, totalW, totalH); // Fallback
        }

        // Glass Material
        ctx.fillStyle = 'rgba(2, 6, 23, 0.6)'; // Slate-950 semi-transparent
        ctx.fill();

        // Rim Light
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.stroke();

        // Selection Pulse
        if (isSelected) {
            const pulse = 0.5 + Math.sin(time * 8) * 0.3;
            ctx.shadowColor = 'rgba(6, 182, 212, 0.8)'; // Cyan Glow
            ctx.shadowBlur = 10 + pulse * 5;
            ctx.strokeStyle = `rgba(6, 182, 212, ${0.4 + pulse * 0.4})`;
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        // Helper for Fluid Bars
        const drawFluidBar = (bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string, glow: string) => {
            if (pct <= 0.01) return;
            const fillW = Math.max(bh, bw * pct); // Keep capsule shape even when low

            ctx.save();
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, bh/2);
            else ctx.rect(bx, by, fillW, bh);

            // Liquid Gradient
            const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
            grad.addColorStop(0, colTop);
            grad.addColorStop(1, colBot);
            ctx.fillStyle = grad;

            // Inner Glow (Neon Core)
            ctx.shadowColor = glow;
            ctx.shadowBlur = 6;
            ctx.fill();
            ctx.shadowBlur = 0;

            // Surface Reflection (Glossy Top)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, bh/2);
            else ctx.rect(bx, by, fillW, bh * 0.4);
            ctx.fill();

            ctx.restore();
        };

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // 2. HP Bar
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        // Emerald Fluid
        drawFluidBar(barX, barY, contentW, hpHeight, hpPct, '#6ee7b7', '#10b981', 'rgba(16, 185, 129, 0.5)');

        // 3. MP Bar
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            // Cyan Fluid
            drawFluidBar(barX, mpY, contentW, mpHeight, mpPct, '#7dd3fc', '#0ea5e9', 'rgba(14, 165, 233, 0.5)');
        }
    }

    private drawCircularGauge(ctx: CanvasRenderingContext2D, x: number, y: number, pct: number, visualKey: string, color: string, isSkill: boolean) {
        const radius = 14;
        const iconY = y - 24; // Lifted slightly higher to clear the new glass HUD

        ctx.save();
        // Glass Background for Icon
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(2, 6, 23, 0.8)';
        ctx.fill();
        ctx.save();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        // Icon Opacity
        ctx.globalAlpha = 0.8;
        if (icon) ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        ctx.restore();

        // Rim
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Progress Ring (Neon)
        const safePct = Math.max(0, Math.min(1, pct));
        if (safePct > 0) {
            ctx.beginPath();
            // Start from top (-PI/2)
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 30;
                    const h = d.size + 16;

                    // Liquid Glass Badge for Ult Shout
                    const bgGrad = ctx.createLinearGradient(-w, -h/2, w, h/2);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.8)'); 
                    bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.8)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w, -h/2, w*2, h);

                    // Text Glow
                    ctx.shadowColor = d.color;
                    ctx.shadowBlur = 15;
                    ctx.fillStyle = '#fff';
                    ctx.fillText(d.text, 0, 0);
                    ctx.shadowBlur = 0;

                    ctx.strokeStyle = d.color;
                    ctx.lineWidth = 1;
                    ctx.strokeText(d.text, 0, 0);

                    ctx.restore();
                } else {
                    ctx.font = `bold italic ${d.size}px "Segoe UI", sans-serif`;
                    ctx.lineWidth = 3;
                    ctx.lineJoin = 'round';
                    ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)'; 
                    ctx.strokeText(d.text, d.x, d.y);
                    ctx.fillStyle = d.color;
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else if (d.type === 'CC') {
                ctx.font = `900 ${d.size}px "Arial Black", sans-serif`; 
                ctx.strokeStyle = 'rgba(0,0,0,1.0)';
                ctx.lineWidth = 3;
                ctx.strokeText(d.text, d.x, d.y);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, d.x, d.y);

            } else {
                ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                ctx.fillStyle = d.color; 
                ctx.strokeStyle = 'rgba(0,0,0,0.8)'; 
                ctx.lineWidth = 3; 
                ctx.strokeText(d.text, d.x, d.y); 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

import React, { useRef, useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../../engine/game';
import { TreeNode } from '../parts/TreeNode';

interface BehaviorTreeTabProps {
    agent: Agent;
    version: number; // Force update trigger
    engine: GameEngine;
}

export const BehaviorTreeTab: React.FC<BehaviorTreeTabProps> = ({ agent, version, engine }) => {
    // BT Interaction State
    const [btScale, setBtScale] = useState(0.9); // Increased default scale for readability
    const [btPos, setBtPos] = useState({x: 0, y: 30});
    const btContainerRef = useRef<HTMLDivElement>(null);
    const [btFps, setBtFps] = useState(20); 

    // Local state to force re-render when we lazy-build the AI
    const [, forceUpdate] = useState(0);

    // Dragging Logic
    const isDraggingBT = useRef(false);
    const lastMousePos = useRef<{x: number, y: number} | null>(null);

    // Auto-Build AI if missing
    useEffect(() => {
        if (!agent.bt && engine) {
            agent.bt = engine.ai.buildAI(agent, engine);
            forceUpdate(n => n + 1);
        }
    }, [agent, engine]);

    // Reset view on agent change
    useEffect(() => {
        setBtPos({x: 0, y: 30});
        setBtScale(0.9);
    }, [agent.id]);

    const handleBtWheel = (e: React.WheelEvent) => {
        e.stopPropagation();
        const delta = e.deltaY > 0 ? -0.05 : 0.05;
        setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta)));
    };

    // --- POINTER EVENTS (Robust Dragging) ---
    const handlePointerDown = (e: React.PointerEvent) => { 
        e.preventDefault();
        e.stopPropagation(); // Prevent bubbling to parent Window Drag

        isDraggingBT.current = true;
        lastMousePos.current = { x: e.clientX, y: e.clientY };

        // Capture pointer so we keep receiving events even if cursor leaves the div
        (e.target as Element).setPointerCapture(e.pointerId);

        // Change cursor to grabbing
        if (btContainerRef.current) btContainerRef.current.style.cursor = 'grabbing';
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (isDraggingBT.current && lastMousePos.current) {
            e.preventDefault();
            e.stopPropagation();

            const dx = e.clientX - lastMousePos.current.x;
            const dy = e.clientY - lastMousePos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastMousePos.current = { x: e.clientX, y: e.clientY };
        }
    };

    const handlePointerUp = (e: React.PointerEvent) => { 
        if (isDraggingBT.current) {
            isDraggingBT.current = false; 
            lastMousePos.current = null;

            (e.target as Element).releasePointerCapture(e.pointerId);

            // Restore cursor
            if (btContainerRef.current) btContainerRef.current.style.cursor = 'grab';
        }
    };

    return (
        <div 
            className="flex-1 relative overflow-hidden flex flex-col min-h-0 w-full h-full cursor-grab active:cursor-grabbing select-none" 
            ref={btContainerRef} 
            onWheel={handleBtWheel} 
            onPointerDown={handlePointerDown} 
            onPointerMove={handlePointerMove} 
            onPointerUp={handlePointerUp}
            // onPointerLeave is not needed because we use setPointerCapture
            style={{ touchAction: 'none' }}
        >
            {/* UI Overlay - Minimal for embedded view */}
            <div className="absolute top-2 right-2 z-20 px-2 py-1 text-[9px] font-mono text-slate-500 bg-black/40 rounded border border-white/5 pointer-events-none">
                {Math.round(btScale * 100)}%
            </div>

            {/* Content Layer */}
            <div 
                className="absolute inset-0 w-full h-full flex justify-center items-start origin-top will-change-transform pointer-events-none"
                style={{
                    transform: `translate(${btPos.x}px, ${btPos.y}px) scale(${btScale})`, 
                    // No background color here to allow game to show through
                }}
            >
                <div className="inline-block min-w-max pt-4 pb-20">
                    {agent.bt ? (
                        <TreeNode node={agent.bt} version={version} now={Date.now()} />
                    ) : (
                        <div className="flex flex-col items-center justify-center pt-10 opacity-50">
                            <span className="text-slate-400 font-mono text-xs">NO SIGNAL...</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { BTNode } from '../../../engine/behaviorTree';
import { NodeState } from '../../../types';

interface TreeNodeProps {
    node: BTNode;
    version: number;
    now: number;
}

export const TreeNode: React.FC<TreeNodeProps> = ({ node, version, now }) => {
    // Logic for Visual Persistence
    const timeDiff = now - node.lastRunTime;
    let visualState: NodeState | null = node.status;
    let isFading = false;
    let opacity = 1.0;

    if (!visualState && node.lastResult) {
        if (timeDiff < 1000) { 
            visualState = node.lastResult;
            isFading = true;
            if (timeDiff > 200) opacity = 0.7;
            if (timeDiff > 500) opacity = 0.4;
        }
    }

    const statusStyle = (s: NodeState | null) => {
        switch (s) {
            case NodeState.RUNNING: return "border-amber-500/80 bg-amber-950/80 text-amber-100 shadow-[0_0_20px_rgba(245,158,11,0.4)] ring-1 ring-amber-400 animate-pulse-glow z-10 scale-105";
            case NodeState.SUCCESS: return "border-emerald-500/50 bg-emerald-950/60 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]";
            case NodeState.FAILURE: return "border-red-800/50 bg-red-950/60 text-red-200 opacity-60";
            default: return "border-slate-700 bg-slate-800/80 text-slate-500 backdrop-blur-sm";
        }
    };

    const typeSymbol = (t: string) => {
        if(t === '?') return <span className="text-purple-400 font-bold mr-3 text-xl drop-shadow-md">?</span>;
        if(t === '->') return <span className="text-blue-400 font-bold mr-3 text-xl drop-shadow-md">➜</span>;
        if(t === 'COND') return <span className="text-pink-400 text-base mr-3 font-bold">◆</span>;
        if(t === 'ACT') return <span className="text-yellow-400 text-base mr-3 font-bold">⚡</span>;
        return null;
    }

    return (
        <div className="flex flex-col items-center">
            <div 
                className={`flex items-center px-6 py-4 rounded-2xl border transition-all duration-200 cursor-default select-none min-w-[160px] justify-center backdrop-blur-md ${statusStyle(visualState)}`}
                style={{ opacity: opacity }}
            >
                {typeSymbol(node.type)}
                <span className="whitespace-nowrap truncate max-w-[200px] font-bold text-sm tracking-wider font-mono">{node.n}</span>
            </div>
            {node.c && node.c.length > 0 && (
                <div className="flex flex-col items-center">
                    <div className={`w-px h-8 ${isFading ? 'bg-slate-600/30' : 'bg-slate-600/60'}`}></div>
                    <div className="flex items-start gap-6">
                        {node.c.map((child, idx) => (
                            <div key={child.id} className="flex flex-col items-center relative">
                                {/* Connector Lines */}
                                <div className="absolute top-0 left-0 w-full h-8 -mt-8 pointer-events-none">
                                     {node.c.length > 1 && (
                                         <>
                                            {idx === 0 && <div className="absolute right-0 top-0 w-1/2 h-px bg-slate-600/60 translate-y-8"></div>}
                                            {idx === node.c.length - 1 && <div className="absolute left-0 top-0 w-1/2 h-px bg-slate-600/60 translate-y-8"></div>}
                                            {idx > 0 && idx < node.c.length - 1 && <div className="absolute left-0 top-0 w-full h-px bg-slate-600/60 translate-y-8"></div>}
                                         </>
                                     )}
                                     <div className="absolute left-1/2 top-0 w-px h-8 bg-slate-600/60 translate-y-8 -translate-x-1/2"></div>
                                </div>

                                <div className="pt-8">
                                    <TreeNode node={child} version={version} now={now} />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

import { Agent, GameEngine } from "../game";
import { Camera } from "../renderer"; 
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { Team, Role } from "../../types";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";

export interface RenderCamera {
    x: number;
    y: number;
    zoom: number;
}

const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class TacticalRenderer {
    // Hologram Glitch State
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    public update(dt: number, engine: GameEngine) {
        // Hologram Glitch Logic
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; // Trigger glitch for 0.3s
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;
    }

    public drawOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null, grid: GridSystem, globalTime: number) {
        ctx.save();

        // A. Selection Bracket (REMOVED: Replaced by HUD Highlight)

        // B. Selected Agent Details (Path & Targets)
        if (highlight && highlight.hp > 0) {
            const hH = grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; // Waist height

            // 1. Movement Trajectory
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);

                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = grid.getTerrainHeight(hex.q, hex.r, engine);
                    ctx.lineTo(p.x, p.y - h - 30);
                });

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); // Dashed Line
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); // Reset
                ctx.globalAlpha = 1.0;

                // Destination Marker
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = grid.getTerrainHeight(dest.q, dest.r, engine);

                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }

            // 2. Target Line
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = grid.getTerrainHeight(t.q, t.r, engine);
                const endPx = t.px;
                const endPy = t.py - tH - 30;

                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';

                grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade out near source
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);

                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);

                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(globalTime * 10) * 0.2; // Pulse
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }

        ctx.restore();
    }

    public drawHUD(ctx: CanvasRenderingContext2D, engine: GameEngine, w: number, h: number, cam: RenderCamera, globalTime: number) {
        if (!engine.directorTargetId) return;
        const agent = engine.agents.find(a => a.id === engine.directorTargetId);
        if (!agent) return;

        // Position: Top Right
        const width = 260;
        const height = 140;
        const hudX = w - width - 20;
        const hudY = 20;

        ctx.save();

        // Glitch logic (Keep existing if any)
        let gx = 0, gy = 0;
        if (this.holoGlitchTimer > 0) {
             gx = (Math.random() - 0.5) * 5;
             gy = (Math.random() - 0.5) * 5;
        }
        ctx.translate(hudX + gx, hudY + gy);

        const teamColor = agent.team === Team.BLUE ? '#06b6d4' : '#ef4444'; // Cyan / Red

        // --- BACKGROUND (Liquid Glass) ---
        // Rounded Rect
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(0, 0, width, height, 16);
        else ctx.rect(0, 0, width, height);

        // Fill
        const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
        bgGrad.addColorStop(0, 'rgba(15, 23, 42, 0.8)'); // Slate-900
        bgGrad.addColorStop(1, 'rgba(15, 23, 42, 0.5)');
        ctx.fillStyle = bgGrad;
        ctx.fill();

        // Border & Glow
        ctx.shadowColor = teamColor;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = teamColor;
        ctx.lineWidth = 1.5;
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Inner Highlight
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(1, 1, width-2, height-2, 16);
        else ctx.rect(1, 1, width-2, height-2);
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 1;
        ctx.stroke();

        // --- CONTENT ---
        ctx.fillStyle = teamColor;
        ctx.font = 'bold 13px "JetBrains Mono", monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`TARGET: ${agent.id}`, 20, 30);

        ctx.fillStyle = '#94a3b8'; // Slate-400
        ctx.font = '11px "JetBrains Mono", monospace';
        ctx.fillText(`STATUS:`, 20, 50);

        ctx.fillStyle = '#f8fafc'; // Slate-50
        ctx.fillText(agent.btStatus || 'IDLE', 70, 50);

        // --- PIPELINE GRAPH ---
        const startX = 50;
        const startY = 90;
        const gap = 80;
        const nodes = [
            { label: 'SCAN', active: true },
            { label: 'THINK', active: agent.btStatus !== '待機' && agent.btStatus !== 'IDLE' },
            { label: 'ACT', active: agent.isMoving || agent.castingSkillIdx !== -1 }
        ];

        // Connecting Line
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(startX + gap * 2, startY);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Active Line Progress
        if (nodes[1].active) {
            const t = (globalTime * 2) % 1;
            const flowX = startX + t * (gap * 2);
            ctx.beginPath();
            ctx.arc(flowX, startY, 2, 0, Math.PI*2);
            ctx.fillStyle = '#fff';
            ctx.fill();
        }

        nodes.forEach((n, i) => {
            const x = startX + i * gap;

            // Node Circle
            ctx.beginPath();
            ctx.arc(x, startY, 8, 0, Math.PI*2);

            if (n.active) {
                ctx.fillStyle = teamColor;
                ctx.shadowColor = teamColor;
                ctx.shadowBlur = 10;
                ctx.fill();
                ctx.shadowBlur = 0;

                // White Core
                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(x, startY, 3, 0, Math.PI*2); ctx.fill();
            } else {
                ctx.fillStyle = '#1e293b'; // Slate-800
                ctx.strokeStyle = '#475569';
                ctx.lineWidth = 2;
                ctx.fill();
                ctx.stroke();
            }

            // Label
            ctx.font = 'bold 10px "JetBrains Mono", monospace';
            ctx.textAlign = 'center';
            ctx.fillStyle = n.active ? '#fff' : '#64748b';
            ctx.fillText(n.label, x, startY + 20);
        });

        ctx.restore();
    }

    public drawDebug(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 44; // Slightly wider for liquid look
const BAR_HEIGHT = 6; // Thicker for better gradient
const BAR_PADDING = 3;

interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 
}

export class HUDSystem {
    // Active Texts
    damageNumbers: FloatingText[] = [];

    // Memory Pool
    private pool: FloatingText[] = [];

    constructor() {
        // Pre-allocate pool
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false
        };
    }

    public addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        // UX FIX: Prevent Kill Streak Overlap
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; // Ults float very slowly
                life = 2.5; // Stay longer
                size = 24; // Bigger font
            } else {
                vy = -20; // Normal skills float gently
                life = 1.2;
                size = 14; // Smaller to be less intrusive
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; // Stay very long
            size = 32; // HUGE
        } else {
            // DAMAGE / HEAL
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; // Initial jump
        }

        // Get from pool
        let ft: FloatingText;
        if (this.pool.length > 0) {
            ft = this.pool.pop()!;
        } else {
            ft = this.createEmpty();
        }

        // Init
        ft.active = true;
        ft.x = x; ft.y = y;
        ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;

        this.damageNumbers.push(ft);
    }

    private release(ft: FloatingText) {
        ft.active = false;
        this.pool.push(ft);
    }

    update(dt: number) {
        // Reverse iterate to allow removal
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            // Physics integration
            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            // Gravity logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; // Friction
            } else if (d.type === 'KILL_STREAK') {
                d.vy *= 0.92; // Anti-gravity float
            }

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); // Fast remove from active list
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        // 1. Draw HP/MP Bars & Status Labels
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            // Determine Ground Level Logic
            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            this.drawUnitBars(ctx, a, headX, anchorY, isSelected, time);
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        // 2. Draw Floating Text
        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH'; gaugeColor = '#d8b4fe';
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS'; gaugeColor = '#facc15';
            } else {
                iconType = 'BANISH'; gaugeColor = '#7e22ce';
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN'; gaugeColor = '#fbbf24';
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE'; gaugeColor = '#94a3b8';
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean, time: number) {
        // --- LIQUID GLASS DESIGN ---
        const hasMp = agent.maxMp > 0;

        // Dimensions
        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; // Slight offset upwards

        // 1. Glass Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(startX, startY, totalW, totalH, 6);
        } else {
            ctx.rect(startX, startY, totalW, totalH); // Fallback
        }

        // Glass Material
        ctx.fillStyle = 'rgba(2, 6, 23, 0.6)'; // Slate-950 semi-transparent
        ctx.fill();

        // Rim Light
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.stroke();

        // Selection Pulse
        if (isSelected) {
            const pulse = 0.5 + Math.sin(time * 8) * 0.3;
            ctx.shadowColor = 'rgba(6, 182, 212, 0.8)'; // Cyan Glow
            ctx.shadowBlur = 10 + pulse * 5;
            ctx.strokeStyle = `rgba(6, 182, 212, ${0.4 + pulse * 0.4})`;
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        // Helper for Fluid Bars
        const drawFluidBar = (bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string, glow: string) => {
            if (pct <= 0.01) return;
            const fillW = Math.max(bh, bw * pct); // Keep capsule shape even when low

            ctx.save();
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, bh/2);
            else ctx.rect(bx, by, fillW, bh);

            // Liquid Gradient
            const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
            grad.addColorStop(0, colTop);
            grad.addColorStop(1, colBot);
            ctx.fillStyle = grad;

            // Inner Glow (Neon Core)
            ctx.shadowColor = glow;
            ctx.shadowBlur = 6;
            ctx.fill();
            ctx.shadowBlur = 0;

            // Surface Reflection (Glossy Top)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, bh/2);
            else ctx.rect(bx, by, fillW, bh * 0.4);
            ctx.fill();

            ctx.restore();
        };

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // 2. HP Bar
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        // Emerald Fluid
        drawFluidBar(barX, barY, contentW, hpHeight, hpPct, '#6ee7b7', '#10b981', 'rgba(16, 185, 129, 0.5)');

        // 3. MP Bar
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            // Cyan Fluid
            drawFluidBar(barX, mpY, contentW, mpHeight, mpPct, '#7dd3fc', '#0ea5e9', 'rgba(14, 165, 233, 0.5)');
        }
    }

    private drawCircularGauge(ctx: CanvasRenderingContext2D, x: number, y: number, pct: number, visualKey: string, color: string, isSkill: boolean) {
        const radius = 14;
        const iconY = y - 24; // Lifted slightly higher to clear the new glass HUD

        ctx.save();
        // Glass Background for Icon
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(2, 6, 23, 0.8)';
        ctx.fill();
        ctx.save();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        // Icon Opacity
        ctx.globalAlpha = 0.8;
        if (icon) ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        ctx.restore();

        // Rim
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Progress Ring (Neon)
        const safePct = Math.max(0, Math.min(1, pct));
        if (safePct > 0) {
            ctx.beginPath();
            // Start from top (-PI/2)
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    // Add significant padding for the "Cinema Mode" backdrop
                    const w = textMetrics.width / 2 + 25;
                    const h = d.size + 12;

                    // --- ULT BACKGROUND (Liquid Glass Banner) ---
                    // Dark center, transparent edges to avoid harsh cutoffs
                    const bgGrad = ctx.createLinearGradient(-w - 20, 0, w + 20, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.3, 'rgba(2, 6, 23, 0.85)'); // Slate-950
                    bgGrad.addColorStop(0.7, 'rgba(2, 6, 23, 0.85)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                    // --- NEON ACCENTS (Top/Bottom Lines) ---
                    ctx.strokeStyle = d.color;
                    ctx.lineWidth = 2;
                    ctx.globalAlpha = alpha * 0.8;

                    ctx.beginPath();
                    ctx.moveTo(-w, -h/2); ctx.lineTo(w, -h/2); // Top Line
                    ctx.stroke();

                    ctx.beginPath();
                    ctx.moveTo(-w * 0.8, h/2); ctx.lineTo(w * 0.8, h/2); // Bottom Line (Shorter)
                    ctx.stroke();

                    ctx.globalAlpha = alpha;

                    // --- TEXT ---
                    ctx.shadowColor = d.color;
                    ctx.shadowBlur = 15;
                    ctx.fillStyle = '#fff';
                    ctx.fillText(d.text, 0, 0);

                    // Subtle stroke for clarity against bright VFX
                    ctx.shadowBlur = 0;
                    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
                    ctx.lineWidth = 3;
                    ctx.strokeText(d.text, 0, 0);
                    ctx.fillText(d.text, 0, 0);

                    ctx.restore();
                } else {
                    // --- ACTIVE SKILL (Pill Glass) ---
                    ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const padX = 12;
                    const padY = 6;
                    const w = textMetrics.width;
                    const h = d.size;

                    // Dark Frosted Capsule Background
                    // Ensures visibility on dark maps and light maps alike
                    ctx.fillStyle = 'rgba(15, 23, 42, 0.75)'; // Slate-900 semi-transparent
                    ctx.beginPath();
                    if (ctx.roundRect) {
                        ctx.roundRect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2, 8);
                    } else {
                        ctx.rect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2);
                    }
                    ctx.fill();

                    // Subtle Rim
                    ctx.strokeStyle = `rgba(255,255,255,0.15)`;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    // Text with colored glow
                    ctx.shadowColor = d.color;
                    ctx.shadowBlur = 8;
                    ctx.fillStyle = '#fff'; // White text always pops on dark pill
                    ctx.fillText(d.text, d.x, d.y);
                    ctx.shadowBlur = 0;
                }

            } else if (d.type === 'CC') {
                ctx.font = `900 ${d.size}px "Arial Black", sans-serif`; 
                ctx.strokeStyle = 'rgba(0,0,0,1.0)';
                ctx.lineWidth = 3;
                ctx.strokeText(d.text, d.x, d.y);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, d.x, d.y);

            } else {
                ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                ctx.fillStyle = d.color; 
                ctx.strokeStyle = 'rgba(0,0,0,0.8)'; 
                ctx.lineWidth = 3; 
                ctx.strokeText(d.text, d.x, d.y); 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

